window.BANQUE = [{"id":"marche-particuliers:test:0","m":"marche-particuliers","ch":"Panorama","l":"l1","type":"qcm","q":"Quel est le taux de bancarisation en France ?","opts":["Environ 80 %","Environ 90 %","Plus de 99 %","Environ 70 %"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le taux de bancarisation dépasse 99 % en France, l'un des plus élevés au monde."},{"id":"marche-particuliers:test:1","m":"marche-particuliers","ch":"Panorama","l":"l1","type":"qcm","q":"Quel écart illustre le mieux la différence entre notoriété et confiance dans l'étude IFOP ?","opts":["Le paiement sans contact par téléphone : 93 % → 55 %","Le Livret A : 83 % → 83 %","Le crédit immo : 29,7 % → 29,7 %","Le DAV : 100 % → 100 %"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Le paiement sans contact par téléphone est connu à 93 % mais utilisé en confiance par seulement 55 % des Français."},{"id":"marche-particuliers:test:2","m":"marche-particuliers","ch":"Crédit","l":"l2","type":"num","q":"Quelle part de sinistralité concerne les crédits accordés en France ? (en %)","opts":null,"correct":null,"answer":1.1,"tol":0.1,"unit":"%","ex":"Seuls 1,1 % des crédits sont en sinistralité, malgré 42 % des Français endettés."},{"id":"marche-particuliers:test:3","m":"marche-particuliers","ch":"Crédit","l":"l2","type":"qcm","q":"Quel est le niveau actuel des taux de crédit, contre 0-1 % en 2021 ?","opts":["Entre 1 % et 2 %","Entre 2 % et 3 %","Entre 3,80 % et 3,90 %","Plus de 5 %"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Les taux de crédit se situent aujourd'hui entre 3,80 % et 3,90 %, contre 0-1 % en 2021."},{"id":"marche-particuliers:test:4","m":"marche-particuliers","ch":"Épargne : fondamentaux","l":"l3","type":"qcm","q":"Le revenu disponible brut inclut…","opts":["Uniquement le salaire net","Salaires + revenus du patrimoine + prestations sociales, moins IR et PS","Uniquement les prestations sociales","Le seul patrimoine financier"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le revenu disponible brut = revenus primaires (salaires, indépendants, patrimoine) + prestations sociales - IR - PS."},{"id":"marche-particuliers:test:5","m":"marche-particuliers","ch":"Livrets & fiscalité","l":"l4","type":"num","q":"Un client dépose 8 000 € à 1,70 %. Montant d'une quinzaine d'intérêts ? (en €, 2 décimales)","opts":null,"correct":null,"answer":5.67,"tol":0.05,"unit":"€","ex":"8 000 × 1,70 % × 1/24 = 5,67 €. Formule : k × taux annuel × 1/24."},{"id":"marche-particuliers:test:6","m":"marche-particuliers","ch":"Livrets & fiscalité","l":"l4","type":"qcm","q":"Quel est le plafond du Livret A ?","opts":["10 000 €","12 000 €","22 950 €","61 300 €"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le plafond du Livret A est de 22 950 €. LDDS : 12 000 €, LEP : 10 000 €, PEL : 61 300 €."},{"id":"marche-particuliers:test:7","m":"marche-particuliers","ch":"Livrets & fiscalité","l":"l4","type":"qcm","q":"Avant quelle date faut-il demander une dispense d'acompte ?","opts":["Le 31 décembre","Le 30 novembre","Le 15 mai","Le 1er janvier"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La dispense d'acompte doit être demandée avant le 30 novembre pour s'appliquer l'année suivante."},{"id":"marche-particuliers:test:8","m":"marche-particuliers","ch":"Épargne moyen/long terme","l":"l5","type":"qcm","q":"Quel est le plafond de versement du PEA (hors PEA-PME) ?","opts":["75 000 €","92 000 €","150 000 €","225 000 €"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"150 000 € pour le PEA classique, 75 000 € en complément pour le PEA-PME (225 000 € au total)."},{"id":"marche-particuliers:test:9","m":"marche-particuliers","ch":"Épargne moyen/long terme","l":"l5","type":"qcm","q":"Depuis quand le PEP n'est-il plus commercialisé ?","opts":["2003","2010","2018","2021"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Le PEP (plan d'épargne populaire) a cessé d'être commercialisé en 2003."},{"id":"marche-particuliers:test:10","m":"marche-particuliers","ch":"Assurance vie","l":"l6","type":"num","q":"Montant exonéré par bénéficiaire en cas de décès (en €)","opts":null,"correct":null,"answer":152500,"tol":0,"unit":"€","ex":"152 500 € sont exonérés par bénéficiaire, puis 20 % jusqu'à 852 500 €, puis 31,25 % au-delà."},{"id":"marche-particuliers:test:11","m":"marche-particuliers","ch":"Assurance vie","l":"l6","type":"qcm","q":"Après 8 ans et sous 150 k€ d'encours, quel est l'abattement annuel par personne ?","opts":["3 000 €","4 600 €","9 200 €","152 500 €"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"4 600 € par personne (9 200 € pour un couple), puis 7,5 % + PS."},{"id":"marche-particuliers:test:12","m":"marche-particuliers","ch":"Le PER","l":"l7","type":"qcm","q":"En sortie en capital, comment est imposé le capital versé (versements déductibles) ?","opts":["PFU 31,4 %","IR sans abattement","Exonéré","IR après abattement"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le capital versé est soumis à l'IR sans abattement ; ce sont les plus-values qui subissent le PFU à 31,4 %."},{"id":"marche-particuliers:test:13","m":"marche-particuliers","ch":"Gestion de portefeuille","l":"l8","type":"qcm","q":"La SICAV est juridiquement…","opts":["Une copropriété sans personnalité morale","Une société anonyme","Une association","Un mandat de gestion"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La SICAV est une société anonyme. Le FCP, lui, est une copropriété de valeurs mobilières sans personnalité morale."},{"id":"marche-particuliers:test:14","m":"marche-particuliers","ch":"Le crédit : cadre légal","l":"l9","type":"num","q":"Délai de rétractation d'un crédit à la consommation (en jours)","opts":null,"correct":null,"answer":14,"tol":0,"unit":"jours","ex":"14 jours de rétractation à compter de l'acceptation de l'offre. À ne pas confondre avec les 7 jours de mise à disposition des fonds."},{"id":"marche-particuliers:test:15","m":"marche-particuliers","ch":"Le crédit : cadre légal","l":"l9","type":"qcm","q":"Quelle loi vise à lutter contre le surendettement ?","opts":["La loi Hamon","La loi Lagarde","La loi Neiertz","La loi Badinter"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"La loi Neiertz lutte contre le surendettement selon 3 orientations : prévention, procédure de règlement, responsabilisation."},{"id":"marche-particuliers:test:16","m":"marche-particuliers","ch":"Les garanties","l":"l10","type":"qcm","q":"L'hypothèque est une garantie…","opts":["Personnelle","Réelle","Mutuelle","Assurantielle"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'hypothèque (comme le PPD et le nantissement) est une garantie réelle : elle porte sur un bien. La caution est personnelle."},{"id":"marche-particuliers:test:17","m":"marche-particuliers","ch":"Assurances & RC","l":"l11","type":"qcm","q":"Quels sont les trois caractères de la force majeure ?","opts":["Grave, soudain, coûteux","Imprévisible, irrésistible, extérieur","Direct, certain, personnel","Volontaire, fautif, réparable"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Imprévisible, irrésistible et extérieur — les trois doivent être réunis simultanément pour exonérer."},{"id":"marche-particuliers:test:18","m":"marche-particuliers","ch":"Assurances & RC","l":"l11","type":"qcm","q":"La loi Badinter concerne…","opts":["Le surendettement des ménages","L'indemnisation des victimes d'accidents de la circulation","La reconduction tacite des contrats","Le taux d'usure"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La loi Badinter améliore l'indemnisation des victimes d'accidents de la circulation ; la faute de la victime y est rarement admise."},{"id":"marche-particuliers:quiz:l1:0","m":"marche-particuliers","ch":"Leçon 1 — La banque des particuliers aujourd'hui","l":"l1","type":"qcm","q":"Quel est le principal canal de contact des clients avec leur banque, selon l'étude IFOP ?","opts":["Le téléphone","Le mail","Le courrier"],"correct":1,"ex":"Exact. Le mail est le principal mode de contact, l'agence restant fréquentée en physique et en web."},{"id":"marche-particuliers:quiz:l1:1","m":"marche-particuliers","ch":"Leçon 1 — La banque des particuliers aujourd'hui","l":"l1","type":"qcm","q":"Quelle part des Français veut une banque qui répond à la fois en ligne et en agence ?","opts":["13 %","52 %","78 %"],"correct":2,"ex":"Bien vu. 78 % des Français attendent un modèle phygital ; seuls 13 % veulent une agence uniquement physique et 9 % une banque 100 % digitale."},{"id":"marche-particuliers:quiz:l2:0","m":"marche-particuliers","ch":"Leçon 2 — Le financement et le crédit","l":"l2","type":"qcm","q":"Sur quelle base la banque accorde-t-elle un crédit en France ?","opts":["Sur la seule ancienneté bancaire du client","Sur la capacité de remboursement de l'emprunteur","Sur la valeur du bien financé uniquement"],"correct":1,"ex":"Exact. C'est la capacité de remboursement qui fonde l'octroi ; les garanties (caution, assurance) viennent en complément."},{"id":"marche-particuliers:quiz:l2:1","m":"marche-particuliers","ch":"Leçon 2 — Le financement et le crédit","l":"l2","type":"qcm","q":"Quelle est la part de crédits immobiliers à taux fixe en France ?","opts":["51,9 %","97 %","29,7 %"],"correct":1,"ex":"Bien vu. 97 % des crédits immo sont à taux fixe ; 51,9 % concernent des primo-accédants et 29,7 % des Français détiennent un crédit immo."},{"id":"marche-particuliers:quiz:l3:0","m":"marche-particuliers","ch":"Leçon 3 — L'épargne : les fondamentaux","l":"l3","type":"qcm","q":"Quel est le taux d'épargne financière des Français ?","opts":["18 %","9 %","4 %"],"correct":1,"ex":"Exact. Le taux d'épargne global est de 18 %, dont 9 % de taux d'épargne financière."},{"id":"marche-particuliers:quiz:l3:1","m":"marche-particuliers","ch":"Leçon 3 — L'épargne : les fondamentaux","l":"l3","type":"qcm","q":"Que désigne l'Euribor ?","opts":["Le taux interbancaire à 1 jour","Le taux interbancaire de 1 mois à 1 an","Le taux des obligations d'État"],"correct":1,"ex":"Bien vu. L'ESTER couvre le 1 jour, l'Euribor le 1 mois à 1 an, l'OAT finance la dette de l'État."},{"id":"marche-particuliers:quiz:l4:0","m":"marche-particuliers","ch":"Leçon 4 — Les livrets réglementés et leur fiscalité","l":"l4","type":"qcm","q":"Un client dépose 6 000 € sur un livret à 2,00 %. Quel est le montant d'une quinzaine d'intérêts ?","opts":["10,00 €","5,00 €","2,50 €"],"correct":1,"ex":"Exact. 6 000 × 2,00 % × 1/24 = 5,00 €."},{"id":"marche-particuliers:quiz:l4:1","m":"marche-particuliers","ch":"Leçon 4 — Les livrets réglementés et leur fiscalité","l":"l4","type":"qcm","q":"En 2026, quelle est la flat-tax applicable aux intérêts d'un DAT ?","opts":["30 % (12,8 + 17,2)","31,4 % (12,8 + 18,6)","17,2 % seulement"],"correct":1,"ex":"Bien vu. Depuis la LFSS 2026, les PS sont à 18,6 % au cas général. Seuls l'assurance vie, le PEL, le CEL et le PEP restent à 17,2 %, donc à 30 % de flat-tax."},{"id":"marche-particuliers:quiz:l5:0","m":"marche-particuliers","ch":"Leçon 5 — L'épargne à moyen et long terme","l":"l5","type":"qcm","q":"Depuis quand la prime d'État n'existe-t-elle plus sur les nouveaux PEL ?","opts":["2003","01/01/2018","2021"],"correct":1,"ex":"Exact. Les PEL ouverts après le 1er janvier 2018 n'ouvrent plus droit à la prime d'État."},{"id":"marche-particuliers:quiz:l5:1","m":"marche-particuliers","ch":"Leçon 5 — L'épargne à moyen et long terme","l":"l5","type":"qcm","q":"Quel est le plafond de versement du PEA, hors PEA-PME ?","opts":["75 000 €","150 000 €","92 000 €"],"correct":1,"ex":"Bien vu. 150 000 € pour le PEA classique, 75 000 € en complément pour le PEA-PME."},{"id":"marche-particuliers:quiz:l6:0","m":"marche-particuliers","ch":"Leçon 6 — L'assurance vie, le couteau suisse du patrimoine","l":"l6","type":"qcm","q":"Quel montant est exonéré par bénéficiaire en cas de décès ?","opts":["70 000 €","152 500 €","852 500 €"],"correct":1,"ex":"Exact. 152 500 € exonérés, puis 20 % jusqu'à 852 500 €, puis 31,25 %. Les 70 000 € correspondent au FGAP."},{"id":"marche-particuliers:quiz:l6:1","m":"marche-particuliers","ch":"Leçon 6 — L'assurance vie, le couteau suisse du patrimoine","l":"l6","type":"qcm","q":"Sur un fonds en euros, quand les prélèvements sociaux sont-ils prélevés ?","opts":["Chaque année au 31/12","À la sortie ou au rachat","Au bout de 8 ans"],"correct":0,"ex":"Bien vu. Fonds € : PS au 31/12 chaque année. UC : PS à la sortie ou au rachat."},{"id":"marche-particuliers:quiz:l7:0","m":"marche-particuliers","ch":"Leçon 7 — Le PER : déduire aujourd'hui, être imposé demain","l":"l7","type":"qcm","q":"Quel pourcentage du revenu imposable peut-on verser en déduction sur un PER ?","opts":["5 %","10 %","20 %"],"correct":1,"ex":"Exact. 10 % du revenu imposable, avec possibilité de rattrapage sur les 5 dernières années."},{"id":"marche-particuliers:quiz:l7:1","m":"marche-particuliers","ch":"Leçon 7 — Le PER : déduire aujourd'hui, être imposé demain","l":"l7","type":"qcm","q":"En cas de sortie en rente viagère, quel taux de prélèvements sociaux s'applique ?","opts":["17,2 %","18,6 %","31,4 %"],"correct":1,"ex":"Bien vu. La rente est soumise à l'IR après abattement, plus 18,6 % de PS. Les 31,4 % correspondent au PFU sur les plus-values en sortie capital."},{"id":"marche-particuliers:quiz:l8:0","m":"marche-particuliers","ch":"Leçon 8 — Gestion individualisée ou collective ?","l":"l8","type":"qcm","q":"Dans une gestion conseillée, qui prend la décision finale d'investissement ?","opts":["La société de gestion","Le client","L'AMF"],"correct":1,"ex":"Exact. En gestion conseillée, la société propose, le client reste libre d'accepter ou non. Sous mandat, c'est la société qui décide."},{"id":"marche-particuliers:quiz:l8:1","m":"marche-particuliers","ch":"Leçon 8 — Gestion individualisée ou collective ?","l":"l8","type":"qcm","q":"Quelle est la forme juridique d'un FCP ?","opts":["Une société anonyme","Une copropriété de valeurs mobilières sans personnalité morale","Une association"],"correct":1,"ex":"Bien vu. Le FCP est une copropriété sans personnalité morale ; c'est la SICAV qui est une société anonyme."},{"id":"marche-particuliers:quiz:l9:0","m":"marche-particuliers","ch":"Leçon 9 — Le cadre légal du crédit","l":"l9","type":"qcm","q":"Quelle est la fourchette d'un crédit à la consommation au sens de la loi Lagarde ?","opts":["De 0 à 50 000 €","De 200 € à 75 000 €","De 1 000 € à 100 000 €"],"correct":1,"ex":"Exact. Le crédit conso est compris entre 200 € et 75 000 € au sens de la LCC."},{"id":"marche-particuliers:quiz:l9:1","m":"marche-particuliers","ch":"Leçon 9 — Le cadre légal du crédit","l":"l9","type":"qcm","q":"Qui calcule le taux d'usure, et à quelle fréquence ?","opts":["L'AMF, chaque année","La Banque de France, chaque trimestre","La BCE, chaque mois"],"correct":1,"ex":"Bien vu. Le taux d'usure est calculé trimestriellement par la Banque de France : c'est le TAEG maximum autorisé."},{"id":"marche-particuliers:quiz:l10:0","m":"marche-particuliers","ch":"Leçon 10 — Les garanties du crédit","l":"l10","type":"qcm","q":"Le nantissement se caractérise par…","opts":["La dépossession immédiate du bien","Une garantie sur un bien dont le débiteur n'est pas dépossédé","Un engagement d'un tiers de payer à la place du débiteur"],"correct":1,"ex":"Exact. Le nantissement laisse le bien à la disposition du débiteur ; la troisième proposition décrit la caution."},{"id":"marche-particuliers:quiz:l10:1","m":"marche-particuliers","ch":"Leçon 10 — Les garanties du crédit","l":"l10","type":"qcm","q":"Que signifie PPD ?","opts":["Hypothèque légale spéciale du prêteur de deniers","Prêt à paiement différé","Plan de prévention des dettes"],"correct":0,"ex":"Bien vu. Le PPD est l'hypothèque légale spéciale du prêteur de deniers, une garantie réelle."},{"id":"marche-particuliers:quiz:l11:0","m":"marche-particuliers","ch":"Leçon 11 — Les assurances et la responsabilité civile","l":"l11","type":"qcm","q":"Que recouvre le moyen mnémotechnique D.U.C. ?","opts":["Dommage, Usage, Causalité","Direction, Usage, Contrôle","Défaut, Utilisation, Charge"],"correct":1,"ex":"Exact. Direction, Usage, Contrôle : les trois éléments permettant de faire jouer la responsabilité civile."},{"id":"marche-particuliers:quiz:l11:1","m":"marche-particuliers","ch":"Leçon 11 — Les assurances et la responsabilité civile","l":"l11","type":"qcm","q":"Quels sont les trois caractères de la force majeure ?","opts":["Grave, soudain, coûteux","Imprévisible, irrésistible, extérieur","Volontaire, direct, réparable"],"correct":1,"ex":"Bien vu. Les trois caractères doivent être réunis simultanément pour que la force majeure exonère."},{"id":"produits-derives:quiz:l1:0","m":"produits-derives","ch":"Leçon 1 — Le marché des changes : poids et géographie","l":"l1","type":"qcm","q":"Quelle place financière occupe le premier rang sur le marché des changes ?","opts":["New York","Londres","Tokyo"],"correct":1,"ex":"Exact. Londres dépasse 30 % des transactions, devant New York (≈ 16 %) et Tokyo (≈ 9 %)."},{"id":"produits-derives:quiz:l1:1","m":"produits-derives","ch":"Leçon 1 — Le marché des changes : poids et géographie","l":"l1","type":"qcm","q":"Les 88 % de l'USD s'apprécient par rapport à…","opts":["100 %","200 %","50 %"],"correct":1,"ex":"Bien vu. Une transaction met en jeu deux monnaies : le total fait 200 %. Le poids relatif réel de l'USD est donc d'environ 44 %."},{"id":"produits-derives:quiz:l2:0","m":"produits-derives","ch":"Leçon 2 — Qui intervient sur le marché des changes ?","l":"l2","type":"qcm","q":"Un courtier (broker) sur le marché des changes…","opts":["Prend des positions de change pour son propre compte","Est un simple intermédiaire qui ne prend aucune position de change","Fixe les cours de référence du marché"],"correct":1,"ex":"Exact. Le courtier n'intervient jamais pour son propre compte. Ce sont les market makers qui fixent les cours de référence."},{"id":"produits-derives:quiz:l2:1","m":"produits-derives","ch":"Leçon 2 — Qui intervient sur le marché des changes ?","l":"l2","type":"qcm","q":"Quel est l'intérêt principal, pour un cambiste, de passer par un courtier ?","opts":["Obtenir une commission plus faible","Conserver l'anonymat de ses transactions","Éviter le risque de contrepartie"],"correct":1,"ex":"Bien vu. Le nom de la contrepartie n'est révélé qu'une fois la transaction conclue."},{"id":"produits-derives:quiz:l3:0","m":"produits-derives","ch":"Leçon 3 — Comment circulent réellement les devises","l":"l3","type":"qcm","q":"Le compte nostri enregistre des écritures…","opts":["En devises","En monnaie nationale","Dans les deux, indifféremment"],"correct":0,"ex":"Exact. Nostri = notre compte chez le correspondant étranger, en devises. Lori = leur compte chez nous, en monnaie nationale."},{"id":"produits-derives:quiz:l3:1","m":"produits-derives","ch":"Leçon 3 — Comment circulent réellement les devises","l":"l3","type":"qcm","q":"Quelle est la valeur minimale d'une transaction sur le marché de gros ?","opts":["100 000 USD","1 million de USD","10 millions de USD"],"correct":1,"ex":"Bien vu. 1 million de USD minimum sur le marché de gros, animé par 50 à 80 banques."},{"id":"produits-derives:quiz:l4:0","m":"produits-derives","ch":"Leçon 4 — Couverture, spéculation, arbitrage","l":"l4","type":"qcm","q":"Une entreprise importatrice se trouve typiquement en position…","opts":["Longue, avec un risque de baisse","Courte, avec un risque de hausse","Fermée, sans risque"],"correct":1,"ex":"Exact. L'importateur a des dettes en devises supérieures à ses créances : une hausse du cours alourdirait son décaissement."},{"id":"produits-derives:quiz:l4:1","m":"produits-derives","ch":"Leçon 4 — Couverture, spéculation, arbitrage","l":"l4","type":"qcm","q":"Lorsqu'un agent se couvre sur le marché des changes, le risque de change…","opts":["Disparaît totalement du marché","Est transféré à un autre agent qui accepte de le prendre","Est absorbé par la banque centrale"],"correct":1,"ex":"Bien vu. Le risque ne disparaît pas : il change de porteur, contre l'espérance d'un gain de change."},{"id":"produits-derives:quiz:l5:0","m":"produits-derives","ch":"Leçon 5 — Lire un cours de change","l":"l5","type":"qcm","q":"Dans combien de jours ouvrables a lieu la livraison sur le marché au comptant ?","opts":["Le jour même","Au plus tard 2 jours ouvrables (J+2)","5 jours ouvrables"],"correct":1,"ex":"Exact. Les transactions sont effectuées le jour même au cours au comptant, mais la livraison se fait à J+2."},{"id":"produits-derives:quiz:l5:1","m":"produits-derives","ch":"Leçon 5 — Lire un cours de change","l":"l5","type":"qcm","q":"Le cours GBP/USD = 1,6317 signifie que…","opts":["1 GBP vaut 1,6317 USD","1 USD vaut 1,6317 GBP","1,6317 GBP valent 1 USD"],"correct":0,"ex":"Bien vu. La monnaie au numérateur est celle dont une unité est cotée : 1 GBP = 1,6317 USD."},{"id":"produits-derives:quiz:l6:0","m":"produits-derives","ch":"Leçon 6 — Certain, incertain et double cotation","l":"l6","type":"qcm","q":"En double cotation, le cours acheteur de (B/A) correspond à…","opts":["1 / (A/B)A","1 / (A/B)V","(A/B)A × (A/B)V"],"correct":1,"ex":"Exact. L'inversion croise les cours : l'acheteur devient l'inverse du vendeur. C'est l'erreur classique en examen."},{"id":"produits-derives:quiz:l6:1","m":"produits-derives","ch":"Leçon 6 — Certain, incertain et double cotation","l":"l6","type":"qcm","q":"Dans la cotation USD/CHF = 0,9268, que représente « 0,92 » ?","opts":["La figure","Les points","Le spread"],"correct":0,"ex":"Bien vu. Partie entière + 2 premières décimales = la figure ; le 4e chiffre est le point (pip)."},{"id":"produits-derives:quiz:l7:0","m":"produits-derives","ch":"Leçon 7 — Fabriquer un cours qui n'existe pas","l":"l7","type":"qcm","q":"Comment calcule-t-on le cours croisé acheteur (A/B)A en chaîne ?","opts":["(A/C)A × (C/B)A","(A/C)A × (C/B)V","(A/C)V × (C/B)A"],"correct":0,"ex":"Exact. En chaîne, les acheteurs se multiplient entre eux. L'inversion A/V n'intervient que dans la variante par division."},{"id":"produits-derives:quiz:l7:1","m":"produits-derives","ch":"Leçon 7 — Fabriquer un cours qui n'existe pas","l":"l7","type":"qcm","q":"Pourquoi le USD sert-il de monnaie pivot ?","opts":["Parce qu'il est la devise la plus stable","Parce que toutes les devises sont cotées contre lui, sans l'être entre elles","Parce que la BRI l'impose"],"correct":1,"ex":"Bien vu. C'est sa position centrale dans les cotations, pas sa stabilité, qui en fait le pivot."},{"id":"produits-derives:quiz:l8:0","m":"produits-derives","ch":"Leçon 8 — Arbitrage géographique et triangulaire","l":"l8","type":"qcm","q":"Un arbitrage géographique est possible lorsque…","opts":["Le cours acheteur sur une place dépasse le cours vendeur sur une autre","Les deux places affichent exactement la même cotation","Le spread est identique sur les deux places"],"correct":0,"ex":"Exact. Sans ce recouvrement, l'écart est absorbé par les spreads et l'opération serait perdante."},{"id":"produits-derives:quiz:l8:1","m":"produits-derives","ch":"Leçon 8 — Arbitrage géographique et triangulaire","l":"l8","type":"qcm","q":"Quand vous achetez une devise auprès d'une banque, quel cours subissez-vous ?","opts":["Son cours acheteur","Son cours vendeur","La moyenne des deux"],"correct":1,"ex":"Bien vu. La banque vend au cours vendeur (le plus élevé) et achète au cours acheteur. C'est toujours le sollicité qui impose sa cotation."},{"id":"produits-derives:quiz:l9:0","m":"produits-derives","ch":"Leçon 9 — Le marché des changes à terme","l":"l9","type":"qcm","q":"Quand a lieu le dénouement effectif d'une opération de change à terme ?","opts":["Le jour de la négociation","Le deuxième jour ouvrable après l'échéance (J+2)","Le dernier jour ouvrable du mois de l'échéance"],"correct":1,"ex":"Exact. Le cours, le montant et l'échéance sont fixés le jour de l'accord, mais les fonds circulent à J+2 après l'échéance."},{"id":"produits-derives:quiz:l9:1","m":"produits-derives","ch":"Leçon 9 — Le marché des changes à terme","l":"l9","type":"qcm","q":"Une entreprise couverte à terme profite-t-elle d'une évolution favorable du cours ?","opts":["Oui, la banque lui reverse la différence","Non, l'engagement est ferme et définitif","Oui, si elle dénoue avant l'échéance sans frais"],"correct":1,"ex":"Bien vu. C'est le prix de la certitude : le terme sec ne laisse aucune optionalité, contrairement à une option de change."},{"id":"produits-derives:quiz:l10:0","m":"produits-derives","ch":"Leçon 10 — Cours à terme, report et déport","l":"l10","type":"qcm","q":"GBP/CHF au comptant = 2,3375 et à 3 mois = 2,3405. Que dire de la livre ?","opts":["Elle est en report de 30 points face au franc suisse","Elle est en déport de 30 points face au franc suisse","Elle est au pair"],"correct":0,"ex":"Exact. f > S donc report, et 2,3405 − 2,3375 = 0,0030 = 30 points."},{"id":"produits-derives:quiz:l10:1","m":"produits-derives","ch":"Leçon 10 — Cours à terme, report et déport","l":"l10","type":"qcm","q":"Pourquoi annualise-t-on le report ou le déport ?","opts":["Parce que les points de base ne sont pas une unité officielle","Pour comparer des monnaies et des échéances différentes","Parce que le cours au comptant change tous les jours"],"correct":1,"ex":"Bien vu. Un écart de 7 points à 1 mois et de 12 points à 3 mois ne se comparent qu'une fois ramenés à un taux annuel."},{"id":"produits-derives:quiz:l11:0","m":"produits-derives","ch":"Leçon 11 — Coter en points de swap","l":"l11","type":"qcm","q":"Les points de swap affichés sont « 145 − 139 ». Que faites-vous ?","opts":["Je les retranche du spot : la devise est en déport","Je les ajoute au spot : la devise est en report","J'ajoute le premier et je retranche le second"],"correct":0,"ex":"Exact. 145 > 139 : points acheteurs supérieurs aux points vendeurs, donc déport et soustraction."},{"id":"produits-derives:quiz:l11:1","m":"produits-derives","ch":"Leçon 11 — Coter en points de swap","l":"l11","type":"qcm","q":"Pourquoi le spread doit-il augmenter avec l'échéance ?","opts":["Parce que les taux d'intérêt montent toujours avec la durée","Parce que le risque du cambiste grandit et que les transactions se raréfient","Parce que la réglementation l'impose aux teneurs de marché"],"correct":1,"ex":"Bien vu. Plus l'échéance est lointaine, plus il est difficile de se couvrir : le cambiste élargit sa marge."},{"id":"produits-derives:quiz:l12:0","m":"produits-derives","ch":"Leçon 12 — Le marché des eurodevises","l":"l12","type":"qcm","q":"Un dollar déposé dans une banque à New York est-il un eurodollar ?","opts":["Oui, si le déposant est européen","Non, c'est un dollar : il est dans son pays d'émission","Oui, si la banque est une filiale étrangère"],"correct":1,"ex":"Exact. Seule compte la localisation du dépôt, jamais la nationalité du déposant ou de la banque."},{"id":"produits-derives:quiz:l12:1","m":"produits-derives","ch":"Leçon 12 — Le marché des eurodevises","l":"l12","type":"qcm","q":"Dans la cotation « 2 5/16 − 2 7/16 », que vaut le taux prêteur ?","opts":["2,3125 %","2,4375 %","2,5000 %"],"correct":1,"ex":"Bien vu. Le second taux est le taux prêteur : 2 + 7/16 = 2,4375 %. Le premier, 2 + 5/16 = 2,3125 %, est le taux emprunteur."},{"id":"produits-derives:quiz:l13:0","m":"produits-derives","ch":"Leçon 13 — Risque de change et position de change","l":"l13","type":"qcm","q":"Un exportateur français facture en euros. Est-il exposé au risque de change ?","opts":["Non : la transaction n'est pas libellée en devises","Oui : dès qu'il y a une transaction avec l'étranger","Oui, mais seulement si le paiement est à crédit"],"correct":0,"ex":"Exact. Les trois conditions sont cumulatives : c'est le client étranger qui supporte alors le risque."},{"id":"produits-derives:quiz:l13:1","m":"produits-derives","ch":"Leçon 13 — Risque de change et position de change","l":"l13","type":"qcm","q":"Une position de change longue en USD expose à…","opts":["Une hausse du cours du USD","Une baisse du cours du USD","Rien, la position est couverte par construction"],"correct":1,"ex":"Bien vu. Position longue = on recevra des devises : si elles se déprécient, l'encaissement en monnaie nationale fond. C'est le cas typique de l'exportateur, qui se couvre en vendant à terme."},{"id":"produits-derives:quiz:l14:0","m":"produits-derives","ch":"Leçon 14 — Le cours à terme acheteur","l":"l14","type":"qcm","q":"Pour fabriquer une vente à terme de A contre B, la banque…","opts":["Emprunte A, vend A au comptant contre B, prête B","Emprunte B, achète A au comptant, prête A","Attend l'échéance et achète A au cours du jour"],"correct":0,"ex":"Exact. L'emprunt en A sera remboursé par les devises livrées par le client à l'échéance ; le placement en B servira à le payer."},{"id":"produits-derives:quiz:l14:1","m":"produits-derives","ch":"Leçon 14 — Le cours à terme acheteur","l":"l14","type":"qcm","q":"Le taux d'intérêt sur A est supérieur à celui sur B. La devise A est donc…","opts":["En report par rapport à B","En déport par rapport à B","Au pair par rapport à B"],"correct":1,"ex":"Bien vu. La devise dont le taux d'intérêt est le plus élevé est en déport à terme : c'est ce qui empêche l'arbitrage de taux couvert."},{"id":"produits-derives:quiz:l15:0","m":"produits-derives","ch":"Leçon 15 — Le cours à terme vendeur","l":"l15","type":"qcm","q":"Dans le cours à terme vendeur, quel taux figure au dénominateur ?","opts":["Le taux emprunteur de la monnaie A","Le taux prêteur de la monnaie A","Le taux prêteur de la monnaie B"],"correct":0,"ex":"Exact. La banque prête A : elle le fait au taux auquel le marché emprunte, donc le taux emprunteur de A."},{"id":"produits-derives:quiz:l15:1","m":"produits-derives","ch":"Leçon 15 — Le cours à terme vendeur","l":"l15","type":"qcm","q":"Vos cours à terme donnent un spread plus étroit qu'au comptant. Que se passe-t-il ?","opts":["C'est normal si la devise est en déport","Il y a une erreur : un taux a été inversé","C'est normal pour les échéances courtes"],"correct":1,"ex":"Bien vu. Le spread s'élargit toujours avec l'échéance : un spread qui se resserre signale une erreur de taux ou de sens."},{"id":"produits-derives:test:0","m":"produits-derives","ch":"Introduction","l":"l1","type":"qcm","q":"Quel est le volume quotidien des transactions sur le marché des changes (BRI, 2023) ?","opts":["510 milliards USD","1 500 milliards USD","5 100 milliards USD","25 000 milliards USD"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Environ 5 100 milliards de USD par jour selon l'enquête triennale de la BRI de 2023."},{"id":"produits-derives:test:1","m":"produits-derives","ch":"Introduction","l":"l1","type":"qcm","q":"Les pourcentages de poids des devises (USD 88 %, EUR 31 %…) s'apprécient par rapport à…","opts":["100 %","200 %","300 %","Aucun total fixe"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Une transaction met en jeu deux monnaies : le total est de 200 %. Le poids relatif réel de l'USD est d'environ 44 %."},{"id":"produits-derives:test:2","m":"produits-derives","ch":"Les participants","l":"l2","type":"num","q":"Quelle part des transactions passe par les services des courtiers ? (en %)","opts":null,"correct":null,"answer":40,"tol":0,"unit":"%","ex":"Environ 40 % des transactions, pour une commission de courtage de l'ordre de 0,01 %."},{"id":"produits-derives:test:3","m":"produits-derives","ch":"Les participants","l":"l2","type":"qcm","q":"Un teneur de marché (market maker) se distingue d'un saler parce qu'il…","opts":["Répond uniquement à la demande des clients","Assure en permanence la liquidité et fixe les cours de référence","Ne prend aucune position de change","Travaille au back office"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le market maker assure la liquidité et la contrepartie ; ses cours servent de référence. Le saler, lui, répond à la demande clientèle."},{"id":"produits-derives:test:4","m":"produits-derives","ch":"Supports & fonctionnement","l":"l3","type":"qcm","q":"Le compte lori est…","opts":["Le compte de la banque chez son correspondant, en devises","Le compte du correspondant chez la banque, en monnaie nationale","Un compte de compensation SWIFT","Le compte de la banque centrale"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Lori = le leur chez nous, en monnaie nationale. Nostri = le nôtre chez eux, en devises. Aucun passage entre les deux."},{"id":"produits-derives:test:5","m":"produits-derives","ch":"Supports & fonctionnement","l":"l3","type":"num","q":"En quelle année le système SWIFT a-t-il été créé ?","opts":null,"correct":null,"answer":1977,"tol":0,"unit":"","ex":"SWIFT a été créé en 1977. C'est un mode de transmission des ordres, pas un mode de paiement."},{"id":"produits-derives:test:6","m":"produits-derives","ch":"Supports & fonctionnement","l":"l3","type":"qcm","q":"Le marché des changes est un marché…","opts":["Organisé avec une bourse centralisée","De gré à gré (OTC), non standardisé et délocalisé","Réglementé par l'AMF","Limité aux heures d'ouverture européennes"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"OTC : pas de standardisation officielle, pas de bourse centralisée, cotations en continu 24h/24 et 5 jours ouvrables sur 7."},{"id":"produits-derives:test:7","m":"produits-derives","ch":"Les opérations","l":"l4","type":"qcm","q":"Une entreprise a 600 000 USD de créances et 900 000 USD de dettes à la même échéance. Sa position est…","opts":["Longue, risque de baisse","Courte, risque de hausse","Fermée, aucun risque","Longue, risque de hausse"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"PC = 600 000 − 900 000 = −300 000 : position courte (cas de l'importateur), exposée à une hausse du cours."},{"id":"produits-derives:test:8","m":"produits-derives","ch":"Les opérations","l":"l4","type":"qcm","q":"Lorsqu'un agent se couvre, le risque de change…","opts":["Disparaît du marché","Est transféré à un autre agent","Est pris en charge par la BRI","Est divisé par deux"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le risque ne disparaît pas : il est transféré à un agent qui l'accepte en espérant un gain de change."},{"id":"produits-derives:test:9","m":"produits-derives","ch":"Les opérations","l":"l4","type":"qcm","q":"Un spéculateur intervenant sur quelques minutes est appelé…","opts":["Scalper","Day-to-day trader","Long term trader","Market maker"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Scalpers (quelques minutes), day-to-day traders (un jour), long term traders (échéance lointaine)."},{"id":"produits-derives:test:10","m":"produits-derives","ch":"Lire un cours","l":"l5","type":"num","q":"Dans combien de jours ouvrables a lieu la livraison au comptant ?","opts":null,"correct":null,"answer":2,"tol":0,"unit":"jours","ex":"La livraison a lieu au plus tard dans les 2 jours ouvrables suivant la conclusion de la transaction (J+2)."},{"id":"produits-derives:test:11","m":"produits-derives","ch":"Lire un cours","l":"l5","type":"qcm","q":"Dans la norme ISO 4217, les trois lettres correspondent à…","opts":["3 lettres du nom du pays","2 lettres du pays + 1re lettre de la devise","1 lettre du pays + 2 de la devise","Un code attribué aléatoirement"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Deux lettres du pays et la première lettre de la devise. L'EUR fait exception, étant la monnaie d'une zone économique."},{"id":"produits-derives:test:12","m":"produits-derives","ch":"Certain & incertain","l":"l6","type":"qcm","q":"La cotation à l'incertain exprime…","opts":["Le prix d'1 unité de monnaie locale en monnaie étrangère","Le prix d'1 unité de monnaie étrangère en monnaie locale","La moyenne des cours acheteur et vendeur","Le cours à terme"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"À l'incertain : 1 ME = x ML. Au certain : 1 ML = x' ME, pratiqué notamment en zone euro, en Grande-Bretagne, au Canada, en Australie et Nouvelle-Zélande."},{"id":"produits-derives:test:13","m":"produits-derives","ch":"Certain & incertain","l":"l6","type":"num","q":"Cotation USD/CHF = 0,9268 − 0,9280. Calcule le spread en points.","opts":null,"correct":null,"answer":12,"tol":0,"unit":"points","ex":"0,9280 − 0,9268 = 0,0012, soit 12 points de CHF par USD acheté puis revendu (0,13 % en pourcentage).","aide":{"f":["fwd-spread"],"t":"La cotation donne deux cours : acheteur (le premier) et vendeur (le second). Un spread « en points » est seulement le haut de la formule, V − A, sans division : fais la soustraction, puis lis l'écart en points (1 point = 0,0001, la 4e décimale)."}},{"id":"produits-derives:test:14","m":"produits-derives","ch":"Certain & incertain","l":"l6","type":"qcm","q":"En double cotation, (B/A)ⱽ est égal à…","opts":["1 / (A/B)ⱽ","1 / (A/B)ᴬ","(A/B)ᴬ × (A/B)ⱽ","(A/B)ⱽ − (A/B)ᴬ"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'inversion croise les cours : le vendeur de (B/A) est l'inverse de l'acheteur de (A/B)."},{"id":"produits-derives:test:15","m":"produits-derives","ch":"Cours croisés","l":"l7","type":"num","q":"(GBP/USD)ᴬ = 1,2500 et (USD/CHF)ᴬ = 0,9000. Calcule (GBP/CHF)ᴬ.","opts":null,"correct":null,"answer":1.125,"tol":0.002,"unit":"GBP/CHF","ex":"En chaîne, les acheteurs se multiplient : 1,2500 × 0,9000 = 1,1250.","aide":{"f":["fwd-croise-chaine"],"t":"Les deux cours s'enchaînent par le pivot USD (GBP/USD puis USD/CHF : l'USD « s'annule ») : c'est le calcul en chaîne, on multiplie des cours du même côté. On te demande le cours acheteur : multiplie les deux cours acheteurs."}},{"id":"produits-derives:test:16","m":"produits-derives","ch":"Cours croisés","l":"l7","type":"qcm","q":"Pourquoi une banque fabrique-t-elle un cours croisé pour son client ?","opts":["Pour prendre une position spéculative","Parce que la paire n'est pas cotée directement et qu'elle veut déboucler sans risque","Pour contourner la réglementation","Pour éviter de payer une commission"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La paire n'est pas assez tradée pour être cotée directement ; la banque débouclé immédiatement l'opération sur le marché pour ne pas porter de risque."},{"id":"produits-derives:test:17","m":"produits-derives","ch":"Arbitrage","l":"l8","type":"qcm","q":"Un arbitrage géographique est possible si…","opts":["Le cours acheteur d'une place dépasse le cours vendeur d'une autre","Les spreads sont égaux","Le cours croisé calculé égale le cours observé","Le marché est fermé sur une place"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Il faut un recouvrement : acheter au cours vendeur le plus bas et revendre au cours acheteur le plus haut."},{"id":"produits-derives:test:18","m":"produits-derives","ch":"Arbitrage","l":"l8","type":"num","q":"Avec 100 000 USD : achat de GBP à 1,6000 (vendeur), revente à 1,6040 (acheteur). Gain en USD ?","opts":null,"correct":null,"answer":250,"tol":3,"unit":"USD","ex":"100 000/1,6000 = 62 500 GBP ; 62 500 × 1,6040 = 100 250 USD ; gain = 250 USD.","aide":{"f":["fwd-cours"],"t":"Deux changes successifs. Le cours GBP/USD donne des USD pour 1 GBP : pour savoir combien de GBP tu obtiens, divise tes 100 000 USD par le cours auquel la banque te vend la livre (son cours vendeur, 1,6000). Reconvertis ensuite ces GBP en USD au cours de revente, puis retire la mise de départ."}},{"id":"produits-derives:test:19","m":"produits-derives","ch":"Arbitrage","l":"l8","type":"qcm","q":"Quand vous achetez une devise à une banque, vous subissez…","opts":["Son cours acheteur","Son cours vendeur","Le cours moyen","Le cours croisé"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est toujours la banque sollicitée qui impose sa cotation : elle vend au cours vendeur et achète au cours acheteur."},{"id":"produits-derives:test:20","m":"produits-derives","ch":"Marché à terme","l":"l9","type":"qcm","q":"Le dénouement effectif d'une opération de change à terme a lieu…","opts":["Le jour de la négociation","Le jour de l'échéance","Le deuxième jour ouvrable après l'échéance","Le dernier jour du mois"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Comme au comptant, le règlement-livraison se fait en J+2, ici après la date d'échéance."},{"id":"produits-derives:test:21","m":"produits-derives","ch":"Marché à terme","l":"l9","type":"qcm","q":"Au-delà de deux ans, quelles devises restent négociées à terme ?","opts":["Toutes les monnaies convertibles","USD, JPY, CHF, GBP et EUR","Uniquement l'USD et l'EUR","Les monnaies des pays émergents"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Entre 3 jours et 6 mois toutes les monnaies des échanges internationaux sont cotées ; au-delà de 2 ans, principalement USD, JPY, CHF, GBP et EUR."},{"id":"produits-derives:test:22","m":"produits-derives","ch":"Marché à terme","l":"l9","type":"qcm","q":"Le marché des changes à terme se subdivise en…","opts":["Terme sec et swap de change","Comptant et terme","Gré à gré et organisé","Couverture et spéculation"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Le terme sec (forward outright) et le swap de change ; ce chapitre traite du terme sec."},{"id":"produits-derives:test:23","m":"produits-derives","ch":"Report & déport","l":"l10","type":"num","q":"EUR/USD comptant 1,3820 et à 1 mois 1,3827. Combien de points de report ? (en points de base)","opts":null,"correct":null,"answer":7,"tol":0,"unit":"pb","ex":"1,3827 − 1,3820 = 0,0007, soit 7 points de base de report de l'euro contre le dollar.","aide":{"f":["fwd-report"],"t":"Le cours à 1 mois est au-dessus du comptant : l'euro est en report. Les points de report sont l'écart f − S, compté en 4e décimale (1 point = 0,0001)."}},{"id":"produits-derives:test:24","m":"produits-derives","ch":"Report & déport","l":"l10","type":"num","q":"EUR/USD comptant 1,3820 et à 3 mois 1,3808 : taux de déport annualisé ? (en %, valeur absolue)","opts":null,"correct":null,"answer":0.35,"tol":0.03,"unit":"%","ex":"(1,3808 − 1,3820)/1,3820 × 12/3 × 100 = −0,35 % : l'euro est en déport de 0,35 % l'an.","aide":{"f":["fwd-taux-report"],"t":"On te demande un taux annualisé et la durée est donnée en mois (3 mois) : prends la version « durée en mois ». Calcule d'abord l'écart relatif (f − S) ÷ S, puis multiplie par 12/n et par 100. Le cours à terme est sous le comptant : le taux est négatif (déport), donne sa valeur absolue."}},{"id":"produits-derives:test:25","m":"produits-derives","ch":"Report & déport","l":"l10","type":"qcm","q":"Une devise « au pair » (square) signifie que…","opts":["Le cours à terme égale le cours au comptant","Le spread est nul","Les taux d'intérêt sont nuls","Le cours est fixé par la banque centrale"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"f = S : ni report ni déport, situation rare en pratique."},{"id":"produits-derives:test:26","m":"produits-derives","ch":"Points de swap","l":"l11","type":"qcm","q":"Points de swap affichés 28 − 23 sur EUR/USD. Que fait-on ?","opts":["On additionne : report","On soustrait : déport","On additionne le premier, on soustrait le second","Rien, la cotation est erronée"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"PS acheteur > PS vendeur : déport de l'euro contre le dollar, donc soustraction au cours comptant."},{"id":"produits-derives:test:27","m":"produits-derives","ch":"Points de swap","l":"l11","type":"num","q":"GBP/USD spot 1,6312 − 22, points à 1 mois 5 − 12. Quel est le cours à terme acheteur ?","opts":null,"correct":null,"answer":1.6317,"tol":0.0001,"unit":"","ex":"5 < 12 donc report : 1,6312 + 0,0005 = 1,6317 (et le vendeur : 1,6322 + 0,0012 = 1,6334).","aide":{"f":["fwd-points-swap"],"t":"Les points à terme « 5 − 12 » montent (le premier est plus petit) : c'est un report, on additionne. Pour le cours à terme acheteur, ajoute au cours comptant acheteur les points acheteurs (le premier nombre), exprimés en 4e décimale."}},{"id":"produits-derives:test:28","m":"produits-derives","ch":"Points de swap","l":"l11","type":"qcm","q":"Quel contrôle valide un calcul de cours à terme ?","opts":["Le spread doit rester constant","Le spread doit s'élargir avec l'échéance","Le spread doit se resserrer avec l'échéance","Le cours à terme doit dépasser le comptant"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le risque du cambiste augmente avec l'échéance : le spread s'élargit toujours."},{"id":"produits-derives:test:29","m":"produits-derives","ch":"Eurodevises","l":"l12","type":"qcm","q":"Qu'est-ce qu'une eurodevise ?","opts":["Une devise de la zone euro","Une devise détenue hors de son pays d'émission","Une devise cotée à Francfort","Une devise convertible en euro"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Un dollar déposé à Londres ou à Tokyo est un eurodollar ; déposé aux États-Unis, c'est un dollar."},{"id":"produits-derives:test:30","m":"produits-derives","ch":"Eurodevises","l":"l12","type":"num","q":"Cotation eurodollar 6 mois : 2 5/16 − 2 7/16. Quel est le taux emprunteur ? (en %)","opts":null,"correct":null,"answer":2.3125,"tol":0.0001,"unit":"%","ex":"2 + 5/16 = 2,3125 %. Le taux prêteur est 2 + 7/16 = 2,4375 %.","aide":{"f":["fwd-eurodevises"],"t":"Une cotation de taux s'écrit « taux emprunteur − taux prêteur » : c'est le premier nombre qui t'intéresse. Convertis sa fraction en décimales (5/16 = 5 ÷ 16) et ajoute-la à la partie entière."}},{"id":"produits-derives:test:31","m":"produits-derives","ch":"Eurodevises","l":"l12","type":"qcm","q":"Sur le marché des eurodevises, les spreads de taux vont de…","opts":["1/32 % à 1/8 %","1/8 % à 2 %","1 % à 5 %","0 % à 1/2 %"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"De 1/8 % jusqu'à 2 %, la partie décimale des taux étant généralement un multiple de 1/32."},{"id":"produits-derives:test:32","m":"produits-derives","ch":"Position de change","l":"l13","type":"qcm","q":"Laquelle de ces conditions n'est PAS nécessaire au risque de change ?","opts":["Une transaction avec l'étranger","Une transaction libellée en devises","Un décalage entre transaction et flux financier","Un régime de changes fixes"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"Les trois premières conditions sont cumulatives ; c'est au contraire le flottement qui amplifie le risque."},{"id":"produits-derives:test:33","m":"produits-derives","ch":"Position de change","l":"l13","type":"num","q":"Créances 70 000 EUR et dettes 40 000 EUR au 01/07. Quelle est la position de change en EUR ?","opts":null,"correct":null,"answer":30000,"tol":0,"unit":"EUR","ex":"70 000 − 40 000 = +30 000 EUR : position longue, donc risque de baisse de l'euro à l'échéance.","aide":{"f":["fwd-position"],"t":"Créances et dettes sont dans la même devise (EUR) et à la même date : la position de change est créances moins dettes. Regarde ensuite le signe : positive = position longue."}},{"id":"produits-derives:test:34","m":"produits-derives","ch":"Position de change","l":"l13","type":"qcm","q":"Un importateur en devises est en position…","opts":["Longue, risque de baisse","Courte, risque de hausse","Fermée, aucun risque","Longue, risque de hausse"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Ses dettes en devises excèdent ses créances : il craint une hausse du cours et se couvre en achetant à terme."},{"id":"produits-derives:test:35","m":"produits-derives","ch":"Cours à terme","l":"l14","type":"qcm","q":"Pour fabriquer une vente à terme de A contre B, la banque réalise…","opts":["Un emprunt en A, une vente comptant de A contre B, un prêt en B","Un emprunt en B, un achat comptant de A, un prêt en A","Un simple achat à terme auprès d'une autre banque","Un placement en A et un emprunt en B"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Emprunt en A remboursé par les devises du client, vente au comptant, placement du produit en B jusqu'à l'échéance."},{"id":"produits-derives:test:36","m":"produits-derives","ch":"Cours à terme","l":"l14","type":"num","q":"Spot USD/CHF acheteur 1,4925, r(CHF) emprunteur 1,625 %, r(USD) prêteur 2,4375 %, 6 mois. Cours à terme acheteur ?","opts":null,"correct":null,"answer":1.4865,"tol":0.0003,"unit":"","ex":"1,4925 × (1 + 0,01625 × 0,5)/(1 + 0,024375 × 0,5) = 1,4865, soit 60 points de déport du dollar.","aide":{"f":["fwd-terme-acheteur"],"t":"On demande un cours à terme acheteur : la banque achète des USD à terme (cas de l'exportateur). Dans USD/CHF, A = USD et B = CHF : comptant acheteur × (1 + taux emprunteur CHF × n/12) ÷ (1 + taux prêteur USD × n/12), avec n = 6 mois. Commence par le numérateur : 1 + 1,625 % × 6/12."}},{"id":"produits-derives:test:37","m":"produits-derives","ch":"Cours à terme","l":"l15","type":"num","q":"Spot USD/CHF vendeur 1,4955, r(CHF) prêteur 1,75 %, r(USD) emprunteur 2,3125 %, 6 mois. Cours à terme vendeur ?","opts":null,"correct":null,"answer":1.4913,"tol":0.0003,"unit":"","ex":"1,4955 × (1 + 0,0175 × 0,5)/(1 + 0,023125 × 0,5) = 1,4913 : la double cotation à 6 mois est 1,4865 − 1,4913.","aide":{"f":["fwd-terme-vendeur"],"t":"On demande un cours à terme vendeur : la banque vend des USD à terme (cas de l'importateur). Formule miroir, à partir du comptant vendeur (1,4955) : × (1 + taux prêteur CHF × n/12) ÷ (1 + taux emprunteur USD × n/12), avec n = 6 mois."}},{"id":"produits-derives:test:38","m":"produits-derives","ch":"Cours à terme","l":"l15","type":"qcm","q":"Le taux d'intérêt de la devise A dépasse celui de la monnaie B. La devise A est…","opts":["En report contre B","En déport contre B","Au pair","Indéterminée sans le cours comptant"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La devise la mieux rémunérée est en déport à terme : c'est ce qui neutralise l'arbitrage de taux couvert."},{"id":"marketing-numerique:quiz:l1:0","m":"marketing-numerique","ch":"Leçon 1 — Données, CRM et DMP","l":"l1","type":"qcm","q":"Que permet la numérisation de toute information en 0/1 ?","opts":["Uniquement de stocker","Stocker, communiquer et influencer","Uniquement de communiquer plus vite"],"correct":1,"ex":"Exact. Les trois usages sont indissociables — c'est la dimension « influencer », via les émotions, qui fait du numérique un enjeu marketing."},{"id":"marketing-numerique:quiz:l1:1","m":"marketing-numerique","ch":"Leçon 1 — Données, CRM et DMP","l":"l1","type":"qcm","q":"Que signifie DMP ?","opts":["Digital Marketing Process","Data Management Platform","Data Mining Program"],"correct":1,"ex":"Bien vu. La DMP industrialise le passage de la donnée brute à la valeur métier."},{"id":"marketing-numerique:quiz:l2:0","m":"marketing-numerique","ch":"Leçon 2 — À quoi sert le marketing ?","l":"l2","type":"qcm","q":"Selon la définition de l'AMA, le marketing sert d'abord à…","opts":["Faire vendre","Faire connaître une marque","Comprendre un marché pour faire des choix et créer de la valeur"],"correct":2,"ex":"Exact. La vente et la notoriété sont des conséquences ; la finalité est la création de valeur pour les clients, les organisations et la société."},{"id":"marketing-numerique:quiz:l2:1","m":"marketing-numerique","ch":"Leçon 2 — À quoi sert le marketing ?","l":"l2","type":"qcm","q":"Le marketing opérationnel correspond à…","opts":["Une démarche d'analyse et de connaissance des marchés","Une démarche d'action et de conquête des marchés","L'audit des résultats"],"correct":1,"ex":"Bien vu. Le stratégique analyse et connaît, l'opérationnel agit et conquiert."},{"id":"marketing-numerique:quiz:l3:0","m":"marketing-numerique","ch":"Leçon 3 — Le marché : demande et offre","l":"l3","type":"qcm","q":"Un non-consommateur relatif est une personne qui…","opts":["Ne consommera jamais le produit","Pourrait consommer si un frein était levé","Consomme chez un concurrent"],"correct":1,"ex":"Exact. Celui qui consomme chez un concurrent est un prospect ; l'absolu, lui, ne consommera jamais."},{"id":"marketing-numerique:quiz:l3:1","m":"marketing-numerique","ch":"Leçon 3 — Le marché : demande et offre","l":"l3","type":"qcm","q":"Le marché générique répond à la question…","opts":["Quel produit ?","Quel besoin ?","Qu'est-ce qui peut le remplacer ?"],"correct":1,"ex":"Bien vu. « Quel produit ? » définit le marché principal, « qu'est-ce qui peut le remplacer ? » le marché substitut."},{"id":"marketing-numerique:quiz:l4:0","m":"marketing-numerique","ch":"Leçon 4 — PESTEL, Porter, SWOT et cycle de vie","l":"l4","type":"qcm","q":"Quelle est la « sixième force » ajoutée au modèle de Porter ?","opts":["Les actionnaires","L'État","Les salariés"],"correct":1,"ex":"Exact. L'État encadre et influence les cinq autres forces — un poids majeur dans le secteur bancaire."},{"id":"marketing-numerique:quiz:l4:1","m":"marketing-numerique","ch":"Leçon 4 — PESTEL, Porter, SWOT et cycle de vie","l":"l4","type":"qcm","q":"Dans le cycle de vie, à quelle phase le client se demande-t-il « Où puis-je en acheter ? »","opts":["Émergence","Croissance","Maturité"],"correct":1,"ex":"Bien vu. À l'émergence il demande « qu'est-ce que c'est ? », en sélection et maturité « lequel acheter ? », en déclin « combien ? »."},{"id":"marketing-numerique:quiz:l5:0","m":"marketing-numerique","ch":"Leçon 5 — Segmenter et cibler","l":"l5","type":"qcm","q":"La segmentation stratégique partitionne…","opts":["Un marché en groupes de clients","Une organisation en sous-ensembles homogènes","Une gamme de produits"],"correct":1,"ex":"Exact. C'est la segmentation marketing qui découpe le marché en sous-ensembles de clients."},{"id":"marketing-numerique:quiz:l5:1","m":"marketing-numerique","ch":"Leçon 5 — Segmenter et cibler","l":"l5","type":"qcm","q":"Proposer des produits de nature diverse à un seul segment de marché correspond à…","opts":["La spécialisation par produit","La spécialisation par marché","Le marketing indifférencié"],"correct":1,"ex":"Bien vu. Par marché : un segment fixe, des produits variés. Par produit : une catégorie de produit fixe, plusieurs segments."},{"id":"marketing-numerique:quiz:l6:0","m":"marketing-numerique","ch":"Leçon 6 — Positionnement et stratégies de croissance","l":"l6","type":"qcm","q":"Dans le losange de Kapferer, la question « Contre qui ? » porte sur…","opts":["Les moments d'utilisation","Les concurrents directs","Les bénéfices apportés"],"correct":1,"ex":"Exact. « Quand ? » vise les moments d'utilisation et « Pourquoi ? » les bénéfices."},{"id":"marketing-numerique:quiz:l6:1","m":"marketing-numerique","ch":"Leçon 6 — Positionnement et stratégies de croissance","l":"l6","type":"qcm","q":"Lancer un produit nouveau sur un marché nouveau correspond, chez Ansoff, à…","opts":["La pénétration du marché","Le développement par les marchés","La diversification"],"correct":2,"ex":"Bien vu. C'est la stratégie la plus risquée : ni le produit ni le marché ne sont maîtrisés."},{"id":"marketing-numerique:quiz:l7:0","m":"marketing-numerique","ch":"Leçon 7 — Le mix : produit et prix","l":"l7","type":"qcm","q":"Le prix plancher est déterminé par…","opts":["L'acceptabilité par le client","Le seuil en dessous duquel le profit devient négatif","Le prix moyen de la concurrence"],"correct":1,"ex":"Exact. Le plafond, lui, correspond au niveau au-delà duquel la demande devient inexistante."},{"id":"marketing-numerique:quiz:l7:1","m":"marketing-numerique","ch":"Leçon 7 — Le mix : produit et prix","l":"l7","type":"qcm","q":"Une politique de pénétration correspond à…","opts":["Vendre au prix fort à une cible réduite","Vendre à faible marge dans une optique de volume","Aligner ses prix sur le leader"],"correct":1,"ex":"Bien vu. C'est la stratégie du challengeur sur un marché mature ; l'écrémage vise le profit sur un marché nouveau."},{"id":"marketing-numerique:quiz:l8:0","m":"marketing-numerique","ch":"Leçon 8 — Le mix : distribution et communication","l":"l8","type":"qcm","q":"Une distribution exclusive signifie…","opts":["Un nombre limité de distributeurs choisis","Un seul distributeur autorisé","Une présence dans un maximum de points de vente"],"correct":1,"ex":"Exact. Un nombre limité de distributeurs correspond à la distribution sélective ; l'exclusive n'en autorise qu'un."},{"id":"marketing-numerique:quiz:l8:1","m":"marketing-numerique","ch":"Leçon 8 — Le mix : distribution et communication","l":"l8","type":"qcm","q":"Quelles sont les trois catégories d'objectifs de communication ?","opts":["Informer, vendre, fidéliser","Faire connaître, faire aimer, faire agir","Segmenter, cibler, positionner"],"correct":1,"ex":"Bien vu. Segmenter/cibler/positionner relève du marketing stratégique, pas des objectifs de communication."},{"id":"marketing-numerique:quiz:l9:0","m":"marketing-numerique","ch":"Leçon 9 — Mesurer et intégrer la durabilité","l":"l9","type":"qcm","q":"La notoriété et l'image sont des objectifs…","opts":["De vente","De comportement","D'attitude"],"correct":2,"ex":"Exact. Vente = volume, CA, part de marché. Comportement = pénétration, fréquence, panier moyen. Attitude = notoriété, image, préférence, intention."},{"id":"marketing-numerique:quiz:l9:1","m":"marketing-numerique","ch":"Leçon 9 — Mesurer et intégrer la durabilité","l":"l9","type":"qcm","q":"Le « choice editing » consiste à…","opts":["Informer le client sur l'impact de ses achats","Sélectionner ou modifier les choix disponibles","Réduire le nombre de références en promotion"],"correct":1,"ex":"Bien vu. L'information (Yuka, Eco-score) relève de l'éducation ; le choice editing agit directement sur l'offre proposée."},{"id":"marketing-numerique:quiz:l10:0","m":"marketing-numerique","ch":"Leçon 10 — Le parcours client et ses points de contact","l":"l10","type":"qcm","q":"Un simulateur de crédit sur le site de la banque relève surtout de quelle étape ?","opts":["Découverte","Intérêt / considération","Fidélité"],"correct":1,"ex":"Exact. Le client connaît déjà l'offre et cherche des informations précises pour comparer : c'est la considération."},{"id":"marketing-numerique:quiz:l10:1","m":"marketing-numerique","ch":"Leçon 10 — Le parcours client et ses points de contact","l":"l10","type":"qcm","q":"Lequel de ces points de contact échappe au contrôle direct de la marque ?","opts":["La vitrine de l'agence","Un avis client publié en ligne","Le courriel de bienvenue"],"correct":1,"ex":"Bien vu. L'avis en ligne et le bouche-à-oreille sont des points de contact subis : on peut y répondre, pas les écrire."},{"id":"marketing-numerique:quiz:l11:0","m":"marketing-numerique","ch":"Leçon 11 — RGPD, CNIL et données personnelles","l":"l11","type":"qcm","q":"En cas de violation de données, sous quel délai faut-il notifier la CNIL ?","opts":["30 jours","72 heures","Immédiatement, avant toute vérification"],"correct":1,"ex":"Exact. 72 heures pour la notification à la CNIL ; les 30 jours sont le délai de traitement d'une demande de suppression."},{"id":"marketing-numerique:quiz:l11:1","m":"marketing-numerique","ch":"Leçon 11 — RGPD, CNIL et données personnelles","l":"l11","type":"qcm","q":"Quel est le plafond de sanction prévu par le RGPD ?","opts":["2 % du chiffre d'affaires national","4 % du chiffre d'affaires mondial ou 20 M€","Un million d'euros par infraction"],"correct":1,"ex":"Bien vu. C'est le montant le plus élevé des deux qui s'applique — d'où les 325 M€ infligés à Google sur les cookies."},{"id":"marketing-numerique:test:0","m":"marketing-numerique","ch":"Données & DMP","l":"l1","type":"qcm","q":"Que signifie DMP ?","opts":["Digital Marketing Process","Data Management Platform","Data Mining Protocol","Direct Marketing Platform"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Data Management Platform : elle industrialise le passage des données brutes à la valeur métier."},{"id":"marketing-numerique:test:1","m":"marketing-numerique","ch":"Données & DMP","l":"l1","type":"qcm","q":"Dans la chaîne de traitement d'une DMP, qu'est-ce qui suit immédiatement les données brutes ?","opts":["Le machine learning","Le filtre / nettoyage","La valeur métier","La feature selection"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Données brutes → filtre/nettoyage → feature selection → statistiques/ML → valeur métier."},{"id":"marketing-numerique:test:2","m":"marketing-numerique","ch":"Fondamentaux","l":"l2","type":"qcm","q":"Selon l'AMA, le marketing sert d'abord à…","opts":["Faire vendre","Faire connaître une marque","Comprendre les consommateurs","Comprendre un marché pour faire des choix et créer de la valeur"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"Les trois autres réponses sont des conséquences ou des moyens ; la finalité est la création de valeur."},{"id":"marketing-numerique:test:3","m":"marketing-numerique","ch":"Fondamentaux","l":"l2","type":"qcm","q":"Quel est l'ordre de la démarche marketing ?","opts":["Choisir → Analyser → Agir → Mesurer","Analyser → Choisir → Agir → Mesurer","Agir → Mesurer → Analyser → Choisir","Analyser → Agir → Choisir → Mesurer"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Analyse marketing → définition de la stratégie → mise en œuvre → suivi et contrôle, qui reboucle sur l'analyse."},{"id":"marketing-numerique:test:4","m":"marketing-numerique","ch":"Le marché","l":"l3","type":"qcm","q":"Les clients des concurrents constituent, pour l'entreprise…","opts":["Des non-consommateurs absolus","Des non-consommateurs relatifs","Des prospects","Un marché substitut"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Ils consomment déjà la catégorie, mais pas chez l'entreprise : ce sont des prospects, inclus dans son marché potentiel."},{"id":"marketing-numerique:test:5","m":"marketing-numerique","ch":"Le marché","l":"l3","type":"qcm","q":"Le marché support répond à la question…","opts":["Quel besoin ?","Qu'est-ce qui permet ou facilite son utilisation ?","Qu'est-ce qui accompagne son utilisation ?","Qu'est-ce qui peut le remplacer ?"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le complémentaire accompagne l'utilisation, le support la permet ou la facilite, le générique renvoie au besoin."},{"id":"marketing-numerique:test:6","m":"marketing-numerique","ch":"Diagnostic","l":"l4","type":"qcm","q":"Que recouvre le E de PESTEL, en plus de l'économique ?","opts":["Éthique","Écologique","Éducatif","Européen"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Politique, Économique, Socio-culturel, Technologique, Écologique, Légal."},{"id":"marketing-numerique:test:7","m":"marketing-numerique","ch":"Diagnostic","l":"l4","type":"qcm","q":"Quelle est la sixième force du modèle de Porter ?","opts":["Les actionnaires","Les salariés","L'État","Les médias"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"L'État encadre et influence les cinq forces — un poids déterminant dans le secteur bancaire."},{"id":"marketing-numerique:test:8","m":"marketing-numerique","ch":"Diagnostic","l":"l4","type":"qcm","q":"Dans un SWOT, une nouvelle réglementation défavorable est…","opts":["Une faiblesse","Une menace","Une force","Une opportunité"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Elle est externe et négative : l'entreprise ne peut que s'y adapter, donc c'est une menace, pas une faiblesse."},{"id":"marketing-numerique:test:9","m":"marketing-numerique","ch":"Diagnostic","l":"l4","type":"qcm","q":"À quelle phase du cycle de vie correspond la saturation de la demande et les achats de remplacement ?","opts":["Croissance","Sélection","Maturité","Déclin"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"En maturité : bataille pour les parts de marché, difficultés de croissance, accent sur l'efficacité et les coûts."},{"id":"marketing-numerique:test:10","m":"marketing-numerique","ch":"Segmenter & cibler","l":"l5","type":"qcm","q":"La segmentation marketing, selon Kotler, subdivise…","opts":["Une organisation en DAS","Un marché en sous-ensembles homogènes de clients","Une gamme en lignes de produits","Un budget en postes"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est la segmentation stratégique qui partitionne l'organisation en DAS."},{"id":"marketing-numerique:test:11","m":"marketing-numerique","ch":"Segmenter & cibler","l":"l5","type":"qcm","q":"Coca-Cola, un produit unique pour tous les segments, illustre…","opts":["Le marketing différencié","Le marketing indifférencié","La concentration","La spécialisation par produit"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Marketing indifférencié : un produit et un plan marketing uniques pour attirer le plus grand nombre."},{"id":"marketing-numerique:test:12","m":"marketing-numerique","ch":"Segmenter & cibler","l":"l5","type":"qcm","q":"Le statut de fidélité est une variable de segmentation…","opts":["Intrinsèque au consommateur","Exprimant sa réponse à la catégorie de produits","Géographique","Sociodémographique"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Avec les situations d'achat, les avantages recherchés et le statut d'utilisateur, il relève des variables de réponse."},{"id":"marketing-numerique:test:13","m":"marketing-numerique","ch":"Positionner","l":"l6","type":"qcm","q":"Un positionnement doit être…","opts":["Crédible, attractif et différent","Large, flou et adaptable","Rentable, rapide et mesurable","Technique, chiffré et daté"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Une position crédible, attractive et différente sur son marché et dans l'esprit des clients."},{"id":"marketing-numerique:test:14","m":"marketing-numerique","ch":"Positionner","l":"l6","type":"qcm","q":"Helios, « la banque durable en ligne pour les clients responsables », se différencie par…","opts":["Les attributs du produit","Les publics auxquels l'offre est destinée","Les services associés","L'imaginaire de la marque"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est l'exemple bancaire du cours pour l'axe « publics auxquels l'offre est destinée »."},{"id":"marketing-numerique:test:15","m":"marketing-numerique","ch":"Positionner","l":"l6","type":"qcm","q":"Vendre un produit existant sur un marché nouveau correspond, chez Ansoff, à…","opts":["La pénétration du marché","Le développement par les produits","Le développement par les marchés","La diversification"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le terme qui suit « développement par » désigne ce qui est nouveau : ici, les marchés."},{"id":"marketing-numerique:test:16","m":"marketing-numerique","ch":"Le mix","l":"l7","type":"qcm","q":"Une politique d'écrémage consiste à…","opts":["Vendre à faible marge pour le volume","Vendre au prix fort à une cible réduite","S'aligner sur la concurrence","Pratiquer des tarifs différenciés"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Écrémage : optique de profit, position de leader sur un marché nouveau. Risque : signaler à la concurrence de forts profits."},{"id":"marketing-numerique:test:17","m":"marketing-numerique","ch":"Le mix","l":"l7","type":"qcm","q":"Quels sont les trois facteurs influençant le prix ?","opts":["Coûts, concurrence, clients","Coûts, canaux, communication","Clients, canaux, concurrence","Coûts, clients, communication"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Les trois C : coûts (plancher), clients (plafond), concurrence (positionnement dans le couloir)."},{"id":"marketing-numerique:test:18","m":"marketing-numerique","ch":"Le mix","l":"l8","type":"qcm","q":"Tesla et Rolex illustrent une distribution…","opts":["Intensive","Sélective","Exclusive","Par franchise"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Distribution exclusive : un seul distributeur autorisé, pour maîtriser image et expérience client."},{"id":"marketing-numerique:test:19","m":"marketing-numerique","ch":"Le mix","l":"l8","type":"qcm","q":"Un canal court se caractérise par…","opts":["Producteur → grossiste → détaillant → consommateur","Producteur → détaillant avec centrale d'achat → consommateur","Producteur → consommateur","Producteur → franchisé → consommateur"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le canal long passe par un grossiste ; le canal direct ou ultra-court va du producteur au consommateur."},{"id":"marketing-numerique:test:20","m":"marketing-numerique","ch":"Mesurer & durabilité","l":"l9","type":"qcm","q":"Le panier moyen est un objectif…","opts":["De vente","De comportement","D'attitude","D'image"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Comportement : pénétration, fréquence, panier moyen. Vente : volume, CA, part de marché. Attitude : notoriété, image, préférence, intention."},{"id":"marketing-numerique:test:21","m":"marketing-numerique","ch":"Mesurer & durabilité","l":"l9","type":"qcm","q":"« Don't buy this jacket » de Patagonia illustre quel levier du marketing de transition ?","opts":["Communiquer de manière responsable","Concevoir des produits durables","Réduire la surproduction et la surconsommation","Réduire les impacts des actions marketing"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le levier 5, aux côtés du « N'achetez pas de fraises (en hiver) » de Biocoop."},{"id":"marketing-numerique:test:22","m":"marketing-numerique","ch":"Mesurer & durabilité","l":"l9","type":"qcm","q":"Le modèle du « donut » a été proposé par…","opts":["Philip Kotler","Kate Raworth","Michael Porter","Igor Ansoff"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Kate Raworth : un plafond environnemental et un plancher social délimitant l'espace sûr et juste pour l'humanité."},{"id":"marketing-numerique:test:23","m":"marketing-numerique","ch":"Méthode","l":"methode","type":"qcm","q":"Dans la grille de lecture des cas, quelle est la première question ?","opts":["Pour qui ?","Quel diagnostic ?","Quel marché ?","Comment ?"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"1. Quel marché ? 2. Quel diagnostic ? 3. Pour qui ? 4. Quelle place ? 5. Comment ? 6. Avec quels résultats et impacts ?"},{"id":"marketing-numerique:test:24","m":"marketing-numerique","ch":"Méthode","l":"methode","type":"qcm","q":"Quelle est la chaîne de raisonnement attendue dans une copie ?","opts":["Données → Analyse → Diagnostic → Recommandation → Justification","Recommandation → Données → Analyse → Conclusion","Analyse → Recommandation → Données → Diagnostic","Diagnostic → Données → Justification → Analyse"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"C'est la chaîne indiquée en conclusion du cours : une recommandation doit toujours être justifiée par le diagnostic."},{"id":"marketing-numerique:test:25","m":"marketing-numerique","ch":"Parcours client","l":"l10","type":"qcm","q":"Combien d'étapes compte le parcours client présenté dans le cours ?","opts":["Trois","Quatre","Cinq","Sept"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Découverte, intérêt/considération, acquisition/achat, service, fidélité/loyauté."},{"id":"marketing-numerique:test:26","m":"marketing-numerique","ch":"Parcours client","l":"l10","type":"qcm","q":"Un chatbot et un simulateur en ligne sont des points de contact de quelle étape ?","opts":["Découverte","Intérêt / considération","Service","Fidélité"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le client connaît l'offre et cherche des informations précises pour comparer."},{"id":"marketing-numerique:test:27","m":"marketing-numerique","ch":"Parcours client","l":"l10","type":"qcm","q":"Qu'est-ce qu'un point de contact ?","opts":["Un canal de distribution","Tout endroit, physique ou numérique, où le client rencontre la marque","Un indicateur de satisfaction","Une étape du mix marketing"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Y compris les points subis : avis en ligne, bouche-à-oreille, commentaires sous une publication."},{"id":"marketing-numerique:test:28","m":"marketing-numerique","ch":"Parcours client","l":"l10","type":"qcm","q":"Le programme de fidélité et les courriels personnalisés interviennent à l'étape…","opts":["Découverte","Acquisition","Service","Fidélité / loyauté"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"C'est l'étape où le client devient ambassadeur de la marque."},{"id":"marketing-numerique:test:29","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Depuis quand le RGPD est-il en vigueur ?","opts":["25 mai 2016","25 mai 2018","1er janvier 2020","25 mai 2021"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Règlement adopté en 2016, entré en application le 25 mai 2018."},{"id":"marketing-numerique:test:30","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Sous quel délai la CNIL doit-elle être notifiée d'une violation de données ?","opts":["24 heures","72 heures","30 jours","Deux mois"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"72 heures. À ne pas confondre avec les 30 jours de traitement d'une demande de suppression."},{"id":"marketing-numerique:test:31","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Quelle sanction maximale le RGPD prévoit-il ?","opts":["20 M€ uniquement","4 % du CA mondial ou 20 M€, le plus élevé","2 % du CA national","10 % du résultat net"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est le montant le plus élevé qui s'applique : Google a été sanctionné de 325 M€ sur les cookies."},{"id":"marketing-numerique:test:32","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Laquelle de ces mentions n'a rien à faire dans une fiche CRM ?","opts":["La date du dernier rendez-vous","Le motif d'une réclamation","L'appartenance religieuse du client","Le canal de contact préféré"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Les données sensibles — religion, santé, origine ethnique, opinions politiques — sont proscrites, comme les jugements subjectifs."},{"id":"marketing-numerique:test:33","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Le principe de minimisation impose de…","opts":["Réduire le nombre de destinataires des données","Ne collecter que les données nécessaires à la finalité annoncée","Limiter la durée de conservation à un an","Anonymiser systématiquement les données"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Rien de plus que ce que la finalité exige : dans le cas des Pressoirs des Alpilles, seules les données nécessaires à la livraison sont demandées."},{"id":"marketing-numerique:test:34","m":"marketing-numerique","ch":"RGPD & données","l":"l11","type":"qcm","q":"Que vérifie l'étape 2 d'une analyse d'impact (PIA) ?","opts":["Les mesures de sécurité","Les principes fondamentaux : proportionnalité, nécessité et droits des personnes","La validation par le DPO","La cartographie des risques"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Étape 1 contexte · étape 2 principes fondamentaux · étape 3 risques de sécurité · étape 4 validation."},{"id":"marketing-numerique:test:35","m":"marketing-numerique","ch":"Le mix","l":"l8","type":"qcm","q":"Quelle enseigne était la plus fréquentée en France en 2020 ?","opts":["Carrefour (50 %)","E.Leclerc (53 %)","Lidl (44 %)","Intermarché (41 %)"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"E.Leclerc 53 %, devant Carrefour 50 % et Lidl 44 %. La fréquentation ne se confond pas avec la part de marché."},{"id":"es-banque:test:0","m":"es-banque","ch":"Banque à distance","l":"l1","type":"qcm","q":"Quelles conditions rendent l'écrit électronique valable (loi du 14 mars 2000) ?","opts":["Signature scannée et archivage","Identification de l'auteur et intégrité du document","Accord écrit du client","Horodatage certifié"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les deux conditions sont cumulatives : identification de l'auteur et garantie d'intégrité."},{"id":"es-banque:test:1","m":"es-banque","ch":"Banque à distance","l":"l1","type":"qcm","q":"Qui peut obtenir une levée du secret bancaire sans condition particulière ?","opts":["La police","Le fisc","L'ACPR et la Banque de France","Les huissiers"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"L'ACPR et la BDF toujours ; la justice en procédure pénale ; police et fisc sur réquisition seulement."},{"id":"es-banque:test:2","m":"es-banque","ch":"Droit au compte","l":"l2","type":"qcm","q":"Quelle loi fonde le droit au compte ?","opts":["La loi du 24 janvier 1984","La loi MURCEF de 2001","La loi Lagarde de 2010","La loi TEPA de 2007"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Loi du 24 janvier 1984 : attestation de refus, puis désignation d'office par la Banque de France."},{"id":"es-banque:test:3","m":"es-banque","ch":"Droit au compte","l":"l2","type":"num","q":"Combien de mois de préavis pour une modification tarifaire ?","opts":null,"correct":null,"answer":2,"tol":0,"unit":"mois","ex":"2 mois d'information écrite préalable ; le silence du client vaut acceptation tacite."},{"id":"es-banque:test:4","m":"es-banque","ch":"KYC","l":"l3","type":"qcm","q":"En tutelle, le tuteur…","opts":["Assiste le client par co-signature","Représente le client","N'intervient pas sur les comptes","Doit obtenir l'accord du client"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Tutelle = représenter. Curatelle = assister. Sauvegarde = le client conserve ses droits."},{"id":"es-banque:test:5","m":"es-banque","ch":"KYC","l":"l3","type":"qcm","q":"À quel âge un titulaire de Livret Jeune peut-il retirer seul ?","opts":["12 ans","14 ans","16 ans","18 ans"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Dès 16 ans, sauf opposition du représentant légal."},{"id":"es-banque:test:6","m":"es-banque","ch":"Patrimoine","l":"l4","type":"qcm","q":"En communauté réduite aux acquêts, un héritage reçu pendant le mariage est…","opts":["Commun","Propre","Indivis","Commun après 5 ans"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les héritages et les biens antérieurs restent propres ; seuls les acquêts sont communs."},{"id":"es-banque:test:7","m":"es-banque","ch":"Succession","l":"l5","type":"num","q":"Abattement en ligne directe parent-enfant, en euros ?","opts":null,"correct":null,"answer":100000,"tol":0,"unit":"€","ex":"100 000 € par enfant et par parent (art. 779 CGI), rechargeable tous les 15 ans en donation."},{"id":"es-banque:test:8","m":"es-banque","ch":"Succession","l":"l5","type":"qcm","q":"Un enfant hérite de 250 000 €. Quels droits environ ?","opts":["Environ 15 000 €","Environ 28 200 €","Environ 30 000 €","Environ 50 000 €"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"250 000 − 100 000 = 150 000 € taxables → 403 + 404 + 573 + 26 814 ≈ 28 194 €."},{"id":"es-banque:test:9","m":"es-banque","ch":"Succession","l":"l5","type":"qcm","q":"Depuis la loi TEPA de 2007, le partenaire de PACS est…","opts":["Taxé à 60 %","Totalement exonéré","Abattu de 80 724 €","Taxé comme un frère"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Exonération totale de droits de succession, au même titre que le conjoint survivant."},{"id":"es-banque:test:10","m":"es-banque","ch":"Assurance vie","l":"l6","type":"num","q":"Abattement par bénéficiaire pour les primes versées avant 70 ans ?","opts":null,"correct":null,"answer":152500,"tol":0,"unit":"€","ex":"152 500 € par bénéficiaire (art. 990 I), puis 20 % et 31,25 % au-delà de 852 500 € reçus."},{"id":"es-banque:test:11","m":"es-banque","ch":"Assurance vie","l":"l6","type":"num","q":"Abattement global pour les primes versées après 70 ans ?","opts":null,"correct":null,"answer":30500,"tol":0,"unit":"€","ex":"30 500 € global, tous bénéficiaires et tous contrats confondus (art. 757 B), réparti au prorata."},{"id":"es-banque:test:12","m":"es-banque","ch":"Assurance vie","l":"l6","type":"qcm","q":"Après 70 ans, quelle est l'assiette taxable ?","opts":["Le capital décès total","Les primes versées seules","Les gains seuls","La moitié du capital"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Seules les primes sont taxées ; les gains générés sont totalement exonérés de droits de succession."},{"id":"es-banque:test:13","m":"es-banque","ch":"Assurance vie","l":"l6","type":"num","q":"Contrat de 400 000 € versé avant 70 ans, 2 enfants. Total des droits en euros ?","opts":null,"correct":null,"answer":19000,"tol":50,"unit":"€","ex":"200 000 − 152 500 = 47 500 € taxables par enfant, × 20 % = 9 500 €, soit 19 000 € au total."},{"id":"es-banque:test:14","m":"es-banque","ch":"Assurance vie","l":"l6","type":"qcm","q":"En 2026, les prélèvements sociaux sur les gains d'assurance vie sont de…","opts":["17,2 % — exception maintenue","18,6 % comme le PEA","0 %","30 %"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"La LFSS 2026 a porté les PS à 18,6 % pour le PEA, le CTO et le PER, mais l'assurance vie est explicitement exclue et reste à 17,2 %."},{"id":"es-banque:test:15","m":"es-banque","ch":"Prévoyance","l":"l7","type":"qcm","q":"Que la GAV exclut-elle ?","opts":["Les accidents domestiques","Les agressions","Les accidents de la route et du travail","Les accidents médicaux"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"La GAV couvre la vie privée ; route et travail relèvent d'autres régimes."},{"id":"es-banque:test:16","m":"es-banque","ch":"IARD","l":"l8","type":"num","q":"Délai de déclaration d'un vol, en jours ouvrés ?","opts":null,"correct":null,"answer":2,"tol":0,"unit":"jours","ex":"2 jours ouvrés et dépôt de plainte. 5 jours pour le cas général, 10 jours pour la catastrophe naturelle."},{"id":"es-banque:test:17","m":"es-banque","ch":"IARD","l":"l8","type":"qcm","q":"La sous-assurance entraîne…","opts":["La nullité du contrat","La règle proportionnelle","Un plafonnement au réel","Une majoration de prime"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Indemnité réduite au prorata. La nullité sanctionne la sur-assurance frauduleuse."},{"id":"es-banque:test:18","m":"es-banque","ch":"Auto & MRH","l":"l9","type":"qcm","q":"Quel coefficient s'applique après un sinistre responsable ?","opts":["× 0,95","× 1,25","× 1,50","× 3,50"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"+25 % par sinistre responsable, −5 % par année sans sinistre, bornes 0,50 et 3,50."},{"id":"es-banque:test:19","m":"es-banque","ch":"ADE","l":"l10","type":"qcm","q":"Sous quelles conditions le questionnaire médical est-il supprimé (loi Lemoine) ?","opts":["Part assurée < 200 k€ seulement","Fin du prêt avant 60 ans seulement","Les deux conditions réunies","Dès 50 ans"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Les deux conditions sont cumulatives : moins de 200 000 € assurés ET fin du prêt avant le 60e anniversaire."},{"id":"es-banque:test:20","m":"es-banque","ch":"Crédit conso","l":"l11","type":"num","q":"Délai de rétractation d'un crédit à la consommation, en jours ?","opts":null,"correct":null,"answer":14,"tol":0,"unit":"jours","ex":"14 jours de rétractation, à distinguer des 15 jours de validité de l'offre et des 7 jours avant déblocage."},{"id":"es-banque:test:21","m":"es-banque","ch":"Crédit immobilier","l":"l12","type":"qcm","q":"Dans un prêt modulable, qu'est-ce qui varie ?","opts":["Le taux","La durée","Le capital","L'assurance"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le taux reste fixe, c'est la durée qui s'ajuste. Le taux variable est indexé sur l'Euribor."},{"id":"es-banque:test:22","m":"es-banque","ch":"Déontologie","l":"l13","type":"qcm","q":"Quelle est la peine encourue pour blanchiment aggravé ?","opts":["1 an et 15 000 €","5 ans et 375 000 €","10 ans et 750 000 €","3 ans et 45 000 €"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"10 ans et 750 000 €. La violation du secret professionnel, elle, coûte 1 an et 15 000 € (art. 226-13)."},{"id":"es-banque:test:23","m":"es-banque","ch":"PAC","l":"l14","type":"qcm","q":"Quel indicateur du PAC mesure la qualité du développement ?","opts":["La part de marché","Le taux de détention","Le coût du risque","La part contributive"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le coût du risque : une croissance obtenue en dégradant le risque n'est pas une réussite."},{"id":"es-banque:quiz:l1:0","m":"es-banque","ch":"Leçon 1 — Banque à distance, preuve et secret professionnel","l":"l1","type":"qcm","q":"Quelles sont les deux conditions de validité de l'écrit électronique ?","opts":["Identification de l'auteur et garantie d'intégrité","Signature manuscrite scannée et horodatage","Accord du client et archivage 5 ans"],"correct":0,"ex":"Exact. Loi du 14 mars 2000 : les deux conditions sont cumulatives."},{"id":"es-banque:quiz:l1:1","m":"es-banque","ch":"Leçon 1 — Banque à distance, preuve et secret professionnel","l":"l1","type":"qcm","q":"La police peut-elle obtenir le solde d'un compte ?","opts":["Oui, sur simple demande","Uniquement sur réquisition judiciaire ou commission rogatoire","Jamais, en aucun cas"],"correct":1,"ex":"Bien vu. Seules l'ACPR et la Banque de France y accèdent sans condition."},{"id":"es-banque:quiz:l2:0","m":"es-banque","ch":"Leçon 2 — Droit au compte, inclusion bancaire et convention","l":"l2","type":"qcm","q":"Un client se voit refuser l'ouverture d'un compte. Que doit lui remettre la banque ?","opts":["Une lettre motivant le refus","Une attestation de refus, pour saisir la Banque de France","Rien, le refus est discrétionnaire"],"correct":1,"ex":"Exact. La banque n'a pas à se justifier, mais l'attestation ouvre la procédure de désignation d'office."},{"id":"es-banque:quiz:l2:1","m":"es-banque","ch":"Leçon 2 — Droit au compte, inclusion bancaire et convention","l":"l2","type":"qcm","q":"Quelle loi impose la convention de compte écrite ?","opts":["La loi de 1984","La loi MURCEF de 2001","La loi Lagarde de 2010"],"correct":1,"ex":"Bien vu. MURCEF impose aussi la médiation en cas de litige."},{"id":"es-banque:quiz:l3:0","m":"es-banque","ch":"Leçon 3 — Connaissance client et clients protégés","l":"l3","type":"qcm","q":"En curatelle, le curateur…","opts":["Représente le client et agit à sa place","Assiste le client par co-signature","N'a aucun pouvoir bancaire"],"correct":1,"ex":"Exact. C'est le tuteur qui représente ; le curateur assiste seulement."},{"id":"es-banque:quiz:l3:1","m":"es-banque","ch":"Leçon 3 — Connaissance client et clients protégés","l":"l3","type":"qcm","q":"Quelle consultation est obligatoire à l'ouverture d'un compte ?","opts":["Le FCC","Le FICP","Les deux sont facultatives"],"correct":0,"ex":"Bien vu. FCC obligatoire, FICP recommandé à l'ouverture — mais obligatoire avant un octroi de crédit."},{"id":"es-banque:quiz:l4:0","m":"es-banque","ch":"Leçon 4 — Épargne et régimes matrimoniaux","l":"l4","type":"qcm","q":"En communauté réduite aux acquêts, un héritage reçu pendant le mariage est…","opts":["Un bien commun","Un bien propre","Un bien indivis à parts égales"],"correct":1,"ex":"Exact. Les héritages et les biens antérieurs restent propres ; seuls les acquêts sont communs."},{"id":"es-banque:quiz:l4:1","m":"es-banque","ch":"Leçon 4 — Épargne et régimes matrimoniaux","l":"l4","type":"qcm","q":"À quoi le PACS est-il assimilé par défaut ?","opts":["À la communauté réduite aux acquêts","À la séparation de biens","À la communauté universelle"],"correct":1,"ex":"Bien vu. Sauf convention d'indivision contraire signée par les partenaires."},{"id":"es-banque:quiz:l5:0","m":"es-banque","ch":"Leçon 5 — Dévolution, réserve et droits de succession","l":"l5","type":"qcm","q":"Quel est l'abattement en ligne directe parent-enfant ?","opts":["152 500 €","100 000 €","30 500 €"],"correct":1,"ex":"Exact. 152 500 € est l'abattement d'assurance vie avant 70 ans, 30 500 € celui après 70 ans — trois montants à ne jamais confondre."},{"id":"es-banque:quiz:l5:1","m":"es-banque","ch":"Leçon 5 — Dévolution, réserve et droits de succession","l":"l5","type":"qcm","q":"Depuis la loi TEPA de 2007, le conjoint survivant…","opts":["Bénéficie d'un abattement de 100 000 €","Est totalement exonéré de droits de succession","Paie 20 % au-delà de 152 500 €"],"correct":1,"ex":"Bien vu. Exonération totale, également applicable au partenaire de PACS."},{"id":"es-banque:quiz:l6:0","m":"es-banque","ch":"Leçon 6 — L'assurance vie et la règle des 70 ans","l":"l6","type":"qcm","q":"Pour les primes versées après 70 ans, quelle est l'assiette taxable ?","opts":["La totalité du capital décès","Les primes versées seules, les gains étant exonérés","Les gains seuls, les primes étant exonérées"],"correct":1,"ex":"Exact. C'est l'atout du 757 B : l'exonération totale des produits générés par le contrat."},{"id":"es-banque:quiz:l6:1","m":"es-banque","ch":"Leçon 6 — L'assurance vie et la règle des 70 ans","l":"l6","type":"qcm","q":"En 2026, quel taux de prélèvements sociaux s'applique aux gains d'une assurance vie ?","opts":["17,2 % — l'assurance vie est exclue de la hausse","18,6 % comme tous les revenus du capital","0 %, elle est exonérée"],"correct":0,"ex":"Bien vu. La LFSS 2026 a porté les PS à 18,6 % pour le PEA, le CTO et le PER, mais l'assurance vie figure dans les exceptions et reste à 17,2 %."},{"id":"es-banque:quiz:l7:0","m":"es-banque","ch":"Leçon 7 — Prévoyance, santé et retraite","l":"l7","type":"qcm","q":"Que la GAV exclut-elle ?","opts":["Les accidents domestiques","Les accidents de la route et du travail","Les agressions"],"correct":1,"ex":"Exact. La GAV couvre la vie privée ; route et travail relèvent d'autres régimes."},{"id":"es-banque:quiz:l7:1","m":"es-banque","ch":"Leçon 7 — Prévoyance, santé et retraite","l":"l7","type":"qcm","q":"Quelle part de la mutuelle l'employeur finance-t-il depuis l'ANI ?","opts":["30 %","50 %","100 %"],"correct":1,"ex":"Bien vu. La mutuelle est obligatoire pour tous les salariés, financée au minimum à moitié par l'employeur."},{"id":"es-banque:quiz:l8:0","m":"es-banque","ch":"Leçon 8 — Principes généraux et sinistres","l":"l8","type":"qcm","q":"Quel est le délai de déclaration d'un vol ?","opts":["2 jours ouvrés + dépôt de plainte","5 jours ouvrés","10 jours"],"correct":0,"ex":"Exact. 5 jours pour le cas général, 10 jours pour la catastrophe naturelle après l'arrêté."},{"id":"es-banque:quiz:l8:1","m":"es-banque","ch":"Leçon 8 — Principes généraux et sinistres","l":"l8","type":"qcm","q":"Une sur-assurance avec intention frauduleuse entraîne…","opts":["Un plafonnement au réel","La nullité du contrat","La règle proportionnelle"],"correct":1,"ex":"Bien vu. Sans fraude, l'indemnité est simplement plafonnée à la valeur réelle."},{"id":"es-banque:quiz:l9:0","m":"es-banque","ch":"Leçon 9 — Assurance automobile et multirisque habitation","l":"l9","type":"qcm","q":"Quel est le coefficient minimum de bonus ?","opts":["0,25","0,50","0,75"],"correct":1,"ex":"Exact. Le bonus plafonne à 0,50 et le malus à 3,50."},{"id":"es-banque:quiz:l9:1","m":"es-banque","ch":"Leçon 9 — Assurance automobile et multirisque habitation","l":"l9","type":"qcm","q":"La RC auto obligatoire couvre-t-elle les dommages corporels du conducteur responsable ?","opts":["Oui, intégralement","Non, jamais","Oui, mais avec une franchise"],"correct":1,"ex":"Bien vu. C'est précisément pour cela que la garantie du conducteur est indispensable."},{"id":"es-banque:quiz:l10:0","m":"es-banque","ch":"Leçon 10 — L'assurance des emprunteurs","l":"l10","type":"qcm","q":"Quelle loi permet de résilier son assurance emprunteur à tout moment sans frais ?","opts":["La loi Lagarde (2010)","La loi Lemoine (2022)","La convention AERAS"],"correct":1,"ex":"Exact. Lagarde avait instauré le droit à la délégation ; Lemoine y ajoute la résiliation infra-annuelle."},{"id":"es-banque:quiz:l10:1","m":"es-banque","ch":"Leçon 10 — L'assurance des emprunteurs","l":"l10","type":"qcm","q":"À combien la loi Lemoine a-t-elle réduit le droit à l'oubli ?","opts":["10 ans","5 ans après guérison","2 ans"],"correct":1,"ex":"Bien vu. 5 ans après la fin du protocole thérapeutique, pour les anciens cancers et l'hépatite C."},{"id":"es-banque:quiz:l11:0","m":"es-banque","ch":"Leçon 11 — Taux, crédit à la consommation et renouvelable","l":"l11","type":"qcm","q":"Un crédit renouvelable de 2 000 € doit être remboursé en…","opts":["Moins de 3 ans","Moins de 5 ans","Moins de 7 ans"],"correct":0,"ex":"Exact. Le seuil est 3 000 € : en dessous 3 ans maximum, au-dessus 5 ans."},{"id":"es-banque:quiz:l11:1","m":"es-banque","ch":"Leçon 11 — Taux, crédit à la consommation et renouvelable","l":"l11","type":"qcm","q":"À quelle fréquence le FICP est-il consulté sur un crédit renouvelable ?","opts":["Tous les ans","Tous les 3 ans","Une seule fois, à l'octroi"],"correct":0,"ex":"Bien vu. FICP tous les ans, vérification de solvabilité tous les 3 ans (loi Lagarde)."},{"id":"es-banque:quiz:l12:0","m":"es-banque","ch":"Leçon 12 — Financement immobilier, garanties et surendettement","l":"l12","type":"qcm","q":"Dans un prêt à taux modulable, qu'est-ce qui varie ?","opts":["Le taux","La durée","Le capital emprunté"],"correct":1,"ex":"Exact. Le taux reste inchangé, c'est la durée qui s'ajuste. Le taux variable, lui, est indexé sur l'Euribor."},{"id":"es-banque:quiz:l12:1","m":"es-banque","ch":"Leçon 12 — Financement immobilier, garanties et surendettement","l":"l12","type":"qcm","q":"Quel est le délai de réflexion sur une offre de prêt immobilier ?","opts":["10 jours avant de pouvoir accepter","14 jours de rétractation après acceptation","15 jours de validité"],"correct":0,"ex":"Bien vu. C'est l'inverse du crédit conso, où l'on se rétracte après avoir accepté."},{"id":"es-banque:quiz:l13:0","m":"es-banque","ch":"Leçon 13 — Déontologie, conformité et lutte anti-blanchiment","l":"l13","type":"qcm","q":"Quelles sont les trois étapes du blanchiment ?","opts":["Placement, conversion, dissimulation","Dépôt, transfert, retrait","Collecte, fractionnement, investissement"],"correct":0,"ex":"Exact. Trois étapes à restituer dans cet ordre."},{"id":"es-banque:quiz:l13:1","m":"es-banque","ch":"Leçon 13 — Déontologie, conformité et lutte anti-blanchiment","l":"l13","type":"qcm","q":"Peut-on informer le client d'une déclaration de soupçon le concernant ?","opts":["Oui, par obligation de transparence","Jamais, pendant toute la durée de l'investigation","Uniquement si le client le demande"],"correct":1,"ex":"Bien vu. La confidentialité est absolue et sa violation est sanctionnée."},{"id":"es-banque:quiz:l14:0","m":"es-banque","ch":"Leçon 14 — Le Plan d'Action Commercial en agence","l":"l14","type":"qcm","q":"Quel indicateur mesure la qualité du développement, au-delà du volume ?","opts":["La part de marché","Le coût du risque","Le taux de détention"],"correct":1,"ex":"Exact. Il permet de vérifier que la croissance ne se fait pas au prix d'une dégradation du risque."},{"id":"es-banque:quiz:l14:1","m":"es-banque","ch":"Leçon 14 — Le Plan d'Action Commercial en agence","l":"l14","type":"qcm","q":"Quelle est la dernière phase du PAC ?","opts":["La mise en œuvre des moyens","Le contrôle des résultats","Les décisions stratégiques"],"correct":1,"ex":"Bien vu. Le contrôle boucle la démarche et alimente les voies d'amélioration."},{"id":"fiscalite-particulier:quiz:l1:0","m":"fiscalite-particulier","ch":"Leçon 1 — L'impôt sur le revenu : ce que dit l'article 1 A","l":"l1","type":"qcm","q":"Sur quoi porte l'impôt sur le revenu, selon l'article 1 A du CGI ?","opts":["Sur chaque revenu catégoriel pris isolément","Sur le revenu net global du contribuable","Sur le revenu brut encaissé dans l'année"],"correct":1,"ex":"Exact. L'impôt frappe le revenu net global. Les catégories servent à le construire, pas à être imposées séparément."},{"id":"fiscalite-particulier:quiz:l1:1","m":"fiscalite-particulier","ch":"Leçon 1 — L'impôt sur le revenu : ce que dit l'article 1 A","l":"l1","type":"qcm","q":"Les loyers d'un appartement loué vide relèvent de quelle catégorie ?","opts":["Les revenus fonciers","Les revenus de capitaux mobiliers","Les bénéfices industriels et commerciaux"],"correct":0,"ex":"Bien vu. Location nue = revenus fonciers. En location meublée, on bascule en BIC : c'est une distinction qui tombe souvent."},{"id":"fiscalite-particulier:quiz:l2:0","m":"fiscalite-particulier","ch":"Leçon 2 — Les sept caractéristiques de l'impôt sur le revenu","l":"l2","type":"qcm","q":"Un salarié a droit à une prime votée en décembre N, mise à sa disposition en janvier N+1. Elle est imposable au titre de :","opts":["L'année N, année d'acquisition du droit","L'année N+1, année de mise à disposition","L'année au choix du contribuable"],"correct":1,"ex":"Exact. C'est la disponibilité qui compte, pas l'acquisition du droit."},{"id":"fiscalite-particulier:quiz:l2:1","m":"fiscalite-particulier","ch":"Leçon 2 — Les sept caractéristiques de l'impôt sur le revenu","l":"l2","type":"qcm","q":"Le prélèvement à la source a-t-il supprimé la déclaration annuelle de revenus ?","opts":["Oui, depuis le 1er janvier 2019","Non, l'impôt reste déclaratif","Oui, sauf pour les revenus fonciers"],"correct":1,"ex":"Bien vu. Le prélèvement à la source change le moment du paiement, pas la nature déclarative de l'impôt."},{"id":"fiscalite-particulier:quiz:l3:0","m":"fiscalite-particulier","ch":"Leçon 3 — La territorialité : qui est imposable, et sur quoi","l":"l3","type":"qcm","q":"Une personne domiciliée fiscalement hors de France perçoit des loyers d'un immeuble situé à Lyon. Ces loyers sont :","opts":["Imposables en France, sous réserve des conventions","Non imposables en France","Imposables seulement si la personne est française"],"correct":0,"ex":"Exact. Revenu de source française : imposable quel que soit le domicile, et quelle que soit la nationalité. La gestion relève du SIPNR."},{"id":"fiscalite-particulier:quiz:l3:1","m":"fiscalite-particulier","ch":"Leçon 3 — La territorialité : qui est imposable, et sur quoi","l":"l3","type":"qcm","q":"La Polynésie française fait-elle partie du territoire au sens de l'impôt sur le revenu ?","opts":["Oui, comme tous les territoires d'outre-mer","Non, seuls les cinq DOM sont inclus","Oui, depuis la réforme du prélèvement à la source"],"correct":1,"ex":"Bien vu. Guadeloupe, Martinique, Réunion, Guyane et Mayotte — et rien d'autre."},{"id":"fiscalite-particulier:quiz:l4:0","m":"fiscalite-particulier","ch":"Leçon 4 — Le domicile fiscal : quatre critères, un seul suffit","l":"l4","type":"qcm","q":"Une personne a passé 165 jours en France cette année. Le critère du séjour principal est-il rempli ?","opts":["Oui, elle y a séjourné plus de la moitié du temps utile","Non, le seuil est de plus de 183 jours","Cela dépend de sa nationalité"],"correct":1,"ex":"Exact. 165 < 183 : le critère du séjour principal n'est pas rempli. Il reste à examiner le foyer, l'activité professionnelle et le centre des intérêts économiques."},{"id":"fiscalite-particulier:quiz:l4:1","m":"fiscalite-particulier","ch":"Leçon 4 — Le domicile fiscal : quatre critères, un seul suffit","l":"l4","type":"qcm","q":"Les quatre critères de l'article 4 B s'apprécient :","opts":["De manière cumulative : les quatre doivent être remplis","De manière alternative, mais dans un ordre successif","Dans l'ordre que choisit l'administration"],"correct":1,"ex":"Bien vu. Un seul critère suffit, mais l'examen suit l'ordre : personnel, professionnel, économique."},{"id":"fiscalite-particulier:quiz:l5:0","m":"fiscalite-particulier","ch":"Leçon 5 — Le foyer fiscal et le contribuable","l":"l5","type":"qcm","q":"M. MARTIN, veuf, vit sous le toit de sa tante Mme DUBOIS, veuve elle aussi. Combien de foyers fiscaux ?","opts":["Un seul, celui de Mme DUBOIS","Deux foyers fiscaux distincts","Un seul, au choix des intéressés"],"correct":1,"ex":"Exact. Aucun des deux n'est à la charge de l'autre, et vivre sous le même toit ne crée pas de foyer commun. Deux foyers, une part chacun."},{"id":"fiscalite-particulier:quiz:l5:1","m":"fiscalite-particulier","ch":"Leçon 5 — Le foyer fiscal et le contribuable","l":"l5","type":"qcm","q":"Deux concubins ont deux enfants communs mineurs. Combien de foyers fiscaux ?","opts":["Un seul, comme un couple marié","Deux, les enfants étant à la charge de l'un ou de l'autre","Trois, un par adulte et un pour les enfants"],"correct":1,"ex":"Bien vu. Deux foyers. Les enfants sont rattachés à l'un des deux parents — jamais aux deux simultanément pour la même année."},{"id":"fiscalite-particulier:quiz:l6:0","m":"fiscalite-particulier","ch":"Leçon 6 — Les personnes à charge de droit","l":"l6","type":"qcm","q":"La mère d'un contribuable, 74 ans, sans ressources, vit au foyer de son fils. Elle est :","opts":["Personne à charge de droit","Pas à charge : un ascendant valide n'est pas une PAC","Personne à charge sur demande de rattachement"],"correct":1,"ex":"Exact. L'absence de ressources ne crée pas la qualité de personne à charge. Il faudrait une invalidité constatée par une carte, ou avoir plus de 75 ans pour la seule déduction des frais d'accueil."},{"id":"fiscalite-particulier:quiz:l6:1","m":"fiscalite-particulier","ch":"Leçon 6 — Les personnes à charge de droit","l":"l6","type":"qcm","q":"Un enfant infirme de 30 ans, sans carte d'invalidité, vivant chez ses parents :","opts":["Est à charge de droit, mais sans demi-part supplémentaire","N'est pas à charge, faute de carte","Est à charge et ouvre droit à une demi-part supplémentaire"],"correct":0,"ex":"Bien vu. L'infirmité ouvre la qualité de personne à charge à tout âge, mais « l'état d'infirmité ne permet pas de bénéficier d'une demi-part supplémentaire »."},{"id":"fiscalite-particulier:quiz:l7:0","m":"fiscalite-particulier","ch":"Leçon 7 — Le rattachement des enfants majeurs","l":"l7","type":"qcm","q":"Un étudiant en lettres a 24 ans au 1er janvier de l'année d'imposition. Peut-il demander son rattachement ?","opts":["Oui, il a moins de 25 ans et poursuit ses études","Non, il a dépassé 21 ans","Oui, mais seulement s'il vit chez ses parents"],"correct":0,"ex":"Exact. La condition d'études repousse le plafond de 21 à 25 ans. La résidence n'est pas une condition du rattachement."},{"id":"fiscalite-particulier:quiz:l7:1","m":"fiscalite-particulier","ch":"Leçon 7 — Le rattachement des enfants majeurs","l":"l7","type":"qcm","q":"Un enfant majeur marié et chargé de famille se rattache au foyer de ses parents. Qui est rattaché ?","opts":["Lui seul","Lui, son conjoint et ses enfants à charge","Lui et ses enfants, mais pas son conjoint"],"correct":1,"ex":"Bien vu. C'est le rattachement global : tout le foyer de l'enfant concerné bascule dans celui des parents — ou des beaux-parents."},{"id":"fiscalite-particulier:quiz:l8:0","m":"fiscalite-particulier","ch":"Leçon 8 — À quelle date on photographie le foyer","l":"l8","type":"qcm","q":"Un enfant naît le 13 septembre de l'année N. Compte-t-il comme personne à charge au titre de l'année N ?","opts":["Oui : augmentation des charges, on apprécie au 31 décembre","Non, il faudra attendre l'année N+1","Oui, mais pour une demi-part divisée au prorata"],"correct":0,"ex":"Exact. Une naissance augmente les charges de famille : la situation s'apprécie au 31 décembre et l'enfant compte dès l'année N, pour une majoration entière."},{"id":"fiscalite-particulier:quiz:l8:1","m":"fiscalite-particulier","ch":"Leçon 8 — À quelle date on photographie le foyer","l":"l8","type":"qcm","q":"Un couple divorce en cours d'année N. Combien de déclarations pour l'année N ?","opts":["Une commune jusqu'au divorce, puis deux séparées","Deux déclarations séparées pour l'année entière","Une seule déclaration commune pour l'année entière"],"correct":1,"ex":"Bien vu. Divorce, séparation et rupture de PACS : deux déclarations couvrant chacune l'année entière. Le découpage en deux périodes, c'est le cas du décès."},{"id":"fiscalite-particulier:quiz:l9:0","m":"fiscalite-particulier","ch":"Leçon 9 — Le nombre de parts : cas général et case T","l":"l9","type":"qcm","q":"Un couple pacsé avec quatre enfants mineurs dispose de combien de parts ?","opts":["4 parts","5 parts","6 parts"],"correct":1,"ex":"Exact. 2 + 0,5 + 0,5 + 1 + 1 = 5 parts. Les deux premiers enfants valent une demi-part, les suivants une part entière."},{"id":"fiscalite-particulier:quiz:l9:1","m":"fiscalite-particulier","ch":"Leçon 9 — Le nombre de parts : cas général et case T","l":"l9","type":"qcm","q":"Un parent divorcé vivant seul avec deux enfants à sa charge exclusive dispose de :","opts":["2 parts","2,5 parts","3 parts"],"correct":1,"ex":"Bien vu. 1 (divorcé) + 0,5 + 0,5 (case T, 1re PAC) + 0,5 (2e PAC) = 2,5 parts. La demi-part de la case T ne joue qu'une fois."},{"id":"fiscalite-particulier:quiz:l10:0","m":"fiscalite-particulier","ch":"Leçon 10 — Les veufs et les situations d'invalidité","l":"l10","type":"qcm","q":"Une veuve élève seule un enfant mineur. Elle dispose de :","opts":["2 parts","2,5 parts","3 parts, avec la case T"],"correct":1,"ex":"Exact. 1 + 1,5 = 2,5 parts, soit le niveau d'un couple avec un enfant. Pas de case T pour les veufs."},{"id":"fiscalite-particulier:quiz:l10:1","m":"fiscalite-particulier","ch":"Leçon 10 — Les veufs et les situations d'invalidité","l":"l10","type":"qcm","q":"Quel taux de pension d'invalidité ouvre droit à une demi-part supplémentaire ?","opts":["Au moins 40 %","Au moins 80 %","Au moins 50 %"],"correct":0,"ex":"Bien vu. 40 % pour la demi-part liée à la pension ; 80 % est le seuil de la carte qui fait d'une personne sous le toit une personne à charge."},{"id":"fiscalite-particulier:quiz:l11:0","m":"fiscalite-particulier","ch":"Leçon 11 — Du revenu global au revenu net global imposable","l":"l11","type":"qcm","q":"Un déficit global constaté au titre de l'année N est reportable sur les revenus globaux :","opts":["Des 3 années suivantes","Des 6 années suivantes","Sans limitation de durée"],"correct":1,"ex":"Exact. Six ans, et l'imputation se fait en commençant par les déficits les plus anciens — sinon on en perd par péremption."},{"id":"fiscalite-particulier:quiz:l11:1","m":"fiscalite-particulier","ch":"Leçon 11 — Du revenu global au revenu net global imposable","l":"l11","type":"qcm","q":"Dans quel ordre s'enchaînent les quatre étapes ?","opts":["RG → charges → déficits antérieurs → abattements","RG → déficits antérieurs → charges → abattements","RG → abattements → charges → déficits antérieurs"],"correct":1,"ex":"Bien vu. Revenu global, puis revenu brut global (− déficits antérieurs), puis revenu net global (− charges), puis revenu net global imposable (− abattements)."},{"id":"fiscalite-particulier:test:0","m":"fiscalite-particulier","ch":"Principes","l":"l1","type":"qcm","q":"Sur quelle base l'impôt sur le revenu est-il établi, selon l'article 1 A du CGI ?","opts":["Le revenu brut encaissé","Le revenu net global du contribuable","Chaque revenu catégoriel séparément","Le revenu disponible après impôt"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'article 1 A dispose que l'impôt « frappe le revenu net global du contribuable ». Les catégories servent à le construire."},{"id":"fiscalite-particulier:test:1","m":"fiscalite-particulier","ch":"Principes","l":"l1","type":"num","q":"Combien de catégories de revenus l'article 1 A énumère-t-il ?","opts":null,"correct":null,"answer":8,"tol":0,"unit":"catégories","ex":"Huit : revenus fonciers, BIC, rémunérations de dirigeants, BA, traitements et salaires, BNC, RCM et plus-values."},{"id":"fiscalite-particulier:test:2","m":"fiscalite-particulier","ch":"Principes","l":"l1","type":"qcm","q":"Les loyers d'un appartement loué meublé relèvent de quelle catégorie ?","opts":["Revenus fonciers","Bénéfices industriels et commerciaux","Revenus de capitaux mobiliers","Bénéfices non commerciaux"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La location meublée relève des BIC. Seule la location nue donne des revenus fonciers."},{"id":"fiscalite-particulier:test:3","m":"fiscalite-particulier","ch":"Principes","l":"l2","type":"qcm","q":"Le prélèvement à la source, entré en vigueur le 1er janvier 2019, a-t-il supprimé le caractère déclaratif de l'IR ?","opts":["Oui, totalement","Non, la déclaration reste obligatoire","Oui, sauf pour les revenus fonciers","Oui, pour les seuls salariés"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le prélèvement à la source change le moment du paiement, pas la nature déclarative de l'impôt."},{"id":"fiscalite-particulier:test:4","m":"fiscalite-particulier","ch":"Principes","l":"l2","type":"qcm","q":"Un revenu est imposable lorsqu'il est :","opts":["Acquis","Perçu","Disponible","Déclaré"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Seuls les revenus disponibles sont imposables : ceux dont la perception ne dépend plus que de la volonté du bénéficiaire."},{"id":"fiscalite-particulier:test:5","m":"fiscalite-particulier","ch":"Principes","l":"l2","type":"qcm","q":"Quelle affirmation est fausse ? L'impôt sur le revenu est :","opts":["Un impôt d'État","Un impôt progressif par tranches","Un impôt proportionnel à taux unique","Un impôt global et synthétique"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"L'IR est progressif par tranches, pas proportionnel. C'est la flat tax qui est proportionnelle, et elle ne concerne que certains revenus du capital."},{"id":"fiscalite-particulier:test:6","m":"fiscalite-particulier","ch":"Principes","l":"l2","type":"qcm","q":"Sur quelle page de la déclaration n° 2042 porte-t-on les personnes à charge ?","opts":["La 1re","La 2e","La 3e","La 4e"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Page 2 : situation familiale et personnes à charge. Page 3 : traitements, RCM, revenus fonciers. Page 4 : charges déductibles, réductions et crédits."},{"id":"fiscalite-particulier:test:7","m":"fiscalite-particulier","ch":"Territorialité","l":"l3","type":"qcm","q":"Une personne domiciliée fiscalement en France est imposable :","opts":["Sur ses seuls revenus de source française","Sur l'ensemble de ses revenus","Sur ses revenus français et la moitié des étrangers","Uniquement si elle est de nationalité française"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Article 4 A : domicile en France ⇒ imposition sur l'ensemble des revenus, sous réserve des conventions internationales."},{"id":"fiscalite-particulier:test:8","m":"fiscalite-particulier","ch":"Territorialité","l":"l3","type":"qcm","q":"Lequel de ces territoires n'entre pas dans la France au sens de l'IR ?","opts":["La Corse","Mayotte","La Polynésie française","La Guyane"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Seuls la France continentale, la Corse, les îles du littoral et les cinq DOM (Guadeloupe, Martinique, Réunion, Guyane, Mayotte) sont inclus."},{"id":"fiscalite-particulier:test:9","m":"fiscalite-particulier","ch":"Territorialité","l":"l3","type":"qcm","q":"Quelle combinaison échappe à l'impôt sur le revenu français ?","opts":["Domicile en France, revenu de source étrangère","Domicile hors de France, revenu de source française","Domicile hors de France, revenu de source étrangère","Aucune : tout est imposable"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Une seule case sur quatre : domicile hors de France ET revenu de source étrangère."},{"id":"fiscalite-particulier:test:10","m":"fiscalite-particulier","ch":"Territorialité","l":"l3","type":"qcm","q":"Quelle déclaration un résident français encaissant des revenus étrangers doit-il souscrire en annexe de la 2042 ?","opts":["La 2044","La 2047","La 2042-C","La 2031"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La déclaration n° 2047, annexée à la déclaration d'ensemble n° 2042."},{"id":"fiscalite-particulier:test:11","m":"fiscalite-particulier","ch":"Territorialité","l":"l4","type":"num","q":"Au-delà de combien de jours de présence en France le critère du séjour principal est-il rempli ?","opts":null,"correct":null,"answer":183,"tol":0,"unit":"jours","ex":"Plus de 183 jours. Un séjour de 165 jours ne suffit donc pas."},{"id":"fiscalite-particulier:test:12","m":"fiscalite-particulier","ch":"Territorialité","l":"l4","type":"qcm","q":"Les critères de l'article 4 B s'apprécient :","opts":["De manière cumulative","De manière alternative, dans un ordre successif","Dans l'ordre choisi par le contribuable","Uniquement sur le critère économique"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Alternatifs quant à la conséquence — un seul suffit — mais successifs quant à la méthode : personnels, puis professionnel, puis économique."},{"id":"fiscalite-particulier:test:13","m":"fiscalite-particulier","ch":"Territorialité","l":"l4","type":"qcm","q":"Un couple vivant à l'étranger y exploite son entreprise et passe 165 jours par an dans un appartement français habituellement loué. Son domicile fiscal est :","opts":["En France, par le critère du foyer","En France, par le critère économique","Hors de France : aucun critère n'est rempli","En France, par le critère professionnel"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Cas EBREL. Résidence habituelle à l'étranger, moins de 183 jours, activité et intérêts économiques à l'étranger : aucun des quatre critères."},{"id":"fiscalite-particulier:test:14","m":"fiscalite-particulier","ch":"Territorialité","l":"l4","type":"qcm","q":"Quel service gère les dossiers des personnes domiciliées à l'étranger percevant des revenus français ?","opts":["Le SIE","Le SIPNR","La DGFiP centrale","Le centre des impôts du lieu de l'immeuble"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le Service des Impôts des Particuliers des Non Résidents, quelle que soit la nationalité du contribuable."},{"id":"fiscalite-particulier:test:15","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l5","type":"qcm","q":"Deux concubins avec deux enfants communs mineurs forment :","opts":["Un foyer fiscal","Deux foyers fiscaux","Trois foyers fiscaux","Un ou deux, au choix"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le concubinage n'est pas reconnu fiscalement. Deux foyers ; les enfants sont rattachés à l'un ou à l'autre."},{"id":"fiscalite-particulier:test:16","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l5","type":"qcm","q":"À partir de quel événement une personne physique devient-elle contribuable de plein droit ?","opts":["À 16 ans","À la majorité civile à 18 ans ou par le mariage","À la fin des études","Au premier emploi"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Majorité civile à 18 ans, ou mariage."},{"id":"fiscalite-particulier:test:17","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l6","type":"num","q":"Quel taux d'invalidité la carte doit-elle constater pour qu'une personne vivant sous le toit soit à charge ? (en %)","opts":null,"correct":null,"answer":80,"tol":0,"unit":"%","ex":"Au moins 80 % — à ne pas confondre avec les 40 % de la pension qui ouvre une demi-part supplémentaire."},{"id":"fiscalite-particulier:test:18","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l6","type":"qcm","q":"Un enfant infirme de 34 ans vivant chez ses parents, sans carte d'invalidité :","opts":["N'est pas à charge","Est à charge de droit, sans demi-part supplémentaire","Est à charge et ouvre droit à une demi-part","Doit demander son rattachement"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'infirmité rend l'enfant à charge de droit à tout âge, mais « l'état d'infirmité ne permet pas de bénéficier d'une demi-part supplémentaire »."},{"id":"fiscalite-particulier:test:19","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l6","type":"qcm","q":"La mère d'un contribuable, 74 ans, sans ressources, vit à son foyer. Elle est :","opts":["Personne à charge de droit","Personne à charge par rattachement","Pas à charge : ascendant valide","À charge si elle le demande"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Un ascendant valide n'est jamais une personne à charge. À plus de 75 ans, seuls les frais d'accueil deviennent déductibles."},{"id":"fiscalite-particulier:test:20","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l6","type":"qcm","q":"Un enfant mineur recueilli est à charge de droit à condition que le contribuable assume une charge :","opts":["Partielle","Effective et exclusive","Majoritaire","Simplement matérielle"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Charge effective ET exclusive, matérielle comme éducative, et l'enfant doit vivre au foyer."},{"id":"fiscalite-particulier:test:21","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l7","type":"num","q":"Jusqu'à quel âge, apprécié au 1er janvier, un enfant majeur qui poursuit ses études peut-il demander son rattachement ?","opts":null,"correct":null,"answer":25,"tol":0,"unit":"ans (exclus)","ex":"Moins de 25 ans au 1er janvier. Sans condition d'études, le plafond est de moins de 21 ans."},{"id":"fiscalite-particulier:test:22","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l7","type":"qcm","q":"La demande de rattachement d'un enfant majeur est :","opts":["Annuelle et révocable","Annuelle et en principe irrévocable","Définitive jusqu'à 25 ans","Automatique s'il vit au foyer"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Annuelle et en principe irrévocable. Vivre au foyer ne vaut jamais rattachement."},{"id":"fiscalite-particulier:test:23","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l7","type":"qcm","q":"Un enfant majeur marié et chargé de famille se rattache. Qui bascule dans le foyer des parents ?","opts":["Lui seul","Lui et ses enfants","Lui, son conjoint et ses enfants à charge","Lui et son conjoint, sans les enfants"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"C'est le rattachement global : tout le foyer de l'enfant concerné."},{"id":"fiscalite-particulier:test:24","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l8","type":"qcm","q":"Un enfant naît le 13 septembre de l'année N. Pour l'année N, il :","opts":["Ne compte pas","Compte pour une majoration entière","Compte au prorata des mois","Compte pour une demi-majoration"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'augmentation des charges de famille fait apprécier la situation au 31 décembre : majoration entière dès l'année N."},{"id":"fiscalite-particulier:test:25","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l8","type":"qcm","q":"En cas de divorce en cours d'année N, combien de déclarations sont souscrites au titre de N ?","opts":["Une seule, commune","Deux, pour l'année entière chacune","Une commune puis deux séparées","Trois"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Deux déclarations séparées couvrant l'année entière. Le découpage en deux périodes concerne le décès."},{"id":"fiscalite-particulier:test:26","m":"fiscalite-particulier","ch":"Foyer fiscal","l":"l8","type":"qcm","q":"En cas de décès du conjoint en cours d'année, la situation retenue pour le calcul de l'impôt est celle :","opts":["Du 31 décembre","Du 1er janvier de l'année d'imposition","De la date du décès","Au choix du survivant"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"« En cas de décès la situation retenue est celle du 1er janvier de l'année d'imposition » — à la différence du mariage ou du divorce, appréciés au 31 décembre."},{"id":"fiscalite-particulier:test:27","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l9","type":"num","q":"Un couple pacsé avec quatre enfants mineurs : combien de parts ?","opts":null,"correct":null,"answer":5,"tol":0,"unit":"parts","ex":"2 + 0,5 + 0,5 + 1 + 1 = 5 parts. Les deux premiers enfants valent une demi-part, les suivants une part entière."},{"id":"fiscalite-particulier:test:28","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l9","type":"num","q":"Un parent divorcé vivant seul, avec deux enfants à sa charge exclusive : combien de parts ?","opts":null,"correct":null,"answer":2.5,"tol":0,"unit":"parts","ex":"1 + 0,5 + 0,5 (case T sur la 1re PAC) + 0,5 (2e PAC) = 2,5 parts."},{"id":"fiscalite-particulier:test:29","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l9","type":"num","q":"Elena, divorcée, vit seule avec son fils de 6 ans en résidence alternée : combien de parts ?","opts":null,"correct":null,"answer":1.25,"tol":0,"unit":"parts","ex":"1 + (0,5 ÷ 2) = 1,25 part. La résidence alternée divise les majorations par deux et exclut la case T, la charge n'étant pas assumée seul."},{"id":"fiscalite-particulier:test:30","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l9","type":"qcm","q":"La demi-part de la case T bénéficie :","opts":["À chaque personne à charge","À la première personne à charge seulement","Aux veufs également","Aux parents en résidence alternée"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Elle ne joue qu'une fois, sur la première PAC. Elle est exclue en résidence alternée et ne concerne pas les veufs."},{"id":"fiscalite-particulier:test:31","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l10","type":"num","q":"Une veuve élevant seule un enfant mineur : combien de parts ?","opts":null,"correct":null,"answer":2.5,"tol":0,"unit":"parts","ex":"1 + 1,5 = 2,5 parts, soit le niveau d'un couple avec un enfant. Les veufs n'ont pas droit à la case T."},{"id":"fiscalite-particulier:test:32","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l10","type":"num","q":"Quel taux de pension d'invalidité ouvre droit à une demi-part supplémentaire ? (en %)","opts":null,"correct":null,"answer":40,"tol":0,"unit":"%","ex":"Au moins 40 %. Les 80 % sont le seuil de la carte qui fait d'une personne sous le toit une personne à charge."},{"id":"fiscalite-particulier:test:33","m":"fiscalite-particulier","ch":"Nombre de parts","l":"l10","type":"num","q":"M. LAFONT, célibataire vivant seul, pension d'invalidité à 42 %, a recueilli son neveu de 12 ans : combien de parts ?","opts":null,"correct":null,"answer":2.5,"tol":0,"unit":"parts","ex":"1 + 0,5 (1re PAC) + 0,5 (case T) + 0,5 (pension ≥ 40 %) = 2,5 parts."},{"id":"fiscalite-particulier:test:34","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"num","q":"Sur combien d'années un déficit global est-il reportable ?","opts":null,"correct":null,"answer":6,"tol":0,"unit":"années","ex":"Les six années suivantes, en commençant l'imputation par les déficits les plus anciens."},{"id":"fiscalite-particulier:test:35","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"qcm","q":"Quel est l'ordre correct des quatre étapes ?","opts":["RG → charges → déficits antérieurs → abattements","RG → déficits antérieurs → charges → abattements","RG → abattements → déficits antérieurs → charges","RG → déficits antérieurs → abattements → charges"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Revenu global, revenu brut global (− déficits antérieurs), revenu net global (− charges), revenu net global imposable (− abattements)."},{"id":"fiscalite-particulier:test:36","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"qcm","q":"Laquelle de ces charges n'est pas déductible du revenu brut global ?","opts":["Les pensions alimentaires","Les cotisations PERP","Les frais d'accueil d'une personne de plus de 75 ans","Les dons ouvrant droit à réduction d'impôt"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"Les réductions et crédits d'impôt s'appliquent sur l'impôt calculé, jamais sur la base imposable."},{"id":"fiscalite-particulier:test:37","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"num","q":"Micro-foncier : 6 200 € de loyers encaissés. Quel est le revenu foncier net, en euros ?","opts":null,"correct":null,"answer":4340,"tol":0,"unit":"€","ex":"Abattement forfaitaire de 30 % : 6 200 × 0,70 = 4 340 €."},{"id":"fiscalite-particulier:test:38","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"num","q":"Un traitement de 40 600 € brut imposable, déduction forfaitaire de 10 % : quel revenu net catégoriel, en euros ?","opts":null,"correct":null,"answer":36540,"tol":0,"unit":"€","ex":"40 600 × 0,90 = 36 540 €. La déduction de 4 060 € reste bien en deçà du plafond annuel."},{"id":"fiscalite-particulier:test:39","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"num","q":"Revenu global 16 340 €, déficit global antérieur de 1 400 € : quel revenu brut global, en euros ?","opts":null,"correct":null,"answer":14940,"tol":0,"unit":"€","ex":"16 340 − 1 400 = 14 940 € (cas GAONAC'H)."},{"id":"fiscalite-particulier:test:40","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"qcm","q":"Au-delà de quel montant de recettes le régime micro-foncier cesse-t-il de s'appliquer ?","opts":["10 000 €","15 000 €","23 000 €","32 900 €"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Au-delà de 15 000 € de recettes, le régime réel devient obligatoire."},{"id":"fiscalite-particulier:test:41","m":"fiscalite-particulier","ch":"Base d'imposition","l":"l11","type":"qcm","q":"Les charges déductibles du revenu brut global peuvent-elles créer un déficit global ?","opts":["Oui, sans limite","Oui, dans la limite de 10 700 €","Non, elles ne peuvent ni créer ni augmenter un déficit global","Oui, si elles sont justifiées"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Elles diminuent le revenu brut global mais ne peuvent ni créer ni augmenter un déficit global."},{"id":"droits-particuliers:test:0","m":"droits-particuliers","ch":"Naissance","l":"l1","type":"qcm","q":"La personnalité juridique est :","opts":["La capacité d'exercer seul ses droits","L'aptitude à être titulaire de droits et d'obligations","Le fait d'être inscrit à l'état civil","Un statut réservé aux majeurs"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est l'aptitude à être titulaire de droits et assujetti à des obligations. Un nourrisson l'a ; la capacité d'exercice est une autre question."},{"id":"droits-particuliers:test:1","m":"droits-particuliers","ch":"Naissance","l":"l1","type":"qcm","q":"Une SCI familiale qui emprunte auprès de la banque est :","opts":["Un particulier","Une personne morale","Une personne physique","Un groupement sans personnalité"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Une société est une personne morale : elle est exclue de la notion de particulier, qui vise les seules personnes physiques."},{"id":"droits-particuliers:test:2","m":"droits-particuliers","ch":"Naissance","l":"l2","type":"qcm","q":"Lequel de ces critères n'est PAS une condition de la personnalité juridique ?","opts":["Naître","Être vivant","Être viable","Être déclaré en mairie"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"Les trois conditions sont naître, vivant, viable. La déclaration en mairie constate la naissance, elle n'en est pas une condition."},{"id":"droits-particuliers:test:3","m":"droits-particuliers","ch":"Naissance","l":"l2","type":"num","q":"Selon le repère de l'OMS cité en cours, à partir de combien de semaines de grossesse l'enfant est-il viable ?","opts":null,"correct":null,"answer":22,"tol":0,"unit":"semaines","ex":"22 semaines de grossesse, ou un poids de plus de 500 g."},{"id":"droits-particuliers:test:4","m":"droits-particuliers","ch":"Naissance","l":"l2","type":"qcm","q":"Un enfant né vivant mais sans cœur fonctionnel, malformation non opérable, décède aussitôt. On dresse :","opts":["Un acte de naissance et un acte de décès","Un acte d'enfant sans vie","Un acte de décès seul","Aucun acte"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il est né vivant mais non viable : pas de personnalité juridique, acte d'enfant sans vie."},{"id":"droits-particuliers:test:5","m":"droits-particuliers","ch":"Naissance","l":"l2","type":"qcm","q":"L'acte d'enfant sans vie :","opts":["Permet à l'enfant d'hériter","N'emporte aucun effet juridique","Établit sa filiation successorale","Est interdit depuis 2021"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est une reconnaissance humaine (prénoms, nom depuis 2021, obsèques), sans effet juridique."},{"id":"droits-particuliers:test:6","m":"droits-particuliers","ch":"Naissance","l":"l3","type":"num","q":"La période légale de conception commence à quel jour avant la naissance ?","opts":null,"correct":null,"answer":300,"tol":0,"unit":"e jour","ex":"Du 300e au 180e jour inclus avant la naissance (art. 311 C. civ.)."},{"id":"droits-particuliers:test:7","m":"droits-particuliers","ch":"Naissance","l":"l3","type":"qcm","q":"Le père décède ; l'enfant naît vivant et viable 253 jours plus tard. Peut-il hériter ?","opts":["Non, il n'existait pas au décès","Oui, il peut placer sa conception avant le décès","Seulement si ses parents étaient mariés","Seulement avec l'accord des autres héritiers"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"253 jours < 300 : le décès tombe dans la période légale de conception. L'enfant, conçu au jour du décès, hérite."},{"id":"droits-particuliers:test:8","m":"droits-particuliers","ch":"Naissance","l":"l3","type":"qcm","q":"La présomption de durée de grossesse est :","opts":["Irréfragable","Simple","Réservée au juge","Applicable seulement en matière fiscale"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Présomption simple : preuve contraire admise par tout moyen."},{"id":"droits-particuliers:test:9","m":"droits-particuliers","ch":"Décès","l":"l4","type":"qcm","q":"Le certificat de décès est rédigé par :","opts":["L'officier d'état civil","Le médecin","Le notaire","La famille"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le médecin rédige le certificat ; l'officier d'état civil dresse ensuite l'acte de décès."},{"id":"droits-particuliers:test:10","m":"droits-particuliers","ch":"Décès","l":"l4","type":"qcm","q":"En cas de mort suspecte, le médecin coche la case :","opts":["« Décès naturel »","« Obstacle médico-légal »","« Mort cérébrale »","« Disparition »"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'obstacle médico-légal suspend l'inhumation jusqu'au procès-verbal d'un officier de police judiciaire assisté d'un médecin."},{"id":"droits-particuliers:test:11","m":"droits-particuliers","ch":"Décès","l":"l4","type":"num","q":"Combien de minutes dure chaque EEG confirmant une mort cérébrale ?","opts":null,"correct":null,"answer":30,"tol":0,"unit":"minutes","ex":"30 minutes chacun, avec un intervalle minimal de 4 heures entre les deux."},{"id":"droits-particuliers:test:12","m":"droits-particuliers","ch":"Décès","l":"l4","type":"qcm","q":"Lequel n'est PAS un critère clinique de la mort cérébrale ?","opts":["Absence totale de conscience","Abolition des réflexes du tronc cérébral","Absence de ventilation spontanée","Arrêt du cœur"],"correct":3,"answer":null,"tol":null,"unit":"","ex":"Dans la mort cérébrale, le cœur peut battre encore : c'est précisément ce qui la distingue."},{"id":"droits-particuliers:test:13","m":"droits-particuliers","ch":"Décès","l":"l4","type":"qcm","q":"À la place des deux EEG, quel examen permet aussi de confirmer la mort cérébrale ?","opts":["Une radiographie du thorax","Une angiographie cérébrale","Une prise de sang","Un scanner abdominal"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'angiographie montrant l'arrêt de la circulation encéphalique (art. R. 1232-2 CSP)."},{"id":"droits-particuliers:test:14","m":"droits-particuliers","ch":"Décès","l":"l5","type":"qcm","q":"Au décès d'un partenaire pacsé, le PACS :","opts":["Se poursuit avec les héritiers","Prend fin","Est suspendu un an","Devient un mariage"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le décès dissout le mariage et met fin au PACS."},{"id":"droits-particuliers:test:15","m":"droits-particuliers","ch":"Décès","l":"l5","type":"qcm","q":"Qui peut agir pour défendre la mémoire d'un défunt ?","opts":["Personne : la personnalité a disparu","Ses successeurs","Le procureur seul","Uniquement le conjoint"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les successeurs peuvent faire cesser l'atteinte et obtenir des dommages et intérêts."},{"id":"droits-particuliers:test:16","m":"droits-particuliers","ch":"Décès","l":"l5","type":"num","q":"Un écrivain meurt en 1957. En quelle année son œuvre entre-t-elle dans le domaine public (au 1er janvier) ?","opts":null,"correct":null,"answer":2028,"tol":0,"unit":"","ex":"1957 + 70 = 2027 : protection jusqu'au 31/12/2027, domaine public le 01/01/2028."},{"id":"droits-particuliers:test:17","m":"droits-particuliers","ch":"Décès","l":"l5","type":"qcm","q":"Le droit moral de l'auteur est :","opts":["Temporaire, 70 ans","Perpétuel et transmis aux héritiers","Éteint au décès","Cessible à un éditeur"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Perpétuel. C'est le droit patrimonial qui est limité à 70 ans après l'année du décès."},{"id":"droits-particuliers:test:18","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"qcm","q":"Quel juge constate la présomption d'absence ?","opts":["Le juge aux affaires familiales","Le juge des contentieux de la protection","Le juge d'instruction","Le maire"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le juge des contentieux de la protection, au tribunal judiciaire."},{"id":"droits-particuliers:test:19","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"qcm","q":"La présomption d'absence est inscrite :","opts":["Au casier judiciaire","Au répertoire civil, avec mention « RC » en marge de l'acte de naissance","Au fichier des personnes recherchées seulement","Nulle part"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Répertoire civil tenu par le tribunal, et mention RC à l'état civil de l'absent."},{"id":"droits-particuliers:test:20","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"num","q":"Combien d'années après le jugement de présomption l'absence peut-elle être déclarée ?","opts":null,"correct":null,"answer":10,"tol":0,"unit":"ans","ex":"10 ans. Sans jugement de présomption, 20 ans depuis les dernières nouvelles."},{"id":"droits-particuliers:test:21","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"num","q":"Sans jugement de présomption, combien d'années depuis les dernières nouvelles faut-il ?","opts":null,"correct":null,"answer":20,"tol":0,"unit":"ans","ex":"20 ans depuis les dernières nouvelles."},{"id":"droits-particuliers:test:22","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"qcm","q":"Requête publiée le 2 mai 2024. Le tribunal peut déclarer l'absence au plus tôt le :","opts":["2 mai 2024","2 novembre 2024","2 mai 2025","2 mai 2034"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Un an au moins après la publication : 02/05/2025."},{"id":"droits-particuliers:test:23","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"qcm","q":"Pendant la présomption d'absence, le conjoint de l'absent :","opts":["Peut se remarier","Ne peut pas se remarier : le mariage tient","Est automatiquement divorcé","Hérite de l'absent"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'absent est présumé vivant : pas de dissolution du mariage, pas de succession."},{"id":"droits-particuliers:test:24","m":"droits-particuliers","ch":"Absence et disparition","l":"l6","type":"qcm","q":"L'absent réapparaît après le jugement déclaratif. Il récupère :","opts":["Rien","Ses biens dans leur état et le prix de ceux vendus, mais pas son mariage","Ses biens et son mariage","Uniquement son mariage"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Art. 130 et 132 : biens dans leur état, prix des biens aliénés ; le mariage reste dissous."},{"id":"droits-particuliers:test:25","m":"droits-particuliers","ch":"Absence et disparition","l":"l7","type":"qcm","q":"La disparition suppose :","opts":["Un doute total sur la vie ou la mort","Un corps introuvable et une mort quasi certaine","Un départ volontaire","Dix ans sans nouvelles"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Circonstances mettant la vie en danger, corps non retrouvé : la mort est quasi certaine."},{"id":"droits-particuliers:test:26","m":"droits-particuliers","ch":"Absence et disparition","l":"l7","type":"qcm","q":"La disparition aboutit à :","opts":["Un jugement déclaratif d'absence","Un jugement déclaratif de décès","Une présomption d'absence","Un acte d'enfant sans vie"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Jugement déclaratif de décès, transcrit sur les registres ; la succession s'ouvre."},{"id":"droits-particuliers:test:27","m":"droits-particuliers","ch":"Absence et disparition","l":"l7","type":"qcm","q":"Lequel de ces exemples relève de la disparition ?","opts":["Un homme parti un matin sans laisser d'adresse","Une victime du tsunami de 2004 jamais retrouvée","Un enfant dont le corps a été retrouvé dans une rivière","Un expatrié qui ne donne plus de nouvelles"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Catastrophe mettant la vie en danger, corps non retrouvé. Un corps retrouvé (cas de Grégory Villemin) n'est jamais une disparition."},{"id":"droits-particuliers:test:28","m":"droits-particuliers","ch":"Identification","l":"l8","type":"qcm","q":"Les éléments d'identification sont dits « indisponibles », ce qui signifie :","opts":["Qu'ils sont secrets","Qu'on ne peut pas les modifier ou les céder librement","Qu'ils disparaissent au décès","Qu'ils sont réservés aux majeurs"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"On ne change pas son nom ou son état comme on veut : seules les procédures prévues par la loi le permettent."},{"id":"droits-particuliers:test:29","m":"droits-particuliers","ch":"Identification","l":"l8","type":"qcm","q":"Parents mariés, aucune déclaration de choix, filiations établies en même temps. L'enfant porte :","opts":["Le nom de la mère","Le nom du père","Les deux noms par ordre alphabétique","Le nom choisi par l'officier d'état civil"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"À défaut de déclaration et de filiations simultanées : nom du père. L'ordre alphabétique vise le désaccord signalé."},{"id":"droits-particuliers:test:30","m":"droits-particuliers","ch":"Identification","l":"l8","type":"num","q":"À partir de quel âge le consentement de l'enfant est-il requis pour changer son nom ?","opts":null,"correct":null,"answer":13,"tol":0,"unit":"ans","ex":"13 ans ou plus."},{"id":"droits-particuliers:test:31","m":"droits-particuliers","ch":"Identification","l":"l8","type":"qcm","q":"Le changement de nom pour « nom ridicule ou déshonorant » relève :","opts":["D'un formulaire en mairie","D'un décret, sur demande au ministre de la Justice","Du juge aux affaires familiales","Du préfet"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Changement par décret, en justifiant d'un intérêt légitime, après publicité."},{"id":"droits-particuliers:test:32","m":"droits-particuliers","ch":"Identification","l":"l8","type":"qcm","q":"La loi du 2 mars 2022 permet à un majeur :","opts":["De changer de nom librement chaque année","De prendre ou ajouter, une fois dans sa vie, le nom du parent non transmis","De choisir n'importe quel nom","De supprimer son nom"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Une fois dans sa vie, par formulaire auprès de l'officier d'état civil, sans motif à justifier."},{"id":"droits-particuliers:test:33","m":"droits-particuliers","ch":"Identification","l":"l9","type":"qcm","q":"Un prénom paraît contraire à l'intérêt de l'enfant. L'officier d'état civil :","opts":["Refuse de l'inscrire","Avise le procureur, qui peut saisir le JAF","Choisit un autre prénom","Saisit lui-même le JAF"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il inscrit le prénom puis avise le procureur de la République, qui peut saisir le juge aux affaires familiales."},{"id":"droits-particuliers:test:34","m":"droits-particuliers","ch":"Identification","l":"l9","type":"qcm","q":"Le changement de prénom :","opts":["Est payant et passe par un décret","Se demande en mairie, gratuitement, avec un intérêt légitime","Est impossible après 18 ans","Relève du tribunal correctionnel"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"En mairie, gratuit, sous réserve d'un intérêt légitime ; consentement de l'enfant dès 13 ans."},{"id":"droits-particuliers:test:35","m":"droits-particuliers","ch":"Identification","l":"l9","type":"qcm","q":"Depuis la loi du 18 novembre 2016, le refus d'un changement de sexe à l'état civil peut-il se fonder sur l'absence d'opération ?","opts":["Oui","Non","Seulement pour les mineurs","Seulement si l'entourage l'ignore"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Non : ne pas avoir subi de traitement, d'opération ou de stérilisation ne peut motiver un refus."},{"id":"droits-particuliers:test:36","m":"droits-particuliers","ch":"Identification","l":"l10","type":"qcm","q":"Le domicile au sens de l'article 102 du Code civil est :","opts":["L'adresse fiscale","Le lieu du principal établissement","Le lieu de naissance","Le lieu de travail"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le lieu du principal établissement."},{"id":"droits-particuliers:test:37","m":"droits-particuliers","ch":"Identification","l":"l10","type":"num","q":"Après combien d'années de mariage le conjoint étranger d'un Français peut-il en principe demander la nationalité par déclaration ?","opts":null,"correct":null,"answer":4,"tol":0,"unit":"ans","ex":"4 ans, avec communauté de vie ; 5 ans s'il ne justifie pas de 3 ans de résidence en France depuis le mariage."},{"id":"droits-particuliers:test:38","m":"droits-particuliers","ch":"Identification","l":"l10","type":"qcm","q":"Un enfant né en France de parents étrangers devient français à sa majorité s'il réside en France et y a résidé :","opts":["1 an","5 ans depuis l'âge de 11 ans","10 ans depuis sa naissance","Il ne le devient jamais sans naturalisation"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"5 ans de résidence, continue ou non, depuis l'âge de 11 ans (art. 21-7 C. civ.)."},{"id":"droits-particuliers:test:39","m":"droits-particuliers","ch":"Identification","l":"l10","type":"qcm","q":"La naturalisation est accordée :","opts":["Automatiquement à 18 ans","Par décret","Par le maire","Par simple déclaration"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est une décision de l'État, par décret."},{"id":"droits-particuliers:quiz:l1:0","m":"droits-particuliers","ch":"Leçon 1 — Le particulier et la personnalité juridique","l":"l1","type":"qcm","q":"Qu'est-ce que la personnalité juridique ?","opts":["Le fait d'avoir atteint la majorité","L'aptitude à être titulaire de droits et assujetti à des obligations","Le fait d'être inscrit sur une liste électorale"],"correct":1,"ex":"Exact. Un nouveau-né a la personnalité juridique : il peut être propriétaire ou héritier. La majorité concerne la capacité d'exercer seul ses droits, pas leur titularité."},{"id":"droits-particuliers:quiz:l1:1","m":"droits-particuliers","ch":"Leçon 1 — Le particulier et la personnalité juridique","l":"l1","type":"qcm","q":"Une association qui ouvre un compte bancaire est-elle un « particulier » ?","opts":["Oui, si elle n'a pas de but lucratif","Non, c'est une personne morale","Oui, si son président signe seul"],"correct":1,"ex":"Bien vu. Le particulier est une personne physique. Une association, même sans but lucratif, est une personne morale."},{"id":"droits-particuliers:quiz:l2:0","m":"droits-particuliers","ch":"Leçon 2 — Naître vivant et viable","l":"l2","type":"qcm","q":"Un enfant naît vivant et viable puis décède deux heures plus tard, avant toute déclaration en mairie. Quel(s) acte(s) dresse-t-on ?","opts":["Un acte d'enfant sans vie","Un acte de naissance et un acte de décès","Un acte de décès seulement"],"correct":1,"ex":"Exact. Il est né vivant et viable : il a eu la personnalité juridique, même deux heures. On dresse donc les deux actes — et il a pu, pendant ce temps, hériter et transmettre."},{"id":"droits-particuliers:quiz:l2:1","m":"droits-particuliers","ch":"Leçon 2 — Naître vivant et viable","l":"l2","type":"qcm","q":"Les trois conditions « naître, vivant, viable » sont :","opts":["Alternatives : une seule suffit","Cumulatives : il les faut toutes","Laissées à l'appréciation de l'officier d'état civil"],"correct":1,"ex":"Bien vu. Les trois sont cumulatives. Un enfant vivant mais non viable n'acquiert pas la personnalité juridique."},{"id":"droits-particuliers:quiz:l3:0","m":"droits-particuliers","ch":"Leçon 3 — Infans conceptus : l'enfant simplement conçu","l":"l3","type":"qcm","q":"Qui choisit la date de conception retenue dans la période légale ?","opts":["Le médecin accoucheur","Elle est placée selon l'intérêt de l'enfant","Le juge, toujours au 240e jour"],"correct":1,"ex":"Exact. La conception est présumée intervenue à n'importe quel moment de la période, « suivant ce qu'exige l'intérêt de l'enfant »."},{"id":"droits-particuliers:quiz:l3:1","m":"droits-particuliers","ch":"Leçon 3 — Infans conceptus : l'enfant simplement conçu","l":"l3","type":"qcm","q":"La présomption de la période de conception est :","opts":["Irréfragable : aucune preuve contraire","Simple : la preuve contraire est admise par tout moyen","Réservée aux enfants de parents mariés"],"correct":1,"ex":"Bien vu. Présomption simple : on peut prouver par tout moyen que la grossesse a été plus longue ou plus courte."},{"id":"droits-particuliers:quiz:l4:0","m":"droits-particuliers","ch":"Leçon 4 — Constater le décès","l":"l4","type":"qcm","q":"Qui dresse l'acte de décès ?","opts":["Le médecin qui constate la mort","L'officier d'état civil de la commune du décès","L'officier de police judiciaire"],"correct":1,"ex":"Exact. Le médecin rédige le certificat, l'officier d'état civil dresse l'acte. L'officier de police judiciaire n'intervient qu'en cas d'obstacle médico-légal, par un procès-verbal."},{"id":"droits-particuliers:quiz:l4:1","m":"droits-particuliers","ch":"Leçon 4 — Constater le décès","l":"l4","type":"qcm","q":"Quel intervalle minimal sépare les deux EEG confirmant une mort cérébrale ?","opts":["30 minutes","4 heures","24 heures"],"correct":1,"ex":"Bien vu. 30 minutes, c'est la durée de chaque enregistrement ; 4 heures, c'est l'intervalle minimal entre les deux."},{"id":"droits-particuliers:quiz:l5:0","m":"droits-particuliers","ch":"Leçon 5 — Ce qui survit au décès","l":"l5","type":"qcm","q":"Un peintre meurt le 3 juin 1956. Quand son œuvre entre-t-elle dans le domaine public ?","opts":["Le 3 juin 2026","Le 1er janvier 2027","Le 1er janvier 2026"],"correct":1,"ex":"Exact. Protection pendant 1956 puis les 70 années suivantes, donc jusqu'au 31/12/2026. Domaine public le 01/01/2027 (1956 + 71). On ne compte jamais à partir du jour exact du décès."},{"id":"droits-particuliers:quiz:l5:1","m":"droits-particuliers","ch":"Leçon 5 — Ce qui survit au décès","l":"l5","type":"qcm","q":"Lequel de ces contrats prend fin avec le décès du client ?","opts":["La procuration qu'il avait donnée à sa fille","Le droit de propriété sur son appartement, qui disparaît","Aucun : tous passent aux héritiers à l'identique"],"correct":0,"ex":"Bien vu. Le mandat est conclu en considération de la personne : il s'éteint. L'appartement, lui, ne disparaît pas : il entre dans la succession."},{"id":"droits-particuliers:quiz:l6:0","m":"droits-particuliers","ch":"Leçon 6 — L'absence : quand on ne sait pas","l":"l6","type":"qcm","q":"Pendant la présomption d'absence, l'absent est considéré comme :","opts":["Vivant","Décédé","Ni l'un ni l'autre : sa personnalité est suspendue"],"correct":0,"ex":"Exact. Présumé vivant : il garde sa personnalité juridique, son mariage tient, un représentant gère ses biens."},{"id":"droits-particuliers:quiz:l6:1","m":"droits-particuliers","ch":"Leçon 6 — L'absence : quand on ne sait pas","l":"l6","type":"qcm","q":"Après un jugement déclaratif d'absence, l'absent réapparaît. Son mariage :","opts":["Revit automatiquement","Reste dissous","Revit si le conjoint ne s'est pas remarié"],"correct":1,"ex":"Bien vu. Article 132 du Code civil : le mariage reste dissous, même si le jugement déclaratif est annulé. Les biens, eux, sont récupérés."},{"id":"droits-particuliers:quiz:l7:0","m":"droits-particuliers","ch":"Leçon 7 — La disparition, et le tableau qui compare","l":"l7","type":"qcm","q":"Un bateau de pêche fait naufrage par gros temps ; un marin n'est jamais retrouvé. Quelle procédure ?","opts":["Présomption d'absence, puis jugement déclaratif d'absence après 10 ans","Jugement déclaratif de décès, sans délai","Aucune : sans corps, pas de décès"],"correct":1,"ex":"Exact. Circonstances mettant la vie en danger, corps introuvable : c'est une disparition. Le décès peut être déclaré immédiatement."},{"id":"droits-particuliers:quiz:l7:1","m":"droits-particuliers","ch":"Leçon 7 — La disparition, et le tableau qui compare","l":"l7","type":"qcm","q":"Combien d'étapes compte la procédure d'absence ?","opts":["Une","Deux","Trois"],"correct":1,"ex":"Bien vu. Présomption d'absence, puis jugement déclaratif d'absence. La disparition, elle, n'en compte qu'une."},{"id":"droits-particuliers:quiz:l8:0","m":"droits-particuliers","ch":"Leçon 8 — Le nom de famille","l":"l8","type":"qcm","q":"Les parents ne s'entendent pas sur le nom : l'un saisit l'officier d'état civil. Quel nom porte l'enfant ?","opts":["Le nom du père","Les deux noms, dans l'ordre alphabétique","Le nom choisi par le juge aux affaires familiales"],"correct":1,"ex":"Exact. Le désaccord signalé conduit aux deux noms accolés par ordre alphabétique. Le nom du père ne s'impose qu'en l'absence de toute déclaration, quand les filiations sont établies en même temps."},{"id":"droits-particuliers:quiz:l8:1","m":"droits-particuliers","ch":"Leçon 8 — Le nom de famille","l":"l8","type":"qcm","q":"Une majeure veut porter le nom de sa mère, qui ne lui a pas été transmis. Que fait-elle ?","opts":["Une requête au ministre de la Justice, avec un intérêt légitime","Un formulaire en mairie, une fois dans sa vie, sans motif à justifier","C'est impossible : le nom est indisponible"],"correct":1,"ex":"Bien vu. C'est la procédure simplifiée de la loi du 2 mars 2022, absente de tes notes mais très probable à l'examen."},{"id":"droits-particuliers:quiz:l9:0","m":"droits-particuliers","ch":"Leçon 9 — Le prénom et le sexe","l":"l9","type":"qcm","q":"Qui peut saisir le juge aux affaires familiales d'un prénom contraire à l'intérêt de l'enfant ?","opts":["L'officier d'état civil directement","Le procureur de la République, avisé par l'officier d'état civil","N'importe quel membre de la famille"],"correct":1,"ex":"Exact. L'officier d'état civil ne refuse pas lui-même : il avise le procureur, qui décide de saisir ou non le juge aux affaires familiales."},{"id":"droits-particuliers:quiz:l9:1","m":"droits-particuliers","ch":"Leçon 9 — Le prénom et le sexe","l":"l9","type":"qcm","q":"Depuis 2016, pour changer la mention de son sexe à l'état civil, il faut :","opts":["Avoir subi une opération chirurgicale","Rien : une simple déclaration en mairie suffit","Prouver par une réunion suffisante de faits qu'on vit sous l'autre sexe"],"correct":2,"ex":"Bien vu. Ni condition médicale, ni simple déclaration : le tribunal judiciaire examine des faits concrets."},{"id":"droits-particuliers:quiz:l10:0","m":"droits-particuliers","ch":"Leçon 10 — Le domicile et la nationalité","l":"l10","type":"qcm","q":"Le domicile, au sens du Code civil, c'est :","opts":["L'adresse indiquée à l'administration fiscale","Le lieu du principal établissement","Le lieu où l'on a passé plus de 183 jours"],"correct":1,"ex":"Exact. Article 102. Les 183 jours sont un critère du domicile fiscal, pas du domicile civil."},{"id":"droits-particuliers:quiz:l10:1","m":"droits-particuliers","ch":"Leçon 10 — Le domicile et la nationalité","l":"l10","type":"qcm","q":"Le conjoint étranger d'une Française peut demander la nationalité par déclaration après :","opts":["1 an de mariage","4 ans de mariage, avec communauté de vie","10 ans de résidence en France"],"correct":1,"ex":"Bien vu. Quatre ans, porté à cinq s'il ne justifie pas de trois ans de résidence en France depuis le mariage."},{"id":"etudes-marche:test:0","m":"etudes-marche","ch":"Les bases","l":"l1","type":"qcm","q":"L'objectif d'une étude de marché est de :","opts":["Prouver que le produit est bon","Réduire l'incertitude pour aider la prise de décision","Remplacer la décision du dirigeant","Collecter le plus de données possible"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Générer des informations pertinentes pour réduire l'incertitude et aider la décision, sous contrainte de budget et de délai."},{"id":"etudes-marche:test:1","m":"etudes-marche","ch":"Les bases","l":"l1","type":"qcm","q":"Une étude qui cherche à expliquer l'effet d'une campagne sur les ventes est :","opts":["Descriptive","Exploratoire","Causale","Documentaire"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Expliquer un lien de cause à effet : étude causale."},{"id":"etudes-marche:test:2","m":"etudes-marche","ch":"Les bases","l":"l1","type":"qcm","q":"L'audit de magasin relève de quelle méthode de collecte ?","opts":["L'observation","L'interrogation","L'expérimentation","L'étude documentaire"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Audimètre, observation sur le lieu de vente, audit de magasin, panels distributeurs : observation."},{"id":"etudes-marche:test:3","m":"etudes-marche","ch":"Les bases","l":"l1","type":"num","q":"Selon Syntec (2014), quelle part des dépenses d'études va aux études quantitatives ? (en %)","opts":null,"correct":null,"answer":78,"tol":0,"unit":"%","ex":"78 % quanti, 14 % quali, 8 % autres (Syntec 2014)."},{"id":"etudes-marche:test:4","m":"etudes-marche","ch":"Les bases","l":"l2","type":"qcm","q":"Des données produites spécialement pour une étude sont :","opts":["Secondaires","Primaires (ad hoc)","Internes","Documentaires"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les données primaires sont issues d'études ad hoc ; les secondaires existent déjà."},{"id":"etudes-marche:test:5","m":"etudes-marche","ch":"Les bases","l":"l2","type":"qcm","q":"L'étude documentaire consiste à :","opts":["Interroger un échantillon représentatif","Sélectionner, synthétiser et analyser des données secondaires","Animer un focus group","Tester un prix en magasin"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Elle exploite des données qui n'ont pas été produites pour l'étude, gratuites ou payantes."},{"id":"etudes-marche:test:6","m":"etudes-marche","ch":"Les bases","l":"l3","type":"qcm","q":"Le quali répond surtout à la question :","opts":["Combien ?","Pourquoi ?","Quand ?","Où ?"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le quanti dit « combien », le quali explique « pourquoi »."},{"id":"etudes-marche:test:7","m":"etudes-marche","ch":"Les bases","l":"l3","type":"qcm","q":"Lequel de ces éléments caractérise une étude qualitative ?","opts":["Un échantillon large et représentatif","Un questionnaire standardisé et fermé","Une analyse interprétative de verbatims","Une analyse statistique"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Quali : échantillon restreint et diversifié, guide souple, analyse interprétative (verbatims, thèmes)."},{"id":"etudes-marche:test:8","m":"etudes-marche","ch":"Les bases","l":"l3","type":"qcm","q":"Un insight marché est :","opts":["Un chiffre clé du marché","Une réalité pertinente, concrète et jusque-là inexploitée sur une cible","Le résultat d'un test de prix","Une tendance publiée par un cabinet"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il naît d'une analyse subjective et approfondie des données."},{"id":"etudes-marche:test:9","m":"etudes-marche","ch":"Qualitatif","l":"l4","type":"qcm","q":"Combien de temps dure en général un bon entretien individuel ?","opts":["10 à 20 minutes","45 à 90 minutes","2 à 3 heures","Une demi-journée"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Entre 45 et 90 minutes selon le format."},{"id":"etudes-marche:test:10","m":"etudes-marche","ch":"Qualitatif","l":"l4","type":"qcm","q":"L'entretien où l'interviewé est observé en magasin et commente ses gestes est :","opts":["Directif","Non directif","Mixte (observation accompagnée)","Semi-directif"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Entretien + mise en situation réelle : très pertinent, mais long à mettre en place."},{"id":"etudes-marche:test:11","m":"etudes-marche","ch":"Qualitatif","l":"l4","type":"qcm","q":"La technique de variation maximale consiste à :","opts":["Interroger le plus de personnes possible","Faire varier au maximum le profil des répondants selon 2 à 3 critères","Poser des questions de plus en plus difficiles","Tirer les répondants au sort"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"L'échantillon quali est restreint mais hétérogène."},{"id":"etudes-marche:test:12","m":"etudes-marche","ch":"Qualitatif","l":"l5","type":"qcm","q":"« Et puis ? Mais encore ? » sont des reformulations :","opts":["De contrôle","De relance","D'approfondissement","Fermées"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Relance : « Et puis ? » ; contrôle : « Si j'ai bien compris… » ; approfondissement : « Peux-tu me réexpliquer ? »."},{"id":"etudes-marche:test:13","m":"etudes-marche","ch":"Qualitatif","l":"l5","type":"qcm","q":"Laquelle de ces questions est non biaisée ?","opts":["Ne pensez-vous pas que notre produit est meilleur ?","Comment comparez-vous notre produit à celui des concurrents ?","Notre produit est-il meilleur que celui des concurrents ?","Préférez-vous notre excellent produit ?"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Une question ouverte et neutre, qui ne suggère pas la réponse."},{"id":"etudes-marche:test:14","m":"etudes-marche","ch":"Qualitatif","l":"l5","type":"qcm","q":"Pendant l'entretien, l'enquêteur :","opts":["Donne son avis pour relancer","Reste neutre et intervient très peu","Pose surtout des questions fermées","Corrige les erreurs du répondant"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il reste neutre, ne donne jamais son opinion et se contente de reformuler."},{"id":"etudes-marche:test:15","m":"etudes-marche","ch":"Qualitatif","l":"l6","type":"num","q":"Combien de personnes au maximum réunit un focus group selon le cours ?","opts":null,"correct":null,"answer":10,"tol":0,"unit":"personnes","ex":"De 6 à 10 personnes."},{"id":"etudes-marche:test:16","m":"etudes-marche","ch":"Qualitatif","l":"l6","type":"num","q":"Deux réunions de groupe peuvent remplacer combien d'entretiens individuels ?","opts":null,"correct":null,"answer":30,"tol":0,"unit":"entretiens","ex":"Deux focus groups d'une dizaine de personnes ≈ 30 entretiens individuels."},{"id":"etudes-marche:test:17","m":"etudes-marche","ch":"Qualitatif","l":"l6","type":"qcm","q":"Quel est un biais propre au focus group ?","opts":["Le biais de cadrage","La prise de parole dominante et l'influence mutuelle","Le biais de sélection par le média","L'appel à la mémoire"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"D'où le rôle de l'animateur : faire participer tous et éviter les leaders."},{"id":"etudes-marche:test:18","m":"etudes-marche","ch":"Qualitatif","l":"l6","type":"qcm","q":"Le collage est surtout utile :","opts":["Pour mesurer une part de marché","En début de séance de créativité, pour la divergence","Pour prétester un questionnaire","Pour calculer une marge d'erreur"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Technique projective non verbale, très efficace pour l'imprégnation du problème."},{"id":"etudes-marche:test:19","m":"etudes-marche","ch":"Qualitatif","l":"l7","type":"qcm","q":"Dans l'analyse quali, quelle étape vient en dernier ?","opts":["Regrouper par thèmes","Repérer les verbatims","Adapter le positionnement et la communication","Identifier les freins"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Synthétiser → identifier motivations et freins → adapter le projet."},{"id":"etudes-marche:test:20","m":"etudes-marche","ch":"Échantillonnage","l":"l8","type":"qcm","q":"La population mère est :","opts":["L'ensemble des clients actuels","L'ensemble des personnes possédant les informations utiles aux objectifs de l'étude","L'échantillon interrogé","La population française"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"C'est la définition du cours : on part de qui détient l'information."},{"id":"etudes-marche:test:21","m":"etudes-marche","ch":"Échantillonnage","l":"l8","type":"num","q":"Étape de l'enquête : le prétest vient en quelle position sur 7 ?","opts":null,"correct":null,"answer":3,"tol":0,"unit":"e étape","ex":"1 population, 2 rédaction, 3 prétest, 4 administration, 5 saisie, 6 traitement, 7 analyse et rapport."},{"id":"etudes-marche:test:22","m":"etudes-marche","ch":"Échantillonnage","l":"l8","type":"qcm","q":"Quelle méthode est probabiliste ?","opts":["Quotas","Convenance","Stratifiée","Boule de neige"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Aléatoires : simple, systématique, stratifiée, en grappes. Empiriques : convenance, jugement, boule de neige, quotas."},{"id":"etudes-marche:test:23","m":"etudes-marche","ch":"Échantillonnage","l":"l8","type":"qcm","q":"La méthode des quotas suppose de connaître :","opts":["Le nom de chaque individu de la population","La répartition de la population selon certaines caractéristiques","La marge d'erreur à l'avance","Les réponses attendues"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"On fixe a priori des groupes selon des caractéristiques connues et mesurées (sexe, âge…)."},{"id":"etudes-marche:test:24","m":"etudes-marche","ch":"Échantillonnage","l":"l8","type":"num","q":"Population à 52 % de femmes, échantillon de 1 500 personnes. Combien de femmes interroger ?","opts":null,"correct":null,"answer":780,"tol":0,"unit":"femmes","ex":"1 500 × 52 % = 780."},{"id":"etudes-marche:test:25","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"num","q":"Quelle valeur de t retient-on pour un niveau de confiance de 95 % ?","opts":null,"correct":null,"answer":1.96,"tol":0,"unit":"","ex":"t = 1,96."},{"id":"etudes-marche:test:26","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"num","q":"Marge d'erreur pour p = 50 % et n = 1 000, au niveau de 95 % ? (en points, arrondi au dixième)","opts":null,"correct":null,"answer":3.1,"tol":0.05,"unit":"points","ex":"1,96 × √(0,25 ÷ 1 000) ≈ 0,0310, soit ± 3,1 points."},{"id":"etudes-marche:test:27","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"num","q":"Taille d'échantillon pour une marge de ± 5 points avec p = 50 % (95 %) ? (arrondi à l'entier supérieur)","opts":null,"correct":null,"answer":385,"tol":0,"unit":"personnes","ex":"1,96² × 0,25 ÷ 0,05² = 384,16, arrondi à 385."},{"id":"etudes-marche:test:28","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"qcm","q":"Pour diviser la marge d'erreur par 2, il faut multiplier la taille de l'échantillon par :","opts":["2","4","√2","10"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La marge varie comme 1 ÷ √n : ×4 sur n divise la marge par √4 = 2."},{"id":"etudes-marche:test:29","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"qcm","q":"Un sondage donne 52 % de OUI sur 500 personnes. Conclusion ?","opts":["Le OUI l'emportera","Le NON l'emportera","On ne peut rien conclure : l'intervalle (≈ 47,6–56,4 %) contient 50 %","Il faut interroger 52 personnes de plus"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"e ≈ 0,0438 : l'intervalle déborde sous 50 %."},{"id":"etudes-marche:test:30","m":"etudes-marche","ch":"Échantillonnage","l":"l9","type":"num","q":"Taille minimale d'un test de communication (performance d'une publicité) selon le cours ?","opts":null,"correct":null,"answer":150,"tol":0,"unit":"personnes","ex":"150 minimum, 200 à 300 en taille classique."},{"id":"etudes-marche:test:31","m":"etudes-marche","ch":"Questionnaire","l":"l10","type":"qcm","q":"Un avantage des questions fermées est :","opts":["Elles reflètent toujours l'opinion réelle","Elles se codent et se traitent facilement","Elles n'influencent pas le répondant","Elles permettent l'expression libre"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Codage et traitement faciles, passation rapide ; mais elles influencent le répondant."},{"id":"etudes-marche:test:32","m":"etudes-marche","ch":"Questionnaire","l":"l10","type":"num","q":"Expérience de Tversky et Kahneman : quel pourcentage choisit le programme A dans le cadre positif ?","opts":null,"correct":null,"answer":72,"tol":0,"unit":"%","ex":"72 % en cadre positif (« 200 sauvées »), 22 % en cadre négatif (« 400 mourront »)."},{"id":"etudes-marche:test:33","m":"etudes-marche","ch":"Questionnaire","l":"l10","type":"qcm","q":"Pourquoi éviter un « sans opinion » au milieu d'une échelle de Likert ?","opts":["Il rompt l'échelle","Il rend l'échelle paire","Il est interdit par le RGPD","Il allonge le questionnaire"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"« Sans opinion » n'est pas un degré d'accord : placé au milieu, il rompt la continuité de l'échelle."},{"id":"etudes-marche:test:34","m":"etudes-marche","ch":"Questionnaire","l":"l11","type":"qcm","q":"« Combien de yaourts consommez-vous par an ? » est un piège de type :","opts":["Jargon","Appel à la mémoire","Double négation","Deux en un"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Impossible de s'en souvenir sur un an : la réponse sera inventée."},{"id":"etudes-marche:test:35","m":"etudes-marche","ch":"Questionnaire","l":"l11","type":"qcm","q":"« Achèteriez-vous cet ordinateur malgré sa faible capacité de mémoire ? » :","opts":["Suggère la réponse","Est trop personnelle","Est un deux en un","Fait appel à la mémoire"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"« Malgré sa faible capacité » oriente vers le non."},{"id":"etudes-marche:test:36","m":"etudes-marche","ch":"Questionnaire","l":"l11","type":"qcm","q":"Les questions d'identification (âge, revenus, CSP) se placent :","opts":["Au début","Au milieu","À la fin","Dans l'introduction"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"À la fin, pour ne pas heurter le répondant et éviter l'abandon."},{"id":"etudes-marche:test:37","m":"etudes-marche","ch":"Questionnaire","l":"l11","type":"qcm","q":"Quelle mention l'introduction d'un questionnaire doit-elle comporter ?","opts":["Le prix du produit testé","Qu'il n'y a ni bonne ni mauvaise réponse","Le nom des autres répondants","La marge d'erreur"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"But, durée, anonymat, mode de remplissage, et « ni bonne ni mauvaise réponse »."},{"id":"etudes-marche:test:38","m":"etudes-marche","ch":"Questionnaire","l":"l12","type":"qcm","q":"Le mode auto-administré par internet présente surtout :","opts":["Un coût élevé","Un biais de sélection par le média et un faible taux de retour","Un biais de sélection par l'enquêteur","Une fiabilité maximale"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Peu coûteux, mais biais du média (ceux qui ont du temps), mauvaise compréhension possible, faible retour."},{"id":"etudes-marche:test:39","m":"etudes-marche","ch":"Questionnaire","l":"l12","type":"qcm","q":"Lors de la saisie, on doit notamment :","opts":["Éliminer les questionnaires aberrants","Calculer une moyenne des CSP","Supprimer les réponses négatives","Relancer les non-répondants"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Masque de saisie, codage, élimination des questionnaires aberrants. Et une moyenne de CSP n'a aucun sens."},{"id":"etudes-marche:quiz:l1:0","m":"etudes-marche","ch":"Leçon 1 — À quoi sert une étude de marché ?","l":"l1","type":"qcm","q":"Une banque teste deux niveaux de frais sur deux agences comparables pour voir lequel attire le plus de clients. Quelle méthode de collecte utilise-t-elle ?","opts":["L'observation","L'interrogation","L'expérimentation"],"correct":2,"ex":"Exact. Elle manipule une variable (le prix) et attribue l'écart de résultats à cette variable : c'est un test de prix, donc une expérimentation."},{"id":"etudes-marche:quiz:l1:1","m":"etudes-marche","ch":"Leçon 1 — À quoi sert une étude de marché ?","l":"l1","type":"qcm","q":"Une étude qui cherche à comprendre pourquoi les clients quittent la banque est :","opts":["Descriptive","Exploratoire","Causale"],"correct":1,"ex":"Bien vu. Décrire → descriptive ; comprendre → exploratoire ; expliquer (une cause, un effet) → causale."},{"id":"etudes-marche:quiz:l2:0","m":"etudes-marche","ch":"Leçon 2 — Où trouver les données ? L'étude documentaire","l":"l2","type":"qcm","q":"Un rapport sectoriel acheté à un cabinet sur le marché du crédit à la consommation est une source de données :","opts":["Secondaires externes","Secondaires internes","Primaires quantitatives"],"correct":0,"ex":"Exact. Le rapport existe déjà (secondaire) et vient de l'extérieur de l'entreprise (externe). Payant ou gratuit, cela ne change rien."},{"id":"etudes-marche:quiz:l2:1","m":"etudes-marche","ch":"Leçon 2 — Où trouver les données ? L'étude documentaire","l":"l2","type":"qcm","q":"Dans le schéma du cours, les panels figurent parmi les données :","opts":["Secondaires externes","Primaires qualitatives","Internes"],"correct":0,"ex":"Oui. Le cours range les panels dans les données secondaires externes, et les enquêtes et expérimentations dans les données primaires quantitatives."},{"id":"etudes-marche:quiz:l3:0","m":"etudes-marche","ch":"Leçon 3 — Quali ou quanti ? Et qu'est-ce qu'un insight ?","l":"l3","type":"qcm","q":"Quelle est la principale force d'une étude quantitative ?","opts":["L'explication en profondeur","La représentativité, qui permet de généraliser","La souplesse du guide d'entretien"],"correct":1,"ex":"Exact. Le quanti vise la représentativité ; le quali, l'explication en profondeur."},{"id":"etudes-marche:quiz:l3:1","m":"etudes-marche","ch":"Leçon 3 — Quali ou quanti ? Et qu'est-ce qu'un insight ?","l":"l3","type":"qcm","q":"Un insight marché s'obtient par :","opts":["Un calcul de marge d'erreur","Une analyse subjective et approfondie des données","La lecture d'un rapport sectoriel"],"correct":1,"ex":"Bien vu. C'est une réalité concrète, pertinente et jusque-là inexploitée, révélée par une analyse subjective et approfondie."},{"id":"etudes-marche:quiz:l4:0","m":"etudes-marche","ch":"Leçon 4 — Les entretiens individuels","l":"l4","type":"qcm","q":"Quel type d'entretien est le plus utilisé, parce qu'il allie cadre et spontanéité ?","opts":["Directif","Semi-directif","Non directif"],"correct":1,"ex":"Exact. Le semi-directif : un guide souple, l'interviewé développe dans l'ordre qu'il veut, l'enquêteur relance et recentre."},{"id":"etudes-marche:quiz:l4:1","m":"etudes-marche","ch":"Leçon 4 — Les entretiens individuels","l":"l4","type":"qcm","q":"On arrête les entretiens individuels :","opts":["Dès qu'on atteint 30 personnes","Quand un nouvel entretien n'apporte plus d'information nouvelle","Quand l'échantillon est représentatif"],"correct":1,"ex":"Bien vu. C'est le principe de saturation. La représentativité est un objectif du quanti, pas du quali."},{"id":"etudes-marche:quiz:l5:0","m":"etudes-marche","ch":"Leçon 5 — Mener l'entretien sans influencer","l":"l5","type":"qcm","q":"« Si j'ai bien compris, vous trouvez l'application trop compliquée ? » est une reformulation :","opts":["De relance","De contrôle","D'approfondissement"],"correct":1,"ex":"Exact. « Si j'ai bien compris… » vérifie la compréhension de l'enquêteur : c'est une reformulation de contrôle."},{"id":"etudes-marche:quiz:l5:1","m":"etudes-marche","ch":"Leçon 5 — Mener l'entretien sans influencer","l":"l5","type":"qcm","q":"À quoi sert la « phase de purge » ?","opts":["À éliminer les questionnaires aberrants","À lever les craintes du répondant pour le mettre en confiance","À supprimer les questions biaisées du guide"],"correct":1,"ex":"Bien vu. La purge précède l'entretien proprement dit. L'élimination des questionnaires aberrants, elle, intervient à la saisie d'une enquête quanti."},{"id":"etudes-marche:quiz:l6:0","m":"etudes-marche","ch":"Leçon 6 — Le focus group et le collage","l":"l6","type":"qcm","q":"Un participant monopolise la parole dans un focus group. Quel est le rôle de l'animateur ?","opts":["Le laisser parler : il est représentatif","Éviter l'apparition d'un leader et faire participer tout le monde","Donner son propre avis pour rééquilibrer"],"correct":1,"ex":"Exact. La prise de parole dominante est un biais majeur du focus group. L'animateur reste neutre : il ne donne jamais son avis."},{"id":"etudes-marche:quiz:l6:1","m":"etudes-marche","ch":"Leçon 6 — Le focus group et le collage","l":"l6","type":"qcm","q":"Le collage est une technique :","opts":["Projective et non verbale","Quantitative et standardisée","D'observation accompagnée"],"correct":0,"ex":"Bien vu. On s'exprime uniquement par des images, ce qui sert la divergence créative."},{"id":"etudes-marche:quiz:l7:0","m":"etudes-marche","ch":"Leçon 7 — Exploiter les résultats qualitatifs","l":"l7","type":"qcm","q":"Par quoi commence l'analyse d'une étude qualitative ?","opts":["Le calcul d'une moyenne","Le regroupement des réponses par grands thèmes","Le choix d'un nouveau packaging"],"correct":1,"ex":"Exact. On synthétise d'abord par thèmes, verbatims, divergences et signaux faibles ; l'adaptation du projet vient en dernier."},{"id":"etudes-marche:quiz:l7:1","m":"etudes-marche","ch":"Leçon 7 — Exploiter les résultats qualitatifs","l":"l7","type":"qcm","q":"Un verbatim, c'est :","opts":["Le résumé écrit par l'enquêteur","Une phrase spontanée du répondant, citée telle quelle","Un pourcentage de réponses identiques"],"correct":1,"ex":"Bien vu. On le cite mot pour mot : c'est sa force dans un rapport qualitatif."},{"id":"etudes-marche:quiz:l8:0","m":"etudes-marche","ch":"Leçon 8 — L'enquête et l'échantillonnage","l":"l8","type":"qcm","q":"Une banque interroge les clients présents dans son agence un samedi matin. C'est un échantillonnage :","opts":["Aléatoire simple","De convenance","Par quotas"],"correct":1,"ex":"Exact. Ils sont « au bon endroit au bon moment ». Les clients qui viennent en agence le samedi ne ressemblent pas à tous les clients : biais de sélection."},{"id":"etudes-marche:quiz:l8:1","m":"etudes-marche","ch":"Leçon 8 — L'enquête et l'échantillonnage","l":"l8","type":"qcm","q":"Pour interroger des gérants de fortune indépendants, difficiles à trouver, la méthode la plus pratique est :","opts":["L'aléatoire simple","La boule de neige","La convenance"],"correct":1,"ex":"Bien vu. Chaque répondant en désigne d'autres : idéal pour des profils spécifiques (experts, B to B), même si c'est long."},{"id":"etudes-marche:quiz:l9:0","m":"etudes-marche","ch":"Leçon 9 — Taille de l'échantillon et marge d'erreur","l":"l9","type":"qcm","q":"Avec 1 000 personnes, la marge d'erreur est d'environ 3 points. Combien faut-il en interroger pour une marge d'environ 1,5 point ?","opts":["2 000","4 000","1 500"],"correct":1,"ex":"Exact. Diviser la marge par 2 impose de multiplier l'échantillon par 4. Vérification : 1,96 × √(0,25 ÷ 4 000) ≈ 0,0155, soit 1,55 point."},{"id":"etudes-marche:quiz:l9:1","m":"etudes-marche","ch":"Leçon 9 — Taille de l'échantillon et marge d'erreur","l":"l9","type":"qcm","q":"Dans la formule, t = 1,96 correspond à :","opts":["Une marge d'erreur de 1,96 %","Un niveau de confiance de 95 %","Un taux de réponse de 96 %"],"correct":1,"ex":"Bien vu. On retient en général 95 % de chances que la vraie valeur soit dans l'intervalle : t = 1,96."},{"id":"etudes-marche:quiz:l10:0","m":"etudes-marche","ch":"Leçon 10 — Rédiger un questionnaire","l":"l10","type":"qcm","q":"Dans l'expérience de Tversky et Kahneman, pourquoi le choix du programme A passe-t-il de 72 % à 22 % ?","opts":["Parce que le programme A est moins efficace dans la seconde version","Parce que la formulation passe d'un cadre positif à un cadre négatif","Parce que l'échantillon a changé"],"correct":1,"ex":"Exact. Les situations sont identiques ; seule la présentation change. C'est le biais de cadrage."},{"id":"etudes-marche:quiz:l10:1","m":"etudes-marche","ch":"Leçon 10 — Rédiger un questionnaire","l":"l10","type":"qcm","q":"« Votre conseiller est : disponible ↔ injoignable ». C'est une échelle :","opts":["De Likert","À différentiel sémantique","Dichotomique"],"correct":1,"ex":"Bien vu. Deux adjectifs opposés aux extrémités : c'est le différentiel sémantique. Likert mesure un degré d'accord avec une affirmation."},{"id":"etudes-marche:quiz:l11:0","m":"etudes-marche","ch":"Leçon 11 — Les 10 pièges et la structure du questionnaire","l":"l11","type":"qcm","q":"« Êtes-vous satisfait de la rapidité et de l'amabilité de votre conseiller ? » tombe dans le piège :","opts":["De la double négation","Du « deux en un »","De l'appel à la mémoire"],"correct":1,"ex":"Exact. Deux notions dans une question : un client satisfait de l'amabilité mais pas de la rapidité ne peut pas répondre. Il faut deux questions."},{"id":"etudes-marche:quiz:l11:1","m":"etudes-marche","ch":"Leçon 11 — Les 10 pièges et la structure du questionnaire","l":"l11","type":"qcm","q":"Où placer la question « Quel est votre revenu mensuel ? » ?","opts":["Au début, pour qualifier le répondant","À la fin, avec les questions d'identification","Nulle part : c'est interdit"],"correct":1,"ex":"Bien vu. Les questions personnelles vont à la fin pour ne pas heurter le répondant et le pousser à abandonner."},{"id":"etudes-marche:quiz:l12:0","m":"etudes-marche","ch":"Leçon 12 — Du prétest au rapport","l":"l12","type":"qcm","q":"Une enquête en ligne n'est remplie que par des retraités disponibles. De quel biais s'agit-il ?","opts":["Biais de sélection par l'enquêteur","Biais de sélection par le média","Biais de cadrage"],"correct":1,"ex":"Exact. Le mode auto-administré attire ceux qui ont du temps : c'est le média qui sélectionne. Le biais « par l'enquêteur » concerne le face à face."},{"id":"etudes-marche:quiz:l12:1","m":"etudes-marche","ch":"Leçon 12 — Du prétest au rapport","l":"l12","type":"qcm","q":"Le prétest se fait :","opts":["Par internet, auprès de 500 personnes","En face à face, auprès d'une dizaine de personnes de la population mère","Auprès des membres de l'équipe d'étude"],"correct":1,"ex":"Bien vu. Une dizaine de personnes de la cible, en conditions réelles, qui commentent leurs choix à voix haute."},{"id":"systeme-bancaire:test:0","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l1","type":"qcm","q":"Les banques mutualistes et coopératives appartiennent :","opts":["À l'État","À leurs membres, c'est-à-dire leurs clients","À la Banque de France","À des fonds d'investissement"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Elles appartiennent à leurs membres (clients) et sont orientées vers la proximité et des valeurs solidaires."},{"id":"systeme-bancaire:test:1","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l1","type":"qcm","q":"Lequel de ces établissements le cours range-t-il à la fois parmi les grandes banques commerciales et parmi les banques mutualistes ?","opts":["Société Générale","BNP Paribas","Crédit Agricole","BoursoBank (ex-Boursorama)"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Le Crédit Agricole, à l'origine coopérative pour le secteur agricole, figure dans les deux listes."},{"id":"systeme-bancaire:test:2","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l1","type":"qcm","q":"Conseiller une entreprise sur une fusion-acquisition relève :","opts":["D'une banque mutualiste","D'une banque d'investissement et d'affaires","De la Banque de France","De l'ACPR"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les banques d'investissement et d'affaires : fusions et acquisitions, levées de fonds, gestion de portefeuilles."},{"id":"systeme-bancaire:test:3","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l1","type":"qcm","q":"Laquelle de ces missions n'est PAS une mission de la Banque de France selon le cours ?","opts":["Mettre en œuvre la politique monétaire européenne","Surveiller la stabilité financière","Réguler les sociétés cotées en Bourse","Superviser les banques via l'ACPR"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"La régulation des sociétés cotées et des transactions boursières revient à l'AMF."},{"id":"systeme-bancaire:test:4","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l2","type":"qcm","q":"Le compte courant sert surtout :","opts":["À faire fructifier son épargne","Aux transactions quotidiennes : factures, virements, retraits","À financer un logement","À préparer sa retraite"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il est utilisé pour les opérations du quotidien et souvent associé à une carte bancaire."},{"id":"systeme-bancaire:test:5","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l2","type":"qcm","q":"Le crédit professionnel est accordé :","opts":["Aux particuliers pour une voiture","Aux entreprises pour leurs activités courantes ou leurs investissements","Aux primo-accédants","Aux personnes exclues du système bancaire"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Crédit professionnel : prêt aux entreprises, pour leurs activités courantes ou leurs investissements."},{"id":"systeme-bancaire:test:6","m":"systeme-bancaire","ch":"Paysage bancaire","l":"l2","type":"qcm","q":"Lequel de ces services relève de la gestion d'actifs et de patrimoine ?","opts":["Le compte courant","Le crédit renouvelable","L'assurance-vie","Le prêt relais"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Conseil en gestion de patrimoine, assurance-vie, fonds d'investissement, plans de retraite."},{"id":"systeme-bancaire:test:7","m":"systeme-bancaire","ch":"Livret A","l":"l3","type":"num","q":"Quel est le plafond de dépôt du Livret A pour un particulier ? (en euros)","opts":null,"correct":null,"answer":22950,"tol":0,"unit":"€","ex":"22 950 €. Les intérêts capitalisés peuvent faire dépasser ce plafond."},{"id":"systeme-bancaire:test:8","m":"systeme-bancaire","ch":"Livret A","l":"l3","type":"num","q":"Quel est le taux du Livret A depuis le 1er août 2026 ? (en %)","opts":null,"correct":null,"answer":1.7,"tol":0,"unit":"%","ex":"1,7 % depuis le 1er août 2026 (1,5 % du 1er février au 31 juillet 2026). Le taux est révisé au 1er février et au 1er août."},{"id":"systeme-bancaire:test:9","m":"systeme-bancaire","ch":"Livret A","l":"l3","type":"qcm","q":"Un dépôt effectué le 8 janvier commence à rapporter des intérêts :","opts":["Le 8 janvier","Le 9 janvier","Le 16 janvier","Le 1er février"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Règle des quinzaines : le dépôt rapporte à partir de la quinzaine suivante, soit le 16 janvier."},{"id":"systeme-bancaire:test:10","m":"systeme-bancaire","ch":"Livret A","l":"l3","type":"num","q":"Un client verse 1 200 € le 8 janvier, au taux de 1,7 %, sans autre mouvement. Combien d'intérêts au 31 décembre ? (en euros, au centime)","opts":null,"correct":null,"answer":19.55,"tol":0.01,"unit":"€","ex":"23 quinzaines (du 16 janvier au 31 décembre) sur 24 : 1 200 × 1,7 % × 23 ÷ 24 = 19,55 €."},{"id":"systeme-bancaire:test:11","m":"systeme-bancaire","ch":"Livret A","l":"l3","type":"qcm","q":"Les intérêts du Livret A sont capitalisés :","opts":["Chaque quinzaine","Chaque mois","Chaque année au 31 décembre","À la clôture du livret"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Ils s'ajoutent au capital au 31 décembre et rapportent à leur tour l'année suivante."},{"id":"systeme-bancaire:test:12","m":"systeme-bancaire","ch":"Livret A","l":"l4","type":"num","q":"En quelle année le Livret A a-t-il été créé ?","opts":null,"correct":null,"answer":1818,"tol":0,"unit":"","ex":"En 1818, après la chute de Napoléon, pour relancer l'économie en encourageant l'épargne."},{"id":"systeme-bancaire:test:13","m":"systeme-bancaire","ch":"Livret A","l":"l4","type":"num","q":"En quelle année une réforme a-t-elle permis à toutes les banques de distribuer le Livret A ?","opts":null,"correct":null,"answer":2009,"tol":0,"unit":"","ex":"2009. Avant, seules la Caisse d'Épargne et La Banque Postale le distribuaient."},{"id":"systeme-bancaire:test:14","m":"systeme-bancaire","ch":"Livret A","l":"l4","type":"qcm","q":"Que finance la Caisse des Dépôts avec une partie des fonds du Livret A ?","opts":["Les crédits renouvelables","Le logement social et des infrastructures publiques","Les fonds propres des banques","Le Fonds de résolution unique"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Construction et rénovation de logements sociaux, hôpitaux, transports."},{"id":"systeme-bancaire:test:15","m":"systeme-bancaire","ch":"Livret A","l":"l4","type":"qcm","q":"Quel inconvénient du Livret A le cours relève-t-il ?","opts":["Les retraits sont pénalisés","Les intérêts sont imposés","Le taux est souvent inférieur à l'inflation","Il faut bloquer les fonds un an"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"D'où une perte de pouvoir d'achat à long terme. Retraits libres, intérêts exonérés, aucune période de blocage."},{"id":"systeme-bancaire:test:16","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l5","type":"num","q":"Jusqu'à combien d'années un crédit immobilier peut-il aller pour un achat en VEFA, selon la norme HCSF citée par le cours ?","opts":null,"correct":null,"answer":27,"tol":0,"unit":"ans","ex":"25 ans maximum ; 27 ans avec un différé lié à une entrée décalée dans le logement (VEFA, construction, ancien avec travaux)."},{"id":"systeme-bancaire:test:17","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l5","type":"qcm","q":"Le prêt relais représente généralement :","opts":["10 à 20 % du prix du nouveau bien","50 à 80 % de la valeur du bien mis en vente","100 % du nouveau bien","35 % des revenus"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"50 à 80 % de la valeur du bien mis en vente, sur une durée courte de 1 à 2 ans."},{"id":"systeme-bancaire:test:18","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l5","type":"num","q":"Un client vend une maison estimée à 300 000 €. Quel montant maximal de prêt relais selon le repère du cours ? (en euros)","opts":null,"correct":null,"answer":240000,"tol":0,"unit":"€","ex":"300 000 × 80 % = 240 000 € (et 150 000 € au minimum, à 50 %)."},{"id":"systeme-bancaire:test:19","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l5","type":"qcm","q":"Quel prêt est réservé aux foyers dont les revenus ne dépassent pas un plafond, et ouvre droit à l'APL ?","opts":["Le prêt conventionné","Le PAS","Le prêt relais","Le prêt amortissable à taux variable"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le prêt d'accession sociale. Le conventionné ouvre aussi droit à l'APL, mais sans condition de ressources."},{"id":"systeme-bancaire:test:20","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l6","type":"num","q":"Revenus nets de 4 000 € par mois, crédit auto de 300 € par mois. Quelle mensualité maximale pour le crédit immobilier selon la norme HCSF ? (en euros)","opts":null,"correct":null,"answer":1100,"tol":0,"unit":"€","ex":"4 000 × 35 % = 1 400 € tous crédits compris, assurance comprise ; 1 400 − 300 = 1 100 €."},{"id":"systeme-bancaire:test:21","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l6","type":"qcm","q":"La norme HCSF du taux d'endettement (35 %) s'entend :","opts":["Hors assurance emprunteur","Assurance emprunteur comprise","Hors crédits à la consommation","Sur les revenus bruts"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"35 % des revenus nets, toutes mensualités de crédit et assurance emprunteur comprises."},{"id":"systeme-bancaire:test:22","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l6","type":"num","q":"De combien de jours de réflexion l'emprunteur dispose-t-il après l'offre de prêt immobilier ?","opts":null,"correct":null,"answer":10,"tol":0,"unit":"jours","ex":"10 jours avant d'accepter ou de refuser l'offre."},{"id":"systeme-bancaire:test:23","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l6","type":"qcm","q":"Crédit Logement est un exemple :","opts":["D'hypothèque","De société de cautionnement","D'assurance groupe","De prêt aidé"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La caution d'une société comme Crédit Logement est une alternative à l'hypothèque."},{"id":"systeme-bancaire:test:24","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l7","type":"qcm","q":"Depuis quelle loi peut-on changer d'assurance emprunteur à tout moment, sans frais ?","opts":["Loi Hamon (2014)","Loi Bourquin (2018)","Loi Lemoine (2022)","Loi Pinel"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Hamon et Bourquin ont ouvert la délégation ; Lemoine permet le changement à tout moment."},{"id":"systeme-bancaire:test:25","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l7","type":"num","q":"PTZ 2026 selon le cours : montant maximal pour un appartement neuf (logement collectif) à 220 000 € ? (en euros)","opts":null,"correct":null,"answer":110000,"tol":0,"unit":"€","ex":"Jusqu'à 50 % du prix : 220 000 × 50 % = 110 000 €, sous réserve des conditions de revenus et de zone."},{"id":"systeme-bancaire:test:26","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l7","type":"qcm","q":"Pour sa résidence principale, un emprunteur peut-il déduire ses intérêts d'emprunt ?","opts":["Oui, en totalité","Oui, pendant 5 ans","Non, plus depuis 2011","Oui, s'il a un PTZ"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Plus de déduction depuis 2011 pour la résidence principale. En locatif, les intérêts se déduisent des revenus locatifs."},{"id":"systeme-bancaire:test:27","m":"systeme-bancaire","ch":"Crédit immobilier","l":"l7","type":"qcm","q":"Selon le cours, le dispositif Jeanbrun, successeur du Pinel, repose sur :","opts":["Une réduction d'impôt de 21 % sur 12 ans","L'amortissement d'une partie du prix d'un logement collectif, contre une location encadrée de 9 ans","Un prêt à taux zéro","La déduction des intérêts de la résidence principale"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le Pinel offrait une réduction d'impôt jusqu'à 21 % sur 12 ans ; le Jeanbrun (« Relance logement », loi de finances 2026) repose sur l'amortissement d'une partie du prix, contre une location encadrée de 9 ans."},{"id":"systeme-bancaire:test:28","m":"systeme-bancaire","ch":"Crédit conso","l":"l8","type":"num","q":"Avant le 20 novembre 2026, quel est le montant maximal d'un crédit à la consommation selon le cours ? (en euros)","opts":null,"correct":null,"answer":75000,"tol":0,"unit":"€","ex":"200 € à 75 000 € ; le plafond passe à 100 000 € pour les contrats conclus à partir du 20 novembre 2026 (directive (UE) 2023/2225)."},{"id":"systeme-bancaire:test:29","m":"systeme-bancaire","ch":"Crédit conso","l":"l8","type":"qcm","q":"Le prêt personnel est un crédit :","opts":["Affecté à un achat précis","Non affecté : l'argent s'utilise librement","Renouvelable","Réservé à la réinsertion"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Pas besoin de justifier l'utilisation des fonds ; taux fixe, mensualités constantes."},{"id":"systeme-bancaire:test:30","m":"systeme-bancaire","ch":"Crédit conso","l":"l8","type":"qcm","q":"Quel crédit le cours associe-t-il particulièrement au risque de surendettement ?","opts":["Le crédit affecté","Le microcrédit personnel","Le crédit renouvelable","Le crédit-bail"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"Taux élevé et facilité d'accès : le crédit renouvelable (revolving)."},{"id":"systeme-bancaire:test:31","m":"systeme-bancaire","ch":"Crédit conso","l":"l8","type":"qcm","q":"La location avec option d'achat (LOA) correspond :","opts":["Au crédit-bail (leasing)","Au prêt relais","Au crédit affecté","Au prêt conventionné"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"On loue le bien, surtout un véhicule, avec la possibilité de l'acheter en fin de contrat."},{"id":"systeme-bancaire:test:32","m":"systeme-bancaire","ch":"Crédit conso","l":"l9","type":"num","q":"De combien de jours calendaires dispose l'emprunteur pour se rétracter d'un crédit à la consommation ?","opts":null,"correct":null,"answer":14,"tol":0,"unit":"jours","ex":"14 jours calendaires après la signature, sans se justifier."},{"id":"systeme-bancaire:test:33","m":"systeme-bancaire","ch":"Crédit conso","l":"l9","type":"qcm","q":"Pour comparer deux offres de crédit à la consommation, on regarde :","opts":["Le seul taux nominal","Le TAEG","Le montant de la première mensualité","Le nombre d'agences de la banque"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Le TAEG inclut le taux nominal, les frais de dossier et l'assurance emprunteur."},{"id":"systeme-bancaire:test:34","m":"systeme-bancaire","ch":"Crédit conso","l":"l9","type":"qcm","q":"Avant d'accorder un crédit à la consommation, que la loi impose-t-elle au prêteur ?","opts":["De plafonner les mensualités à 33 % des revenus","D'appliquer la norme HCSF de 35 %","D'évaluer la solvabilité de l'emprunteur","Rien : il décide librement"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"La loi impose d'évaluer la solvabilité. Les 33 % ne sont qu'un ancien repère de place, sans valeur réglementaire ; la norme HCSF de 35 % vise le crédit immobilier."},{"id":"systeme-bancaire:test:35","m":"systeme-bancaire","ch":"Crédit conso","l":"l9","type":"qcm","q":"Qui un ménage surendetté peut-il saisir ?","opts":["L'AMF","La Commission de surendettement de la Banque de France","La Caisse des Dépôts","Le HCSF"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Elle propose rééchelonnement, suspension des paiements et, dans les cas extrêmes, effacement des dettes."},{"id":"systeme-bancaire:test:36","m":"systeme-bancaire","ch":"Régulation","l":"l10","type":"qcm","q":"L'ACPR est chargée :","opts":["De réguler les sociétés cotées","De superviser la solvabilité des banques et leur respect des règles prudentielles","De fixer le taux du Livret A","De distribuer le PTZ"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Adossée à la Banque de France, l'ACPR supervise les établissements et protège les consommateurs de services financiers."},{"id":"systeme-bancaire:test:37","m":"systeme-bancaire","ch":"Régulation","l":"l10","type":"qcm","q":"L'objectif de l'AMF est :","opts":["La transparence des marchés et la protection des investisseurs","La politique monétaire","Le financement du logement social","La résolution des crises bancaires"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Elle surveille les sociétés cotées, les fonds d'investissement et les transactions boursières."},{"id":"systeme-bancaire:test:38","m":"systeme-bancaire","ch":"Régulation","l":"l10","type":"qcm","q":"Dans l'UE, Bâle III est mis en œuvre, selon le cours, par :","opts":["La loi Lemoine","Le règlement CRR3 et la directive CRD VI","Le Dodd-Frank Act","Le Code de la consommation"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"CRR3 (applicable depuis le 1er janvier 2025) et CRD VI (applicable depuis le 11 janvier 2026)."},{"id":"systeme-bancaire:test:39","m":"systeme-bancaire","ch":"Régulation","l":"l11","type":"qcm","q":"Laquelle de ces causes de la crise de 2007-2008 le cours cite-t-il ?","opts":["La digitalisation des banques","Les prêts subprime et des produits opaques","Le plafond du Livret A","La loi Hamon"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Prise de risque excessive (subprimes, dérivés), manque de transparence, réglementation insuffisante."},{"id":"systeme-bancaire:test:40","m":"systeme-bancaire","ch":"Régulation","l":"l11","type":"num","q":"En quelle année le Dodd-Frank Act a-t-il été adopté ?","opts":null,"correct":null,"answer":2010,"tol":0,"unit":"","ex":"En 2010, pour réguler plus strictement le secteur financier américain."},{"id":"systeme-bancaire:test:41","m":"systeme-bancaire","ch":"Régulation","l":"l11","type":"qcm","q":"Dans l'Union bancaire, le FRU est :","opts":["Un fonds financé par les banques pour couvrir les coûts des défaillances","L'agence américaine de protection des consommateurs","Le superviseur des plus grandes banques","Un ratio de liquidité"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Fonds de résolution unique ; le MRU organise la résolution, le MSU la supervision par la BCE."},{"id":"systeme-bancaire:test:42","m":"systeme-bancaire","ch":"Régulation","l":"l11","type":"qcm","q":"Quel impact de la régulation accrue le cours relève-t-il ?","opts":["Une hausse de la rentabilité du trading","Un recentrage de certaines banques sur la banque de détail","La disparition des stress tests","La fin des fonds propres obligatoires"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Coûts en hausse, rentabilité en baisse, recentrage sur la banque de détail, plus de transparence."},{"id":"systeme-bancaire:test:43","m":"systeme-bancaire","ch":"Régulation","l":"l12","type":"qcm","q":"Selon le cours, les banques en ligne sont souvent :","opts":["Des startups indépendantes","Des filiales de grands groupes bancaires traditionnels","Des établissements publics","Des sociétés de cautionnement"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Les startups indépendantes, mobile-first, ce sont les néobanques (N26, Revolut, Bunq)."},{"id":"systeme-bancaire:test:44","m":"systeme-bancaire","ch":"Régulation","l":"l12","type":"qcm","q":"Lequel de ces établissements est une néobanque selon le cours ?","opts":["BoursoBank (ex-Boursorama)","Hello bank!","N26","Banque Directe"],"correct":2,"answer":null,"tol":null,"unit":"","ex":"N26 (Allemagne, 2015), comme Revolut et Bunq. BoursoBank (ex-Boursorama) et Hello bank! sont des banques en ligne."},{"id":"systeme-bancaire:test:45","m":"systeme-bancaire","ch":"Régulation","l":"l12","type":"qcm","q":"La « finance verte » désigne :","opts":["Le financement de la transition énergétique et de projets durables","Les frais réduits des banques en ligne","Le Livret A","Le coussin contra-cyclique"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Les banques orientent une part de leurs investissements vers des projets respectueux de l'environnement (énergies renouvelables)."},{"id":"systeme-bancaire:quiz:l1:0","m":"systeme-bancaire","ch":"Leçon 1 — Les acteurs du système bancaire","l":"l1","type":"qcm","q":"Qu'est-ce qui distingue une banque mutualiste ou coopérative ?","opts":["Elle ne fait que du conseil en fusions et acquisitions","Elle appartient à ses membres, c'est-à-dire à ses clients","Elle appartient à l'État","Elle ne reçoit pas de dépôts"],"correct":1,"ex":"Exact. Les banques mutualistes appartiennent à leurs membres (les clients) et sont tournées vers la proximité et des valeurs solidaires : Crédit Agricole, Crédit Mutuel, Banques Populaires et Caisses d'Épargne."},{"id":"systeme-bancaire:quiz:l1:1","m":"systeme-bancaire","ch":"Leçon 1 — Les acteurs du système bancaire","l":"l1","type":"qcm","q":"Par quel organisme la Banque de France supervise-t-elle les banques ?","opts":["L'AMF","La Caisse des Dépôts et Consignations","L'ACPR"],"correct":2,"ex":"Bien vu. L'Autorité de contrôle prudentiel et de résolution (ACPR) est adossée à la Banque de France. L'AMF, elle, régule les marchés financiers."},{"id":"systeme-bancaire:quiz:l2:0","m":"systeme-bancaire","ch":"Leçon 2 — Les services bancaires","l":"l2","type":"qcm","q":"Un client veut financer l'achat d'une voiture. Quel type de crédit relève de cette dépense ?","opts":["Un crédit immobilier","Un crédit à la consommation","Un crédit professionnel"],"correct":1,"ex":"Exact. Le crédit à la consommation finance les achats non immobiliers (voiture, électroménager…). Le crédit professionnel est accordé aux entreprises."},{"id":"systeme-bancaire:quiz:l2:1","m":"systeme-bancaire","ch":"Leçon 2 — Les services bancaires","l":"l2","type":"qcm","q":"Lequel de ces produits n'est PAS un compte d'épargne cité par le cours ?","opts":["Le LDDS","Le PEL","Le compte courant","Le Livret A"],"correct":2,"ex":"Bien vu. Le compte courant sert aux transactions quotidiennes. Livret A, LDDS et PEL sont les produits d'épargne populaires cités par le cours."},{"id":"systeme-bancaire:quiz:l3:0","m":"systeme-bancaire","ch":"Leçon 3 — Le Livret A : définition et fonctionnement","l":"l3","type":"qcm","q":"Une cliente verse 500 € le 20 mars sur son Livret A. À partir de quand ce versement rapporte-t-il des intérêts ?","opts":["Le 20 mars","Le 16 mars","Le 1er avril","Le 31 décembre"],"correct":2,"ex":"Exact. Le 20 mars tombe dans la quinzaine du 16 au 31 mars. Le versement rapporte à partir de la quinzaine suivante, soit le 1er avril."},{"id":"systeme-bancaire:quiz:l3:1","m":"systeme-bancaire","ch":"Leçon 3 — Le Livret A : définition et fonctionnement","l":"l3","type":"qcm","q":"Le Livret A d'un client affiche 23 300 € après capitalisation des intérêts. Que peut-il faire ?","opts":["Rien : la banque doit lui reverser l'excédent sur son compte courant","Il garde ce solde, mais ne peut plus faire de nouveaux dépôts","Il peut verser encore 22 950 €"],"correct":1,"ex":"Bien vu. Les intérêts capitalisés peuvent dépasser le plafond de 22 950 € ; ce sont les nouveaux dépôts qui sont bloqués."},{"id":"systeme-bancaire:quiz:l4:0","m":"systeme-bancaire","ch":"Leçon 4 — Le Livret A : rôle économique, histoire, avantages","l":"l4","type":"qcm","q":"Qui centralise une partie des fonds du Livret A pour financer le logement social ?","opts":["La Banque de France","La Caisse des Dépôts et Consignations","L'ACPR","La Banque centrale européenne"],"correct":1,"ex":"Exact. La CDC finance avec ces fonds des projets d'intérêt général : logements sociaux, hôpitaux, transports."},{"id":"systeme-bancaire:quiz:l4:1","m":"systeme-bancaire","ch":"Leçon 4 — Le Livret A : rôle économique, histoire, avantages","l":"l4","type":"qcm","q":"L'État baisse le taux du Livret A. Quel effet attend-il selon le cours ?","opts":["Que les ménages épargnent davantage","Favoriser la consommation ou le placement vers des produits plus rémunérateurs","Augmenter le plafond de dépôt"],"correct":1,"ex":"Bien vu. Un taux élevé incite à épargner ; un taux faible pousse à consommer ou à placer ailleurs."},{"id":"systeme-bancaire:quiz:l5:0","m":"systeme-bancaire","ch":"Leçon 5 — Caractéristiques et types de prêts immobiliers","l":"l5","type":"qcm","q":"Un client veut acheter un appartement avant d'avoir vendu le sien. Quel prêt lui proposer en complément ?","opts":["Un prêt conventionné","Un prêt relais","Un PTZ","Un crédit renouvelable"],"correct":1,"ex":"Exact. Le prêt relais finance le nouvel achat en attendant la vente de l'ancien bien, sur 1 à 2 ans."},{"id":"systeme-bancaire:quiz:l5:1","m":"systeme-bancaire","ch":"Leçon 5 — Caractéristiques et types de prêts immobiliers","l":"l5","type":"qcm","q":"Quel prêt est accessible à tous, sans condition de ressources, et ouvre droit aux APL ?","opts":["Le prêt conventionné","Le PAS","Le PTZ"],"correct":0,"ex":"Bien vu. Le PAS ouvre aussi droit aux APL, mais il est réservé aux foyers sous plafond de revenus. Le PTZ est soumis à des conditions de revenus."},{"id":"systeme-bancaire:quiz:l6:0","m":"systeme-bancaire","ch":"Leçon 6 — Obtenir un crédit immobilier","l":"l6","type":"qcm","q":"Un client gagne 3 200 € nets par mois et n'a aucun autre crédit. Quelle mensualité maximale (assurance comprise) selon la norme HCSF ?","opts":["1 056 €","1 120 €","1 280 €","1 600 €"],"correct":1,"ex":"Exact. 3 200 × 35 % = 1 120 €, assurance emprunteur comprise. (1 056 € correspondrait aux 33 %, ancien repère de place sans valeur réglementaire.)"},{"id":"systeme-bancaire:quiz:l6:1","m":"systeme-bancaire","ch":"Leçon 6 — Obtenir un crédit immobilier","l":"l6","type":"qcm","q":"Quel est le délai de réflexion après réception de l'offre de prêt immobilier ?","opts":["7 jours","10 jours","14 jours","30 jours"],"correct":1,"ex":"Bien vu. 10 jours de réflexion avant d'accepter ou de refuser l'offre. Les 14 jours, c'est la rétractation du crédit à la consommation."},{"id":"systeme-bancaire:quiz:l7:0","m":"systeme-bancaire","ch":"Leçon 7 — Aides, fiscalité et optimisation","l":"l7","type":"qcm","q":"Quelle loi permet de changer d'assurance emprunteur à tout moment, sans frais ?","opts":["La loi Hamon (2014)","La loi Bourquin (2018)","La loi Lemoine (2022)","La loi Denormandie"],"correct":2,"ex":"Exact. Depuis la loi Lemoine (2022), plus besoin d'attendre la date anniversaire. Hamon et Bourquin avaient ouvert la délégation d'assurance."},{"id":"systeme-bancaire:quiz:l7:1","m":"systeme-bancaire","ch":"Leçon 7 — Aides, fiscalité et optimisation","l":"l7","type":"qcm","q":"Un client achète un appartement qu'il va louer. Que peut-il faire des intérêts d'emprunt ?","opts":["Rien : la déduction est supprimée depuis 2011","Les déduire de ses revenus locatifs","Obtenir une réduction d'impôt de 21 % du prix"],"correct":1,"ex":"Bien vu. La suppression de 2011 concerne la résidence principale. En locatif, les intérêts se déduisent des revenus locatifs. Les 21 % étaient le maximum du Pinel, qui ne s'applique plus depuis 2025."},{"id":"systeme-bancaire:quiz:l8:0","m":"systeme-bancaire","ch":"Leçon 8 — Les types de crédits à la consommation","l":"l8","type":"qcm","q":"Quel crédit est annulé si l'achat qu'il finance ne se réalise pas ?","opts":["Le prêt personnel","Le crédit affecté","Le crédit renouvelable","Le microcrédit personnel"],"correct":1,"ex":"Exact. Le crédit affecté est lié à l'achat d'un bien ou d'un service précis : si la vente échoue, le prêt tombe."},{"id":"systeme-bancaire:quiz:l8:1","m":"systeme-bancaire","ch":"Leçon 8 — Les types de crédits à la consommation","l":"l8","type":"qcm","q":"Un jeune sans accès au crédit bancaire veut financer son permis de conduire pour trouver un emploi. Quel crédit correspond ?","opts":["Un crédit renouvelable","Un crédit-bail","Un microcrédit personnel"],"correct":2,"ex":"Bien vu. Le microcrédit personnel (jusqu'à 8 000 €, sur 7 ans maximum) finance des projets de réinsertion, avec un accompagnement social."},{"id":"systeme-bancaire:quiz:l9:0","m":"systeme-bancaire","ch":"Leçon 9 — Souscription, droits de l'emprunteur et surendettement","l":"l9","type":"qcm","q":"Une cliente a signé un prêt personnel et change d'avis. De combien de jours dispose-t-elle pour renoncer ?","opts":["7 jours","10 jours","14 jours calendaires","Aucun : le contrat est signé"],"correct":2,"ex":"Exact. 14 jours calendaires après la signature, sans avoir à se justifier."},{"id":"systeme-bancaire:quiz:l9:1","m":"systeme-bancaire","ch":"Leçon 9 — Souscription, droits de l'emprunteur et surendettement","l":"l9","type":"qcm","q":"Laquelle de ces mesures la Commission de surendettement peut-elle proposer dans les cas extrêmes ?","opts":["Un nouveau crédit renouvelable","L'effacement partiel ou total des dettes","La saisie du Livret A par la CDC"],"correct":1,"ex":"Bien vu. Rééchelonnement, suspension des paiements, et effacement partiel ou total dans les cas extrêmes."},{"id":"systeme-bancaire:quiz:l10:0","m":"systeme-bancaire","ch":"Leçon 10 — La régulation et la supervision","l":"l10","type":"qcm","q":"Quelle autorité surveille les sociétés cotées et les transactions boursières ?","opts":["L'ACPR","L'AMF","La Caisse des Dépôts","Le HCSF"],"correct":1,"ex":"Exact. L'AMF régule les marchés financiers : sociétés cotées, fonds d'investissement, transactions boursières."},{"id":"systeme-bancaire:quiz:l10:1","m":"systeme-bancaire","ch":"Leçon 10 — La régulation et la supervision","l":"l10","type":"qcm","q":"Dans quel cadre la BCE supervise-t-elle les plus grandes banques européennes ?","opts":["Le Mécanisme de surveillance unique (MSU)","Le Fonds de résolution unique (FRU)","Le Dodd-Frank Act"],"correct":0,"ex":"Bien vu. Le MSU confie à la BCE la supervision directe des plus grandes banques. Le FRU sert à financer les défaillances (leçon 11)."},{"id":"systeme-bancaire:quiz:l11:0","m":"systeme-bancaire","ch":"Leçon 11 — La crise de 2007-2008 et la régulation accrue","l":"l11","type":"qcm","q":"Le coussin (buffer) contra-cyclique de Bâle III oblige les banques à :","opts":["Ne plus prêter en période de crise","Mettre du capital de côté en période de croissance","Passer des stress tests américains","Financer le Fonds de résolution unique"],"correct":1,"ex":"Exact. Le capital mis de côté en période de croissance sert à absorber les pertes en période de crise."},{"id":"systeme-bancaire:quiz:l11:1","m":"systeme-bancaire","ch":"Leçon 11 — La crise de 2007-2008 et la régulation accrue","l":"l11","type":"qcm","q":"La Volcker Rule appartient à :","opts":["Bâle III","Le Dodd-Frank Act (États-Unis)","L'Union bancaire européenne"],"correct":1,"ex":"Bien vu. Adopté en 2010, le Dodd-Frank Act comprend la Volcker Rule, les stress tests et la création du CFPB."},{"id":"systeme-bancaire:quiz:l12:0","m":"systeme-bancaire","ch":"Leçon 12 — Les défis : digital, néobanques, finance verte","l":"l12","type":"qcm","q":"Selon le cours, quel est le principal inconvénient des banques en ligne ?","opts":["Des frais de tenue de compte élevés","L'absence de conseiller physique","L'impossibilité d'ouvrir un livret réglementé","Des horaires d'ouverture limités"],"correct":1,"ex":"Exact. C'est un frein pour les besoins complexes (crédit immobilier, investissement). Les banques en ligne proposent bien des livrets réglementés et sont accessibles 24 h/24."},{"id":"systeme-bancaire:quiz:l12:1","m":"systeme-bancaire","ch":"Leçon 12 — Les défis : digital, néobanques, finance verte","l":"l12","type":"qcm","q":"Qu'est-ce qui distingue une néobanque d'une banque en ligne, selon le cours ?","opts":["C'est une startup indépendante, mobile-first, alors que la banque en ligne est souvent une filiale d'un grand groupe","Elle dispose d'un réseau d'agences","Elle propose toujours plus de crédits"],"correct":0,"ex":"Bien vu. Les néobanques (Revolut, N26, Bunq) sont des startups indépendantes ; leurs services peuvent être plus limités (pas de crédits, d'assurances…)."},{"id":"produits-derives-2:test:0","m":"produits-derives-2","ch":"Le marché des Futures","l":"l1","type":"qcm","q":"Une PME lyonnaise doit payer exactement 437 800 USD à un fournisseur texan le 17 mars. Quel argument plaide pour un forward avec sa banque plutôt que pour des Futures ?","opts":["Le forward supprime le risque de contrepartie","Le forward se fait sur mesure : montant et date exacts","Le forward se revend facilement sur le marché","Le forward règle les gains et les pertes chaque soir"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Forward = gré à gré, sur mesure (437 800 USD au 17 mars). Le Future est standardisé (taille, échéance) : il ne couvrirait qu'un multiple de la taille, à une échéance trimestrielle. Pas de contrepartie risquée, revente facile et règlement quotidien sont des atouts du Future."},{"id":"produits-derives-2:test:1","m":"produits-derives-2","ch":"Le marché des Futures","l":"l1","type":"qcm","q":"Un trader a acheté 5 Futures EUR/USD sur le CME. Le lendemain, l'opérateur qui les lui a vendus fait faillite. Que se passe-t-il pour le trader ?","opts":["Il perd ses gains latents","Rien : sa contrepartie est la chambre de compensation","Sa position est annulée et son deposit remboursé","Sa banque reprend la position à sa place"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"La chambre de compensation est l'acheteur de tous les vendeurs et le vendeur de tous les acheteurs. Protégée par les deposits et les appels de marge quotidiens, elle supprime le risque de contrepartie."},{"id":"produits-derives-2:test:2","m":"produits-derives-2","ch":"Le marché des Futures","l":"l1","type":"qcm","q":"Une entreprise couverte par des Futures échéance juin encaisse ses devises le 12 mai. Que fait-elle le 12 mai ?","opts":["Elle attend juin pour se faire livrer les devises","Elle prend la position inverse : elle liquide ses contrats","Elle demande le remboursement de son deposit","Rien, la couverture s'arrête seule"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Un Future est presque toujours dénoué avant l'échéance (E > t) : le jour où l'on encaisse ou paie, on revend les contrats achetés (ou on rachète ceux vendus)."},{"id":"produits-derives-2:test:3","m":"produits-derives-2","ch":"Le marché des Futures","l":"l2","type":"num","q":"Le contrat yen du CME porte sur 12 500 000 JPY, coté en USD pour 1 JPY, avec un tick de 0,0000005 USD. Que vaut un tick, en USD ?","opts":null,"correct":null,"answer":6.25,"tol":0.001,"unit":"USD","ex":"Tick en valeur = tick × T = 0,0000005 × 12 500 000 = 6,25 USD par contrat.","aide":{"f":["fut-tick"],"t":"On te donne le tick (plus petite variation du cours, en USD pour 1 JPY) et la taille du contrat : le tick en valeur est leur produit. Attention aux zéros : 0,0000005 = 5 dix-millionièmes."}},{"id":"produits-derives-2:test:4","m":"produits-derives-2","ch":"Le marché des Futures","l":"l2","type":"num","q":"Un trader achète 6 contrats GBP/USD (62 500 GBP) à 1,2715 et les revend à 1,2683. Quel est son résultat ? (en USD, à l'unité, signe compris)","opts":null,"correct":null,"answer":-1200,"tol":0.5,"unit":"USD","ex":"Résultat = (F vente − F achat) × T × N = (1,2683 − 1,2715) × 62 500 × 6 = −0,0032 × 375 000 = −1 200 USD.","aide":{"f":["fut-resultat"],"t":"Le trader a acheté puis revendu : son résultat est (cours de vente − cours d'achat) × T × N. Commence par l'écart 1,2683 − 1,2715 : le cours a baissé, attends-toi à un résultat négatif."}},{"id":"produits-derives-2:test:5","m":"produits-derives-2","ch":"Le marché des Futures","l":"l2","type":"num","q":"Contrat GBP/USD de 62 500 GBP, tick de 0,0001 USD. Un fonds vendeur de 10 contrats voit le cours baisser de 38 ticks. Quel est son gain ? (en USD)","opts":null,"correct":null,"answer":2375,"tol":0.5,"unit":"USD","ex":"Tick en valeur = 0,0001 × 62 500 = 6,25 USD. Gain = ticks × tick en valeur × N = 38 × 6,25 × 10 = 2 375 USD (le vendeur gagne quand le cours baisse).","aide":{"f":["fut-tick","fut-resultat"],"t":"L'énoncé raisonne en ticks : calcule d'abord le tick en valeur (tick × T), puis prends la 2e forme du résultat : nombre de ticks × tick en valeur × N. Le fonds est vendeur et le cours baisse : c'est un gain."}},{"id":"produits-derives-2:test:6","m":"produits-derives-2","ch":"Le marché des Futures","l":"l2","type":"num","q":"Le Future EUR/USD passe de 1,08415 à 1,08640 ; le tick est de 0,00005 USD. De combien de ticks a-t-il monté ?","opts":null,"correct":null,"answer":45,"tol":0,"unit":"ticks","ex":"Nombre de ticks = écart de cours ÷ tick = 0,00225 ÷ 0,00005 = 45 ticks.","aide":{"f":["fut-tick"],"t":"Un tick est la plus petite variation du cours. Le nombre de ticks, c'est l'écart de cours divisé par le tick : calcule d'abord 1,08640 − 1,08415."}},{"id":"produits-derives-2:test:7","m":"produits-derives-2","ch":"Système de marges","l":"l3","type":"num","q":"Un gérant achète 12 contrats EUR/USD (125 000 EUR), tick de 0,0001 USD, limite de variation quotidienne de 80 ticks. Quel deposit couvre la perte maximale d'une journée ? (en USD)","opts":null,"correct":null,"answer":12000,"tol":0.5,"unit":"USD","ex":"Deposit = limite (ticks) × tick en valeur × N = 80 × (0,0001 × 125 000) × 12 = 80 × 12,5 × 12 = 12 000 USD.","aide":{"f":["fut-deposit","fut-tick"],"t":"Le deposit couvre la perte maximale d'une journée : limite de variation (en ticks) × tick en valeur × nombre de contrats. Commence par le tick en valeur : 0,0001 × 125 000."}},{"id":"produits-derives-2:test:8","m":"produits-derives-2","ch":"Système de marges","l":"l3","type":"num","q":"Deposit de 2 200 USD par contrat pour 8 contrats, marge de maintenance de 70 %. En dessous de quel solde le compte reçoit-il un appel de marge ? (en USD)","opts":null,"correct":null,"answer":12320,"tol":0.5,"unit":"USD","ex":"Deposit = 2 200 × 8 = 17 600 USD. Maintenance = 70 % × 17 600 = 12 320 USD : appel si le solde passe sous ce montant.","aide":{"f":["fut-maintenance","fut-appel-marge"],"t":"L'appel de marge se déclenche quand le solde passe sous la marge de maintenance, un pourcentage du deposit total. Calcule d'abord le deposit total (deposit par contrat × nombre de contrats), puis prends-en 70 %."}},{"id":"produits-derives-2:test:9","m":"produits-derives-2","ch":"Système de marges","l":"l3","type":"qcm","q":"Deposit de 20 000 USD, marge de maintenance de 15 000 USD. Après la séance, le solde du compte de marge est de 13 400 USD. Quel appel de marge l'opérateur reçoit-il ?","opts":["1 600 USD","6 600 USD","13 400 USD","Aucun appel"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"13 400 < 15 000 : appel de marge. Appel = deposit − solde = 20 000 − 13 400 = 6 600 USD. Le compte revient au deposit, pas à la maintenance (1 600 USD serait l'erreur classique)."},{"id":"produits-derives-2:test:10","m":"produits-derives-2","ch":"Système de marges","l":"l3","type":"qcm","q":"Un compte de marge a un deposit de 20 000 USD et une maintenance de 15 000 USD. Après une séance perdante, le solde tombe à 16 200 USD. Que se passe-t-il ?","opts":["Appel de 3 800 USD pour revenir au deposit","Aucun appel : le solde reste au-dessus de la maintenance","Appel de 1 200 USD","La position est liquidée d'office"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"On compare le solde à la maintenance, pas au deposit : 16 200 ≥ 15 000, donc aucun appel de marge."},{"id":"produits-derives-2:test:11","m":"produits-derives-2","ch":"Système de marges","l":"l4","type":"num","q":"Un fonds a vendu 6 contrats GBP/USD (62 500 GBP) à 1,2640. Le soir, le cours de compensation est de 1,2712. Quel est son résultat du jour ? (en USD, signe compris)","opts":null,"correct":null,"answer":-2700,"tol":0.5,"unit":"USD","ex":"Vendeur : résultat = (F veille − F jour) × T × N = (1,2640 − 1,2712) × 375 000 = −0,0072 × 375 000 = −2 700 USD.","aide":{"f":["fut-resultat-jour"],"t":"Il est vendeur : résultat du jour = (F de la veille − F du jour) × T × N. Le premier jour, le cours « de la veille » est celui auquel il a ouvert la position (1,2640). Le cours a monté : un vendeur perd."}},{"id":"produits-derives-2:test:12","m":"produits-derives-2","ch":"Système de marges","l":"l4","type":"num","q":"Acheteur de 4 contrats EUR/USD (125 000 EUR) à 1,0800. Deposit de 2 500 USD par contrat, maintenance de 75 %. Cours de compensation : 1,0770 le jour 1, puis 1,0815 le jour 2. Quel est le solde du compte de marge à la fin du jour 2 ? (en USD)","opts":null,"correct":null,"answer":10750,"tol":0.5,"unit":"USD","ex":"Deposit = 10 000 USD, maintenance = 7 500 USD, T × N = 500 000. Jour 1 : (1,0770 − 1,0800) × 500 000 = −1 500, solde 8 500 ≥ 7 500, pas d'appel. Jour 2 : (1,0815 − 1,0770) × 500 000 = +2 250, solde 10 750 USD.","aide":{"f":["fut-resultat-jour","fut-solde","fut-appel-marge"],"t":"Suis le compte jour par jour. Pars du deposit total (2 500 × 4) et de la maintenance (75 %). Jour 1 : résultat de l'acheteur = (F du jour 1 − 1,0800) × T × N, puis nouveau solde ; vérifie s'il passe sous la maintenance (appel) avant le jour 2, dont le cours « de la veille » est celui du jour 1."}},{"id":"produits-derives-2:test:13","m":"produits-derives-2","ch":"Système de marges","l":"l4","type":"num","q":"Vendeur de 5 contrats EUR/USD (125 000 EUR) à 1,1000. Deposit de 3 000 USD par contrat, maintenance de 80 %. Le soir, le cours de compensation est de 1,1060. Quel appel de marge doit-il verser ? (en USD)","opts":null,"correct":null,"answer":3750,"tol":0.5,"unit":"USD","ex":"Deposit = 15 000, maintenance = 12 000. Résultat du jour (vendeur) = (1,1000 − 1,1060) × 625 000 = −3 750, solde 11 250 < 12 000 : appel = deposit − solde = 15 000 − 11 250 = 3 750 USD.","aide":{"f":["fut-resultat-jour","fut-appel-marge"],"t":"Pars du deposit total (3 000 × 5) et de la maintenance (80 %). Calcule le résultat du jour du vendeur, (1,1000 − 1,1060) × T × N, puis le solde. S'il passe sous la maintenance, l'appel ramène le compte au deposit, pas à la maintenance."}},{"id":"produits-derives-2:test:14","m":"produits-derives-2","ch":"Système de marges","l":"l4","type":"num","q":"Sur une position close, un spéculateur a versé un deposit de 9 000 USD puis deux appels de marge de 4 200 et 1 300 USD. À la clôture, il récupère 11 700 USD. Quel est son résultat global ? (en USD, signe compris)","opts":null,"correct":null,"answer":-2800,"tol":0.5,"unit":"USD","ex":"Résultat = récupéré − versé = 11 700 − (9 000 + 4 200 + 1 300) = 11 700 − 14 500 = −2 800 USD. Les appels ne sont pas des pertes : ce sont des avances de trésorerie.","aide":{"f":["fut-solde","fut-appel-marge"],"t":"Sur une position close, le résultat global est ce que l'on récupère moins tout ce que l'on a versé. Les appels de marge ne sont pas des pertes mais des versements : additionne-les au deposit pour obtenir le total versé."}},{"id":"produits-derives-2:test:15","m":"produits-derives-2","ch":"Couverture","l":"l5","type":"qcm","q":"Un fabricant nantais de machines encaissera 900 000 USD d'un client de Chicago dans 4 mois. Quelle position prend-il sur les Futures EUR/USD ?","opts":["Il vend, car il encaisse des devises","Il achète, car il craint la baisse de l'USD, donc la hausse de EUR/USD","Il vend des Futures GBP/USD","Aucune : l'USD est la monnaie de cotation"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Il recevra des USD et craint leur baisse : si l'USD baisse, EUR/USD monte et il touchera moins d'euros. L'acheteur de Futures EUR/USD gagne quand le cours monte."},{"id":"produits-derives-2:test:16","m":"produits-derives-2","ch":"Couverture","l":"l5","type":"qcm","q":"Un importateur new-yorkais de vins de Bordeaux doit payer 2 millions d'EUR dans 3 mois. Quelle position prend-il ?","opts":["Il achète des Futures EUR/USD","Il vend des Futures EUR/USD","Il vend des Futures GBP/USD","Il ne fait rien : il paie, il n'est pas exposé"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"Il a une dette en EUR : il craint la hausse de l'euro (plus de dollars à payer). L'acheteur de Futures EUR/USD gagne si le cours monte."},{"id":"produits-derives-2:test:17","m":"produits-derives-2","ch":"Couverture","l":"l5","type":"qcm","q":"Un distributeur américain encaissera 750 000 GBP d'un client londonien dans 2 mois. Quelle position prend-il ?","opts":["Il achète des Futures GBP/USD","Il vend des Futures GBP/USD","Il achète des Futures EUR/USD","Il vend des Futures EUR/USD"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Créance en GBP, la devise du contrat : il craint la baisse de la livre. Le vendeur de Futures GBP/USD gagne quand le cours baisse."},{"id":"produits-derives-2:test:18","m":"produits-derives-2","ch":"Couverture","l":"l6","type":"num","q":"Une PME lyonnaise doit payer 1 600 000 USD dans 3 mois. F0 = 1,0640 ; contrat EUR/USD de 125 000 EUR. Combien de contrats négocier par la correspondance des volumes ? (entier le plus proche)","opts":null,"correct":null,"answer":12,"tol":0,"unit":"contrats","ex":"On convertit d'abord la dette dans la devise du contrat : 1 600 000 ÷ 1,0640 = 1 503 759 EUR. N = montant ÷ T = 1 503 759 ÷ 125 000 = 12,03, soit 12 contrats.","aide":{"f":["fut-nb-volumes"],"t":"L'énoncé demande la correspondance des volumes, et la dette est en USD alors que le contrat est en EUR : convertis d'abord la dette en euros au cours F0 (diviser par 1,0640), puis divise par la taille du contrat et arrondis à l'entier le plus proche."}},{"id":"produits-derives-2:test:19","m":"produits-derives-2","ch":"Couverture","l":"l6","type":"num","q":"Sur l'historique des variations, Cov(S, F) = 0,000072 et V(F) = 0,000080. Quel est le ratio de couverture optimal h* ?","opts":null,"correct":null,"answer":0.9,"tol":0.001,"unit":"","ex":"h* = Cov(S, F) ÷ V(F) = 0,000072 ÷ 0,000080 = 0,9.","aide":{"f":["fut-nb-variance"],"t":"L'énoncé donne Cov(S, F) et V(F) : c'est la couverture à variance minimale. Le ratio optimal h* est la covariance divisée par la variance du Future."}},{"id":"produits-derives-2:test:20","m":"produits-derives-2","ch":"Couverture","l":"l6","type":"num","q":"Un importateur américain doit payer 3 000 000 EUR. Cov(S, F) = 0,000105 et V(F) = 0,000100 ; contrat de 125 000 EUR. Nombre de contrats qui minimise la variance ? (entier le plus proche)","opts":null,"correct":null,"answer":25,"tol":0,"unit":"contrats","ex":"h* = 0,000105 ÷ 0,000100 = 1,05. N* = h* × montant ÷ T = 1,05 × 3 000 000 ÷ 125 000 = 25,2, soit 25 contrats (24 par les volumes).","aide":{"f":["fut-nb-variance"],"t":"Cov et V sont donnés : on cherche le nombre de contrats qui minimise la variance, pas la correspondance des volumes. Calcule d'abord h* = Cov ÷ V, puis N* = h* × Q ÷ T (le montant est déjà en EUR, la devise du contrat) et arrondis."}},{"id":"produits-derives-2:test:21","m":"produits-derives-2","ch":"Couverture","l":"l6","type":"num","q":"Une société totalement averse au risque couvre une créance de 1 500 000 EUR (contrat de 125 000 EUR). L'énoncé donne σS,F = 0,8 et σ²F = 1. Combien de contrats ? (entier le plus proche)","opts":null,"correct":null,"answer":10,"tol":0,"unit":"contrats","ex":"σS,F est la covariance : h* = σS,F ÷ σ²F = 0,8 ÷ 1 = 0,8. N* = 0,8 × 1 500 000 ÷ 125 000 = 9,6, soit 10 contrats.","aide":{"f":["fut-nb-variance"],"t":"« Totalement averse au risque » = minimiser la variance. σS,F désigne la covariance et σ²F la variance du Future : h* = σS,F ÷ σ²F, puis N* = h* × Q ÷ T, arrondi à l'entier le plus proche."}},{"id":"produits-derives-2:test:22","m":"produits-derives-2","ch":"Couverture","l":"l7","type":"num","q":"Un exportateur américain encaissera 1 200 000 EUR. Au départ, S0 = 1,0950 ; le jour de l'encaissement, St = 1,0710. Quel est son résultat physique ? (en USD, signe compris)","opts":null,"correct":null,"answer":-28800,"tol":0.5,"unit":"USD","ex":"Résultat physique = Q × (St − S0) = 1 200 000 × (1,0710 − 1,0950) = −28 800 USD : l'euro a baissé, il reçoit moins de dollars.","aide":{"f":["fut-resultat-physique"],"t":"Entreprise américaine avec une créance en EUR : elle compte en USD, c'est la première ligne, Q × (St − S0). L'euro a baissé entre S0 et St : le résultat sera négatif."}},{"id":"produits-derives-2:test:23","m":"produits-derives-2","ch":"Couverture","l":"l7","type":"num","q":"Un exportateur américain, dont le résultat physique est de −28 800 USD, avait vendu 10 contrats EUR/USD (125 000 EUR) à F0 = 1,0985 et les rachète à Ft = 1,0760. Quel est son résultat global ? (en USD, signe compris)","opts":null,"correct":null,"answer":-675,"tol":0.5,"unit":"USD","ex":"Futures (vendeur) = N × T × (F0 − Ft) = 10 × 125 000 × 0,0225 = +28 125 USD. Global = physique + Futures = −28 800 + 28 125 = −675 USD.","aide":{"f":["fut-resultat-futures","fut-resultat-global"],"t":"Il a vendu les Futures : résultat Futures du vendeur = N × T × (F0 − Ft). Ajoute-lui ensuite le résultat physique donné dans l'énoncé : tout est déjà en USD."}},{"id":"produits-derives-2:test:24","m":"produits-derives-2","ch":"Couverture","l":"l7","type":"num","q":"Un importateur français doit payer 800 000 USD. S0 (EUR/USD) = 1,1000 ; le jour du paiement, St = 1,0500. Quel est son résultat physique en euros ? (à l'unité, signe compris)","opts":null,"correct":null,"answer":-34632,"tol":1,"unit":"EUR","ex":"Il paie 800 000 ÷ 1,0500 = 761 904,76 EUR au lieu de 800 000 ÷ 1,1000 = 727 272,73 EUR. Résultat physique = −34 632,03 EUR, soit environ −34 632 EUR.","aide":{"f":["fut-resultat-physique"],"t":"Entreprise française, montant en USD : on compte en euros, avec Q ÷ S (2e ligne). C'est une dette : le signe s'inverse, le résultat est ce qu'il aurait payé au départ (Q ÷ S0) moins ce qu'il paie vraiment (Q ÷ St). Commence par 800 000 ÷ 1,0500."}},{"id":"produits-derives-2:test:25","m":"produits-derives-2","ch":"Couverture","l":"l7","type":"num","q":"Un exportateur bordelais encaissera 1 250 000 USD. Il a acheté 9 contrats EUR/USD (125 000 EUR) à F0 = 1,0900, avec S0 = 1,0870. À l'encaissement : St = 1,1200 et Ft = 1,1230. Quel est son résultat global en euros ? (à l'unité, signe compris)","opts":null,"correct":null,"answer":-735,"tol":1,"unit":"EUR","ex":"Physique = Q ÷ St − Q ÷ S0 = 1 116 071,43 − 1 149 954,00 = −33 882,57 EUR. Futures (acheteur) = 9 × 125 000 × (1,1230 − 1,0900) = 37 125 USD, soit 37 125 ÷ 1,1200 = 33 147,32 EUR. Global ≈ −735 EUR.","aide":{"f":["fut-resultat-physique","fut-resultat-futures","fut-resultat-global"],"t":"Exportateur français qui encaisse des USD : on compte en euros. Physique = Q ÷ St − Q ÷ S0. Futures (il a acheté) = N × T × (Ft − F0), en USD, à convertir en euros au spot du jour St. Le global est la somme des deux, en euros."}},{"id":"produits-derives-2:test:26","m":"produits-derives-2","ch":"Base et évaluation","l":"l8","type":"num","q":"Le cours GBP/USD au comptant est de 1,3480 et le Future septembre cote 1,3512. Quelle est la base ? (4 décimales, signe compris)","opts":null,"correct":null,"answer":-0.0032,"tol":0.00001,"unit":"","ex":"Base = S − F = 1,3480 − 1,3512 = −0,0032.","aide":{"f":["fut-base"],"t":"La base est l'écart entre le comptant et le Future : S − F, dans cet ordre. Ici le Future cote au-dessus du comptant : la base sera négative."}},{"id":"produits-derives-2:test:27","m":"produits-derives-2","ch":"Base et évaluation","l":"l8","type":"num","q":"Couverture vendeuse à volumes égaux sur 625 000 GBP : la base passe de −0,0030 à l'ouverture à −0,0012 à la liquidation. Quel est le résultat global ? (en USD, signe compris)","opts":null,"correct":null,"answer":1125,"tol":0.5,"unit":"USD","ex":"Couverture vendeuse : global = Q × (bt − b0) = 625 000 × (−0,0012 + 0,0030) = 625 000 × 0,0018 = +1 125 USD.","aide":{"f":["fut-base"],"t":"Couverture vendeuse à volumes égaux : le résultat global ne dépend que de l'évolution de la base, Q × (bt − b0). Attention aux signes : bt − b0 = −0,0012 − (−0,0030)."}},{"id":"produits-derives-2:test:28","m":"produits-derives-2","ch":"Base et évaluation","l":"l8","type":"qcm","q":"Un importateur américain couvre une dette de 500 000 EUR en achetant 4 contrats (volumes égaux). La base passe de −0,0040 à −0,0025. Quel est son résultat global ?","opts":["+750 USD","−750 USD","0 USD","−7 500 USD"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Couverture acheteuse : global = −Q × (bt − b0) = −500 000 × (−0,0025 + 0,0040) = −500 000 × 0,0015 = −750 USD."},{"id":"produits-derives-2:test:29","m":"produits-derives-2","ch":"Base et évaluation","l":"l8","type":"qcm","q":"Un exportateur américain doit couvrir une créance de 1 100 000 EUR avec des contrats de 125 000 EUR. Il en vend 9. Que dire de sa couverture ?","opts":["Sur-couverture : 1 125 000 EUR couverts pour 1 100 000 EUR","Sous-couverture de 25 000 EUR","Couverture parfaite","Elle n'est exposée qu'au risque de base"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"N = 1 100 000 ÷ 125 000 = 8,8, arrondi à 9 : 9 × 125 000 = 1 125 000 EUR couverts, soit 25 000 EUR de trop. C'est un risque résiduel : la quantité n'est pas un multiple de la taille."},{"id":"produits-derives-2:test:30","m":"produits-derives-2","ch":"Base et évaluation","l":"l8","type":"qcm","q":"Que vaut la base à l'échéance du Future ?","opts":["Elle vaut zéro : spot et Future convergent","Elle vaut le report","Elle est égale au deposit","Elle est imprévisible"],"correct":0,"answer":null,"tol":null,"unit":"","ex":"À l'échéance, le Future livre la devise au comptant : F = S, donc b = S − F = 0. C'est parce que l'on liquide avant l'échéance (E > t) que la base n'est pas encore nulle."},{"id":"produits-derives-2:test:31","m":"produits-derives-2","ch":"Base et évaluation","l":"l9","type":"num","q":"Au comptant, EUR/USD = 1,0800. Taux à 4 mois : 4,5 % sur l'USD, 3 % sur l'EUR. Quel est le cours à terme théorique à 4 mois ? (4 décimales)","opts":null,"correct":null,"answer":1.0853,"tol":0.00006,"unit":"","ex":"f = S × (1 + iUSD × n/12) ÷ (1 + iEUR × n/12) = 1,08 × (1 + 4,5 % × 4/12) ÷ (1 + 3 % × 4/12) = 1,08 × 1,015 ÷ 1,01 = 1,085347, soit 1,0853.","aide":{"f":["fut-parite"],"t":"Cours à terme théorique = parité des taux. Le taux de la monnaie de cotation (USD) va au numérateur, celui de l'EUR au dénominateur, chacun multiplié par n/12 avec n = 4 mois."}},{"id":"produits-derives-2:test:32","m":"produits-derives-2","ch":"Base et évaluation","l":"l9","type":"qcm","q":"Le cours à terme théorique EUR/USD à 4 mois vaut 1,0853 et le Future de même échéance cote 1,0880. Que fait un arbitragiste ?","opts":["Il achète le Future, sous-évalué","Il vend le Future, surévalué, et achète à terme synthétiquement","Rien : F et f sont égaux à l'arrondi près","Il vend des euros au comptant et les conserve"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"F > f : le Future est surévalué. On le vend, et l'on achète à terme de façon synthétique : emprunt d'USD, achat d'EUR au comptant, placement des EUR jusqu'à l'échéance."},{"id":"produits-derives-2:test:33","m":"produits-derives-2","ch":"Base et évaluation","l":"l9","type":"num","q":"Le Future EUR/USD à 4 mois cote 1,0880, alors que le cours théorique vaut f = 1,08 × 1,015 ÷ 1,01. Quel gain sans risque un arbitrage procure-t-il par contrat de 125 000 EUR ? (en USD, à l'unité)","opts":null,"correct":null,"answer":332,"tol":1,"unit":"USD","ex":"Gain = T × (F − f) = 125 000 × (1,0880 − 1,085347) = 331,68 USD, soit environ 332 USD par contrat.","aide":{"f":["fut-comparer","fut-parite"],"t":"On compare le Future coté F au cours théorique f. Calcule d'abord f (parité des taux) en gardant 6 décimales, puis le gain sans risque par contrat = T × |F − f|."}},{"id":"produits-derives-2:test:34","m":"produits-derives-2","ch":"Base et évaluation","l":"l9","type":"qcm","q":"GBP/USD au comptant = 1,2700. Taux à 6 mois : 4 % sur l'USD, 5 % sur la GBP. Sans calculer, comment se situe le cours à terme théorique de la livre ?","opts":["Au-dessus du comptant : la livre est en report","En dessous du comptant : la livre est en déport","Égal au comptant","On ne peut pas le savoir sans les cours Futures"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"f = S × (1 + iUSD × n/12) ÷ (1 + iGBP × n/12) : le dénominateur l'emporte (5 % > 4 %), donc f < S. La devise la mieux rémunérée est en déport (f = 1,2638)."},{"id":"produits-derives-2:test:35","m":"produits-derives-2","ch":"Spéculation","l":"l10","type":"num","q":"Un spéculateur achète 10 contrats GBP/USD (62 500 GBP) à 1,2800 ; deposit de 2 400 USD par contrat. Quel est son effet de levier ? (1 décimale)","opts":null,"correct":null,"answer":33.3,"tol":0.05,"unit":"","ex":"Levier = valeur notionnelle ÷ deposit = (10 × 62 500 × 1,2800) ÷ (10 × 2 400) = 800 000 ÷ 24 000 = 33,3.","aide":{"f":["fut-levier"],"t":"Effet de levier = valeur notionnelle (N × T × F0, en USD) ÷ deposit total. Calcule les deux : 10 × 62 500 × 1,2800 d'un côté, 10 × 2 400 de l'autre."}},{"id":"produits-derives-2:test:36","m":"produits-derives-2","ch":"Spéculation","l":"l10","type":"num","q":"Un spéculateur achète 2 contrats EUR/USD (125 000 EUR) à 1,0900 avec un deposit de 3 000 USD par contrat. Le cours monte à 1,0960. Quel gain réalise-t-il, en % du deposit ?","opts":null,"correct":null,"answer":25,"tol":0.05,"unit":"%","ex":"Gain = (1,0960 − 1,0900) × 250 000 = 1 500 USD, pour 6 000 USD de deposit : 1 500 ÷ 6 000 = 25 %, alors que le cours n'a monté que de 0,55 %. C'est l'effet de levier.","aide":{"f":["fut-resultat","fut-levier"],"t":"Calcule d'abord le gain de l'acheteur en USD : (cours de vente − cours d'achat) × T × N. Rapporte-le ensuite au deposit total (2 × 3 000 USD) et multiplie par 100 : c'est l'effet de levier."}},{"id":"produits-derives-2:test:37","m":"produits-derives-2","ch":"Spéculation","l":"l10","type":"qcm","q":"Un spéculateur acheteur a un deposit de 10 000 USD et une maintenance de 7 500 USD. Une forte baisse lui fait perdre 4 000 USD en une séance, et il ne peut pas payer l'appel de marge. Le lendemain, le cours remonte. Que s'est-il passé ?","opts":["Rien : il garde son solde de 6 000 USD et profite de la remontée","Sa position est liquidée : la perte de 4 000 USD devient définitive","La chambre de compensation lui prête les 4 000 USD","L'appel est reporté à l'échéance"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Solde 6 000 < 7 500 : appel de 10 000 − 6 000 = 4 000 USD, à payer tout de suite. Faute de paiement, la position est liquidée : le risque de trésorerie fait perdre même celui dont l'anticipation était juste."},{"id":"produits-derives-2:test:38","m":"produits-derives-2","ch":"Spéculation","l":"l10","type":"qcm","q":"Le contrat yen du CME est coté en USD pour 1 JPY. Un spéculateur anticipe une baisse du yen face au dollar. Que fait-il ?","opts":["Il achète des Futures JPY","Il vend des Futures JPY","Il achète des Futures EUR/USD","Il attend l'échéance pour se faire livrer des yens"],"correct":1,"answer":null,"tol":null,"unit":"","ex":"Si le yen baisse, le cours (USD pour 1 JPY) baisse : le vendeur de Futures gagne quand le cours baisse."},{"id":"produits-derives-2:quiz:l1:0","m":"produits-derives-2","ch":"Leçon 1 — Forward ou Futures : deux contrats à terme","l":"l1","type":"qcm","q":"Une coopérative bretonne veut couvrir exactement 1 730 000 USD payables le 17 mars. Quel instrument lui donne un montant et une date sur mesure ?","opts":["Un forward négocié avec sa banque","Des Futures EUR/USD sur le CME","Des Futures GBP/USD","Un dépôt de garantie auprès de la chambre"],"correct":0,"ex":"Exact. Le forward se négocie de gré à gré : montant et date au choix. Le Future est standardisé : taille fixe (125 000 EUR) et échéances trimestrielles."},{"id":"produits-derives-2:quiz:l1:1","m":"produits-derives-2","ch":"Leçon 1 — Forward ou Futures : deux contrats à terme","l":"l1","type":"qcm","q":"Quand les gains et les pertes d'une position en Futures sont-ils réglés ?","opts":["Une seule fois, à l'échéance","Chaque soir, au cours de compensation","Quand l'opérateur le demande","À la livraison des devises"],"correct":1,"ex":"Bien vu. La chambre de compensation réévalue chaque position tous les soirs au cours de compensation : c'est l'appel de marge quotidien. Le forward, lui, se règle une seule fois, à l'échéance."},{"id":"produits-derives-2:quiz:l2:0","m":"produits-derives-2","ch":"Leçon 2 — Lire un contrat : taille, échéance, tick","l":"l2","type":"qcm","q":"Le contrat CHF/USD du CME porte sur 125 000 CHF, avec un tick de 0,0001 USD. Que vaut un tick ?","opts":["1,25 USD","12,5 USD","125 USD","0,0001 CHF"],"correct":1,"ex":"Exact. Tick en valeur = tick × T = 0,0001 × 125 000 = 12,5 USD par contrat."},{"id":"produits-derives-2:quiz:l2:1","m":"produits-derives-2","ch":"Leçon 2 — Lire un contrat : taille, échéance, tick","l":"l2","type":"qcm","q":"Achat de 5 contrats GBP/USD (62 500 GBP) à 1,2590, revente à 1,2634. Quel est le résultat ?","opts":["+1 375 USD","−1 375 USD","+275 USD","+13 750 USD"],"correct":0,"ex":"Bien vu. (F vente − F achat) × T × N = (1,2634 − 1,2590) × 62 500 × 5 = 0,0044 × 312 500 = +1 375 USD. Oublier N donne 275 USD."},{"id":"produits-derives-2:quiz:l3:0","m":"produits-derives-2","ch":"Leçon 3 — Deposit, marge de maintenance et appels de marge","l":"l3","type":"qcm","q":"Deposit de 1 800 USD par contrat pour 10 contrats, maintenance de 75 %. Après la séance, le solde est de 14 100 USD. Que se passe-t-il ?","opts":["Appel de 3 900 USD pour revenir au deposit","Rien : 14 100 ≥ 13 500 USD de maintenance","Appel de 600 USD","La position est liquidée"],"correct":1,"ex":"Exact. Deposit = 18 000 USD, maintenance = 75 % × 18 000 = 13 500 USD. Le solde reste au-dessus : aucun appel."},{"id":"produits-derives-2:quiz:l3:1","m":"produits-derives-2","ch":"Leçon 3 — Deposit, marge de maintenance et appels de marge","l":"l3","type":"qcm","q":"Deposit de 18 000 USD, maintenance de 13 500 USD. Le solde tombe à 11 700 USD. Quel appel de marge faut-il verser ?","opts":["1 800 USD","6 300 USD","11 700 USD","18 000 USD"],"correct":1,"ex":"Bien vu. 11 700 < 13 500 : appel = deposit − solde = 18 000 − 11 700 = 6 300 USD. Revenir seulement à la maintenance (1 800 USD) est l'erreur classique."},{"id":"produits-derives-2:quiz:l4:0","m":"produits-derives-2","ch":"Leçon 4 — Le compte de marge, jour par jour","l":"l4","type":"qcm","q":"Vendeur de 3 contrats EUR/USD (125 000 EUR). Le cours de compensation passe de 1,0745 à 1,0712. Quel est son résultat du jour ?","opts":["+1 237,5 USD","−1 237,5 USD","+412,5 USD","+12 375 USD"],"correct":0,"ex":"Exact. Vendeur : (F veille − F jour) × T × N = (1,0745 − 1,0712) × 375 000 = +1 237,50 USD. Le vendeur gagne quand le cours baisse."},{"id":"produits-derives-2:quiz:l4:1","m":"produits-derives-2","ch":"Leçon 4 — Le compte de marge, jour par jour","l":"l4","type":"qcm","q":"Deposit de 9 000 USD, un appel de marge de 3 600 USD, et 7 400 USD récupérés à la clôture. Quel est le résultat global ?","opts":["−1 600 USD","−5 200 USD","+7 400 USD","−3 600 USD"],"correct":1,"ex":"Bien vu. Versé 9 000 + 3 600 = 12 600 USD, récupéré 7 400 USD : −5 200 USD. Oublier l'appel donnerait −1 600 USD."},{"id":"produits-derives-2:quiz:l5:0","m":"produits-derives-2","ch":"Leçon 5 — Acheter ou vendre des Futures ?","l":"l5","type":"qcm","q":"Un groupe américain doit rembourser un emprunt de 5 millions d'EUR dans 6 mois. Quelle position prend-il sur les Futures EUR/USD ?","opts":["Il achète, car il craint la hausse de l'euro","Il vend, car il craint la baisse de l'euro","Il vend, car il a une dette","Aucune : un emprunt n'est pas exposé"],"correct":0,"ex":"Exact. Dette en EUR : si l'euro monte, il lui faudra plus de dollars. L'acheteur de Futures EUR/USD gagne quand le cours monte."},{"id":"produits-derives-2:quiz:l5:1","m":"produits-derives-2","ch":"Leçon 5 — Acheter ou vendre des Futures ?","l":"l5","type":"qcm","q":"Une entreprise américaine encaissera 1 250 000 GBP. Quel mouvement de GBP/USD lui fait perdre, et que fait-elle ?","opts":["Une hausse : elle achète des Futures GBP/USD","Une baisse : elle vend des Futures GBP/USD","Une baisse : elle achète des Futures GBP/USD","Une hausse : elle vend des Futures GBP/USD"],"correct":1,"ex":"Bien vu. Créance en livres : une baisse de GBP/USD réduit les dollars reçus. Le vendeur de Futures gagne justement quand le cours baisse."},{"id":"produits-derives-2:quiz:l6:0","m":"produits-derives-2","ch":"Leçon 6 — Combien de contrats négocier ?","l":"l6","type":"qcm","q":"Une entreprise française encaissera 4 000 000 USD. F0 = 1,0750 ; contrat de 125 000 EUR. Combien de contrats par la correspondance des volumes ?","opts":["32","30","29","34"],"correct":1,"ex":"Exact. 4 000 000 ÷ 1,0750 = 3 720 930 EUR ; ÷ 125 000 = 29,77, soit 30 contrats. Sans conversion, on trouverait 32 ; en multipliant par F0, 34."},{"id":"produits-derives-2:quiz:l6:1","m":"produits-derives-2","ch":"Leçon 6 — Combien de contrats négocier ?","l":"l6","type":"qcm","q":"Dette de 1 875 000 GBP, contrat de 62 500 GBP, Cov(S, F) = 0,000126 et V(F) = 0,000140. Combien de contrats minimisent la variance ?","opts":["30","27","33","9"],"correct":1,"ex":"Bien vu. h* = 0,000126 ÷ 0,000140 = 0,9 ; N* = 0,9 × 1 875 000 ÷ 62 500 = 27 contrats (30 par les volumes)."},{"id":"produits-derives-2:quiz:l7:0","m":"produits-derives-2","ch":"Leçon 7 — Résultat physique, résultat Futures, résultat global","l":"l7","type":"qcm","q":"Un exportateur américain encaisse 2 000 000 EUR ; S0 = 1,0820 et St = 1,0640. Quel est son résultat physique ?","opts":["+36 000 USD","−36 000 USD","−3 600 USD","−18 000 USD"],"correct":1,"ex":"Exact. Q × (St − S0) = 2 000 000 × (1,0640 − 1,0820) = −36 000 USD : l'euro a baissé, il reçoit moins de dollars."},{"id":"produits-derives-2:quiz:l7:1","m":"produits-derives-2","ch":"Leçon 7 — Résultat physique, résultat Futures, résultat global","l":"l7","type":"qcm","q":"Une entreprise européenne gagne 63 000 USD sur ses Futures. Le jour de la liquidation, EUR/USD = 1,0500. Combien cela fait-il en euros ?","opts":["66 150 EUR","60 000 EUR","63 000 EUR"],"correct":1,"ex":"Bien vu. 63 000 ÷ 1,0500 = 60 000 EUR. On divise, car le cours donne des USD pour 1 EUR ; on convertit au spot du jour de liquidation."},{"id":"produits-derives-2:quiz:l8:0","m":"produits-derives-2","ch":"Leçon 8 — La base et les risques de la couverture","l":"l8","type":"qcm","q":"Au comptant, EUR/USD = 1,0712 ; le Future décembre cote 1,0748. Quelle est la base ?","opts":["+0,0036","−0,0036","−0,0360","0"],"correct":1,"ex":"Exact. b = S − F = 1,0712 − 1,0748 = −0,0036."},{"id":"produits-derives-2:quiz:l8:1","m":"produits-derives-2","ch":"Leçon 8 — La base et les risques de la couverture","l":"l8","type":"qcm","q":"Couverture vendeuse à volumes égaux sur 750 000 EUR : la base passe de −0,0040 à −0,0015. Quel est le résultat global ?","opts":["+1 875 USD","−1 875 USD","+18 750 USD","0 USD"],"correct":0,"ex":"Bien vu. Global = Q × (bt − b0) = 750 000 × 0,0025 = +1 875 USD. La couverture n'est imparfaite que par la variation de la base."},{"id":"produits-derives-2:quiz:l9:0","m":"produits-derives-2","ch":"Leçon 9 — Évaluer un Future et l'arbitrer","l":"l9","type":"qcm","q":"Le cours à terme théorique EUR/USD vaut 1,0853 et le Future de même échéance cote 1,0821. Que fait l'arbitragiste ?","opts":["Il achète le Future, sous-évalué","Il vend le Future, surévalué","Rien : l'écart est trop faible"],"correct":0,"ex":"Exact. F < f : le Future est sous-évalué. On l'achète et l'on vend à terme synthétiquement : emprunt d'EUR, vente au comptant contre USD, placement des USD."},{"id":"produits-derives-2:quiz:l9:1","m":"produits-derives-2","ch":"Leçon 9 — Évaluer un Future et l'arbitrer","l":"l9","type":"qcm","q":"EUR/USD au comptant = 1,1000. Taux à 3 mois : 4 % sur l'USD, 2,5 % sur l'EUR. Quel est le cours à terme théorique ?","opts":["1,1041","1,0959","1,1161","1,1000"],"correct":0,"ex":"Bien vu. f = 1,1000 × (1 + 4 % × 3/12) ÷ (1 + 2,5 % × 3/12) = 1,1 × 1,01 ÷ 1,00625 = 1,1041. Inverser les taux donne 1,0959 ; oublier n/12 donne 1,1161."},{"id":"produits-derives-2:quiz:l10:0","m":"produits-derives-2","ch":"Leçon 10 — Spéculer avec des Futures : levier et trésorerie","l":"l10","type":"qcm","q":"Un spéculateur achète 5 contrats GBP/USD (62 500 GBP) à 1,2600, avec un deposit de 2 100 USD par contrat. Quel est son effet de levier ?","opts":["5","29,8","37,5","187,5"],"correct":2,"ex":"Exact. Notionnel = 5 × 62 500 × 1,2600 = 393 750 USD ; deposit = 10 500 USD ; levier = 37,5. Oublier le cours (en GBP au lieu d'USD) donne 29,8."},{"id":"produits-derives-2:quiz:l10:1","m":"produits-derives-2","ch":"Leçon 10 — Spéculer avec des Futures : levier et trésorerie","l":"l10","type":"qcm","q":"Un spéculateur anticipe une hausse du franc suisse face au dollar. Le contrat CHF/USD est coté en USD pour 1 CHF. Que fait-il ?","opts":["Il achète des Futures CHF/USD","Il vend des Futures CHF/USD","Il vend des Futures EUR/USD"],"correct":0,"ex":"Bien vu. Si le franc monte, le cours (USD pour 1 CHF) monte : l'acheteur de Futures gagne quand le cours monte."}];

window.CARTES = [{"id":"glo:0","m":"marche-particuliers","ch":"Glossaire","l":"l3","type":"carte","q":"DAV","d":"Dépôt à vue","ex":"Le compte courant : individuel, joint ou indivis. Sert aux besoins bancaires du quotidien."},{"id":"glo:1","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"LDDS","d":"Livret de Développement Durable et Solidaire","ex":"Livret réglementé, plafond 12 000 €, 1,7 % net. Finance les entreprises (PME)."},{"id":"glo:2","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"LEP","d":"Livret d'Épargne Populaire","ex":"Plafond 10 000 €, 2,5 % net, sous conditions de ressources. Fonds gérés par les banques elles-mêmes."},{"id":"glo:3","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"PEL","d":"Plan d'Épargne Logement","ex":"Versement initial 225 €, capital maxi 61 200 €, prêt maxi 92 000 € au taux de rémunération + 1,20 %. Prime d'État supprimée après le 01/01/2018."},{"id":"glo:4","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"CEL","d":"Compte Épargne Logement","ex":"Prêt maximum de 23 000 €. Les CEL ouverts avant 2018 sont nets d'impôt mais soumis aux prélèvements sociaux."},{"id":"glo:5","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"LJ","d":"Livret Jeune","ex":"Livret réglementé réservé aux jeunes."},{"id":"glo:6","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"LEE","d":"Livret Épargne Entreprise","ex":"Livret réglementé lié à l'épargne d'entreprise."},{"id":"glo:7","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"PEP","d":"Plan d'Épargne Populaire","ex":"Plafond de versement 92 000 €, durée conseillée 8 ans, transférable. Commercialisation arrêtée en 2003 mais encore détenu."},{"id":"glo:8","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"PEA","d":"Plan d'Épargne en Actions","ex":"Deux enveloppes (espèces + titres), un seul par contribuable dès 18 ans, plafond 150 000 €, détention minimum 5 ans. Actions, ETF, OPC — pas d'obligations."},{"id":"glo:9","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"CTO","d":"Compte-Titres Ordinaire","ex":"Sans plafond ni régime de faveur : fiscalité de droit commun sur obligations, dividendes et cessions."},{"id":"glo:10","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"DAT","d":"Dépôt à terme","ex":"Durée de 5 à 7 ans selon les banques, retrait possible à tout moment mais sans rémunération sous 1 mois. PFU appliqué : 31,4 %."},{"id":"glo:11","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"PFU","d":"Prélèvement Forfaitaire Unique","ex":"La part d'imposition de la flat-tax : 12,8 %, à laquelle s'ajoutent 17,2 % de prélèvements sociaux."},{"id":"glo:12","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"PS","d":"Prélèvements sociaux","ex":"17,2 % sur les revenus mobiliers. Attention : 18,6 % sur les rentes du PER."},{"id":"glo:13","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"Flat-Tax","d":"Prélèvement forfaitaire global","ex":"30 % au total = 12,8 % (PFU) + 17,2 % (PS). Option possible pour le barème progressif de l'IR."},{"id":"glo:14","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"Case 2OP","d":"Option pour le barème de l'impôt sur le revenu","ex":"Case à cocher pour déclarer les intérêts à l'IR plutôt qu'au PFU, utile si le foyer n'est pas imposable."},{"id":"glo:15","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"Dispense d'acompte","d":"Demande de non-prélèvement du PFU","ex":"À demander avant le 30 novembre si le client ne sera pas imposable l'année suivante : il ne paie alors que les 17,2 % de PS, sans avance de trésorerie."},{"id":"glo:16","m":"marche-particuliers","ch":"Glossaire","l":"l4","type":"carte","q":"Quinzaine","d":"Période de calcul des intérêts d'un livret","ex":"Deux par mois (1-15 et 16-30/31). Formule : capital × taux annuel × 1/24. Fonds à déposer à J-1 de la quinzaine."},{"id":"glo:17","m":"marche-particuliers","ch":"Glossaire","l":"l3","type":"carte","q":"ESTER","d":"Euro Short-Term Rate","ex":"Taux interbancaire à 1 jour."},{"id":"glo:18","m":"marche-particuliers","ch":"Glossaire","l":"l3","type":"carte","q":"Euribor","d":"Euro Interbank Offered Rate","ex":"Taux interbancaire de 1 mois à 1 an."},{"id":"glo:19","m":"marche-particuliers","ch":"Glossaire","l":"l3","type":"carte","q":"OAT","d":"Obligation Assimilable du Trésor","ex":"Finance la dette de l'État français, autour de 4 %."},{"id":"glo:20","m":"marche-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"FGAP","d":"Fonds de Garantie des Assurances de Personnes","ex":"Garantit les contrats d'assurance vie à hauteur de 70 000 € par assuré et par compagnie."},{"id":"glo:21","m":"marche-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"UC","d":"Unités de compte","ex":"Supports d'assurance vie non garantis : actions, obligations, OPC, SCPI, ETF. Prélèvements sociaux à la sortie ou au rachat."},{"id":"glo:22","m":"marche-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"Fonds en euros","d":"Support garanti d'assurance vie","ex":"Indexé sur les emprunts d'État, niveau 1/7 sur l'échelle du risque. PS prélevés au 31/12 de chaque année."},{"id":"glo:23","m":"marche-particuliers","ch":"Glossaire","l":"l7","type":"carte","q":"PER","d":"Plan d'Épargne Retraite","ex":"Versements déductibles jusqu'à 10 % du revenu imposable, 6 cas de déblocage. Sortie en capital (IR sans abattement + PFU 31,4 % sur les plus-values) ou en rente (IR après abattement + 18,6 % de PS)."},{"id":"glo:24","m":"marche-particuliers","ch":"Glossaire","l":"l8","type":"carte","q":"OPC","d":"Organisme de Placement Collectif","ex":"Un portefeuille — ou panier — de valeurs mobilières. Classification AMF : fonds à formule, alternatifs, actions, obligations, monétaires."},{"id":"glo:25","m":"marche-particuliers","ch":"Glossaire","l":"l8","type":"carte","q":"SICAV","d":"Société d'Investissement à Capital Variable","ex":"Forme juridique d'OPC : une société anonyme, l'investisseur est actionnaire."},{"id":"glo:26","m":"marche-particuliers","ch":"Glossaire","l":"l8","type":"carte","q":"FCP","d":"Fonds Commun de Placement","ex":"Forme juridique d'OPC : une copropriété de valeurs mobilières sans personnalité morale."},{"id":"glo:27","m":"marche-particuliers","ch":"Glossaire","l":"l8","type":"carte","q":"AMF","d":"Autorité des Marchés Financiers","ex":"Régulateur qui établit notamment la classification des OPC."},{"id":"glo:28","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"SCPI","d":"Société Civile de Placement Immobilier","ex":"Pierre-papier : quote-part d'une valeur immobilière. PS à 17,2 %, durée conseillée 8 ans."},{"id":"glo:29","m":"marche-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"OPCI","d":"Organisme de Placement Collectif Immobilier","ex":"Investit 60 % en immobilier et 40 % en actions foncières cotées. S'investit via un CTO ou une assurance vie."},{"id":"glo:30","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"TAEG","d":"Taux Annuel Effectif Global","ex":"Taux nominal + frais de dossier + frais de garantie + assurance. Instrument légal de comparaison entre banques, obligatoire dans toute publicité ou offre."},{"id":"glo:31","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"Taux d'usure","d":"TAEG maximum légal","ex":"Le taux au-delà duquel il est interdit de prêter. Calculé chaque trimestre par la Banque de France."},{"id":"glo:32","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"VTS","d":"Vérification Triennale de Solvabilité","ex":"Vérifier que l'emprunteur est toujours solvable, préalable au renouvellement. Obligatoire pour les contrats de 3 ans et plus."},{"id":"glo:33","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"LCC","d":"Loi sur le Crédit à la Consommation (loi Lagarde)","ex":"Crédit conso entre 200 € et 75 000 €, rétractation de 14 jours, fonds disponibles à partir du 8ᵉ jour."},{"id":"glo:34","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"Loi Neiertz","d":"Loi contre le surendettement","ex":"Trois orientations : développer la prévention, organiser une procédure de règlement du surendettement, responsabiliser prêteurs et emprunteurs."},{"id":"glo:35","m":"marche-particuliers","ch":"Glossaire","l":"l9","type":"carte","q":"Loi Hamon","d":"Loi sur la reconduction tacite","ex":"Les contrats inactifs depuis 12 mois sont suspendus 12 mois (soit 24 au total) puis résiliés automatiquement — vise le crédit renouvelable."},{"id":"glo:36","m":"marche-particuliers","ch":"Glossaire","l":"l10","type":"carte","q":"PPD","d":"Privilège de Prêteur de Deniers","ex":"Hypothèque légale spéciale du prêteur de deniers : une garantie réelle."},{"id":"glo:37","m":"marche-particuliers","ch":"Glossaire","l":"l10","type":"carte","q":"ADE","d":"Assurance Décès-Emprunteur","ex":"Assurance adossée au crédit, avec l'assurance chômage."},{"id":"glo:38","m":"marche-particuliers","ch":"Glossaire","l":"l10","type":"carte","q":"FGAS","d":"Fonds de Garantie de l'Accession Sociale","ex":"Dispositif de garantie des prêts à l'accession sociale."},{"id":"glo:39","m":"marche-particuliers","ch":"Glossaire","l":"l10","type":"carte","q":"CAMCA","d":"Caisse d'Assurances Mutuelles du Crédit Agricole","ex":"Organisme de cautionnement mutuel, comme Crédit Logement."},{"id":"glo:40","m":"marche-particuliers","ch":"Glossaire","l":"l10","type":"carte","q":"Nantissement","d":"Garantie réelle sans dépossession","ex":"Le débiteur cède un bien en garantie sans en être dépossédé — il en conserve la jouissance."},{"id":"glo:41","m":"marche-particuliers","ch":"Glossaire","l":"l11","type":"carte","q":"RC","d":"Responsabilité Civile","ex":"Article 1240 du Code civil. Trois conditions cumulatives : faute → lien de causalité → dommage. Peut être contractuelle ou extracontractuelle."},{"id":"glo:42","m":"marche-particuliers","ch":"Glossaire","l":"l11","type":"carte","q":"DUC","d":"Direction, Usage, Contrôle","ex":"Moyen mnémotechnique des trois éléments permettant de faire jouer la responsabilité civile."},{"id":"glo:43","m":"marche-particuliers","ch":"Glossaire","l":"l11","type":"carte","q":"GAV","d":"Garantie des Accidents de la Vie","ex":"Assurance de personnes, avec la dépendance, le capital décès et les obsèques."},{"id":"glo:44","m":"marche-particuliers","ch":"Glossaire","l":"l11","type":"carte","q":"Loi Badinter","d":"Loi sur l'indemnisation des accidents de la circulation","ex":"La faute de la victime n'est que rarement admise : pour le dommage corporel, piétons, cyclistes et passagers sont quasiment toujours indemnisés."},{"id":"glo:45","m":"marche-particuliers","ch":"Glossaire","l":"l11","type":"carte","q":"Force majeure","d":"Cause exonératoire de responsabilité","ex":"Trois caractères cumulatifs : imprévisible, irrésistible, extérieur. Avec le fait d'un tiers et la faute de la victime, c'est l'un des 3 cas d'exonération."},{"id":"glo:46","m":"produits-derives","ch":"Glossaire","l":"l1","type":"carte","q":"BRI","d":"Banque des Règlements Internationaux","ex":"Publie l'enquête triennale de référence sur le marché des changes : 5 100 Mds USD par jour en 2023."},{"id":"glo:47","m":"produits-derives","ch":"Glossaire","l":"l5","type":"carte","q":"Spot","d":"Marché des changes au comptant","ex":"Environ 37 % des opérations. Livraison au plus tard à J+2 ouvrables."},{"id":"glo:48","m":"produits-derives","ch":"Glossaire","l":"l1","type":"carte","q":"Forward","d":"Marché des changes à terme","ex":"Compartiment du marché traditionnel qui, contrairement au comptant, permet la couverture du risque de change."},{"id":"glo:49","m":"produits-derives","ch":"Glossaire","l":"l3","type":"carte","q":"OTC","d":"Over The Counter (de gré à gré)","ex":"Les transactions ne sont pas officiellement standardisées et il n'existe aucune bourse centralisée. Le marché est totalement délocalisé."},{"id":"glo:50","m":"produits-derives","ch":"Glossaire","l":"l3","type":"carte","q":"SWIFT","d":"Society for Worldwide Interbank Financial Telecommunication","ex":"Créé en 1977. C'est un mode de transmission des ordres, pas un mode de paiement. Avantages sur le Télex : sécurité, rapidité, coût réduit."},{"id":"glo:51","m":"produits-derives","ch":"Glossaire","l":"l3","type":"carte","q":"Nostri","d":"Compte de la banque chez son correspondant","ex":"« Le nôtre chez eux » : enregistre des écritures en devises."},{"id":"glo:52","m":"produits-derives","ch":"Glossaire","l":"l3","type":"carte","q":"Lori","d":"Compte du correspondant chez la banque","ex":"« Le leur chez nous » : enregistre des écritures en monnaie nationale."},{"id":"glo:53","m":"produits-derives","ch":"Glossaire","l":"l4","type":"carte","q":"PC","d":"Position de change","ex":"Créances en devises − dettes en devises, calculée par devise et par échéance. Longue (exportateur, risque de baisse), courte (importateur, risque de hausse) ou fermée (aucun risque)."},{"id":"glo:54","m":"produits-derives","ch":"Glossaire","l":"l4","type":"carte","q":"Hedging","d":"Couverture du risque de change","ex":"Prendre une position inverse pour annuler un risque initial. Le risque ne disparaît pas : il est transféré à un autre agent."},{"id":"glo:55","m":"produits-derives","ch":"Glossaire","l":"l2","type":"carte","q":"Cambiste","d":"Spécialiste du marché des changes","ex":"Opère en salle des marchés. Soit teneur de marché (market maker), soit cambiste clientèle (saler)."},{"id":"glo:56","m":"produits-derives","ch":"Glossaire","l":"l2","type":"carte","q":"Market maker","d":"Teneur de marché","ex":"Assure en permanence la liquidité et la contrepartie ; ses cours servent de référence. Réservé aux très grandes banques."},{"id":"glo:57","m":"produits-derives","ch":"Glossaire","l":"l2","type":"carte","q":"Saler","d":"Cambiste clientèle","ex":"Chargé de répondre à la demande des clients de la banque."},{"id":"glo:58","m":"produits-derives","ch":"Glossaire","l":"l2","type":"carte","q":"Broker","d":"Courtier","ex":"Simple intermédiaire qui ne prend aucune position de change. Environ 40 % des transactions, commission de l'ordre de 0,01 %. Intérêt : l'anonymat."},{"id":"glo:59","m":"produits-derives","ch":"Glossaire","l":"l5","type":"carte","q":"ISO 4217","d":"Norme de codification des devises","ex":"Trois lettres : les deux premières du pays + la première de la devise. L'EUR fait exception."},{"id":"glo:60","m":"produits-derives","ch":"Glossaire","l":"l6","type":"carte","q":"Incertain","d":"Cotation à l'incertain","ex":"Prix d'une unité de monnaie étrangère en monnaie locale : 1 ME = x ML."},{"id":"glo:61","m":"produits-derives","ch":"Glossaire","l":"l6","type":"carte","q":"Certain","d":"Cotation au certain","ex":"Prix d'une unité de monnaie locale en monnaie étrangère : 1 ML = x' ME. Pratiquée en Grande-Bretagne, zone euro, Canada (sauf contre USD), Australie, Nouvelle-Zélande."},{"id":"glo:62","m":"produits-derives","ch":"Glossaire","l":"l6","type":"carte","q":"Spread","d":"Écart acheteur-vendeur","ex":"La marge de la banque. (cours vendeur − cours acheteur) / cours acheteur × 100. Généralement 10 à 50 points, jusqu'à 100."},{"id":"glo:63","m":"produits-derives","ch":"Glossaire","l":"l6","type":"carte","q":"Figure","d":"Partie stable d'une cotation","ex":"Partie entière + les deux premières décimales. Dans 0,9268, la figure est 0,92."},{"id":"glo:64","m":"produits-derives","ch":"Glossaire","l":"l6","type":"carte","q":"Pip","d":"Point de cotation","ex":"Le quatrième chiffre après la virgule. Dans 0,9268 − 0,9280, 68 et 80 sont les points."},{"id":"glo:65","m":"produits-derives","ch":"Glossaire","l":"l7","type":"carte","q":"Cross rate","d":"Cours croisé","ex":"Cours reconstitué via une monnaie pivot : (A/B) = (A/C) × (C/B). En double cotation, les acheteurs se multiplient entre eux et les vendeurs entre eux. Le USD est le pivot naturel."},{"id":"glo:66","m":"produits-derives","ch":"Glossaire","l":"l4","type":"carte","q":"Scalper","d":"Spéculateur à très court terme","ex":"Intervient sur quelques minutes."},{"id":"glo:67","m":"produits-derives","ch":"Glossaire","l":"l3","type":"carte","q":"Front office","d":"Service de négociation","ex":"Les cambistes clientèle (salers) et les teneurs de marché. Le middle office assure les contrôles, le back office l'administratif et le comptable."},{"id":"glo:68","m":"produits-derives","ch":"Glossaire","l":"l2","type":"carte","q":"CALPERS","d":"California Public Employees' Retirement System","ex":"Fonds de pension des employés de l'État de Californie — exemple d'institution financière non bancaire."},{"id":"glo:69","m":"marketing-numerique","ch":"Glossaire","l":"l1","type":"carte","q":"DMP","d":"Data Management Platform","ex":"Chaîne industrialisée : données brutes → filtre/nettoyage → feature selection → statistiques/ML → valeur métier."},{"id":"glo:70","m":"marketing-numerique","ch":"Glossaire","l":"l1","type":"carte","q":"CRM","d":"Customer Relationship Management","ex":"Gestion de la relation client, alimentée par les données constatées et inférées."},{"id":"glo:71","m":"marketing-numerique","ch":"Glossaire","l":"l2","type":"carte","q":"AMA","d":"American Marketing Association","ex":"Auteur de la définition de référence : comprendre les besoins d'un marché et y répondre en délivrant de la valeur."},{"id":"glo:72","m":"marketing-numerique","ch":"Glossaire","l":"l4","type":"carte","q":"PESTEL","d":"Politique, Économique, Socio-culturel, Technologique, Écologique, Légal","ex":"Les six familles de facteurs du macro-environnement."},{"id":"glo:73","m":"marketing-numerique","ch":"Glossaire","l":"l4","type":"carte","q":"Porter","d":"Les 5+1 forces de Porter","ex":"Rivalité du secteur, pouvoir des fournisseurs, pouvoir des clients, entrants potentiels, substituts — plus l'État en sixième force."},{"id":"glo:74","m":"marketing-numerique","ch":"Glossaire","l":"l4","type":"carte","q":"SWOT","d":"Strengths, Weaknesses, Opportunities, Threats","ex":"Forces et faiblesses sont internes, opportunités et menaces externes. À croiser, pas à lister. Test : si l'entreprise peut agir dessus, c'est interne."},{"id":"glo:75","m":"marketing-numerique","ch":"Glossaire","l":"l5","type":"carte","q":"DAS","d":"Domaine d'Activité Stratégique","ex":"Résultat de la segmentation stratégique, qui partitionne une organisation."},{"id":"glo:76","m":"marketing-numerique","ch":"Glossaire","l":"l5","type":"carte","q":"STP","d":"Segmentation, Ciblage, Positionnement","ex":"L'enchaînement du marketing stratégique : découper, choisir, puis occuper une place dans l'esprit du client."},{"id":"glo:77","m":"marketing-numerique","ch":"Glossaire","l":"l6","type":"carte","q":"Kapferer","d":"Le losange de Kapferer","ex":"Quatre questions du positionnement : Qui ? (cible) Pourquoi ? (bénéfices) Quand ? (moments d'usage) Contre qui ? (concurrents directs, substituts compris)."},{"id":"glo:78","m":"marketing-numerique","ch":"Glossaire","l":"l6","type":"carte","q":"Ansoff","d":"La matrice d'Ansoff","ex":"Croise produit et marché : pénétration, développement par les produits, développement par les marchés, diversification (la plus risquée). Le mot après « développement par » désigne ce qui est nouveau."},{"id":"glo:79","m":"marketing-numerique","ch":"Glossaire","l":"l7","type":"carte","q":"4P","d":"Produit, Prix, Distribution (Place), Communication (Promotion)","ex":"Le marketing mix. Chaque P doit découler du positionnement et se renforcer avec les autres."},{"id":"glo:80","m":"marketing-numerique","ch":"Glossaire","l":"l7","type":"carte","q":"Écrémage","d":"Politique de prix élevé","ex":"Vendre au prix fort à une cible réduite, optique de profit. Position de leader sur un marché nouveau."},{"id":"glo:81","m":"marketing-numerique","ch":"Glossaire","l":"l7","type":"carte","q":"Pénétration","d":"Politique de prix bas","ex":"Vendre à faible marge, optique de volume. Position de challengeur sur un marché mature."},{"id":"glo:82","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"KPI","d":"Key Performance Indicator","ex":"Trois familles : vente (volume, CA, part de marché), comportement (pénétration, fréquence, panier moyen), attitude (notoriété, image, préférence, intention)."},{"id":"glo:83","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"RSE","d":"Responsabilité Sociétale des Entreprises","ex":"Le marketing responsable l'intègre de façon proactive et à long terme, là où le traditionnel reste réactif et court-termiste."},{"id":"glo:84","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"ODD","d":"Objectifs de Développement Durable","ex":"Les 17 objectifs de l'ONU, l'un des trois cadres de référence de la durabilité avec les limites planétaires et le donut."},{"id":"glo:85","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"Greenwashing","d":"Écoblanchiment","ex":"Promesse environnementale non tenue ou non prouvée. L'antidote : la preuve documentée plutôt que la promesse seule."},{"id":"glo:86","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"Choice editing","d":"Édition des choix","ex":"Sélectionner ou modifier les choix disponibles plutôt qu'informer : ne référencer que des produits certifiés, réorganiser un buffet."},{"id":"glo:87","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"ADEME","d":"Agence de la Transition Écologique","ex":"Source du comparatif marketing traditionnel / marketing responsable et des 5 étapes du marketing responsable."},{"id":"glo:88","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"Donut","d":"Le donut de Kate Raworth","ex":"Un plafond environnemental et un plancher social délimitant l'espace sûr et juste pour l'humanité."},{"id":"glo:89","m":"marketing-numerique","ch":"Glossaire","l":"l9","type":"carte","q":"Limites planétaires","d":"Les 9 limites planétaires","ex":"Cadre de Johan Rockström et Will Steffen, l'un des trois repères de la durabilité cités dans le cours."},{"id":"glo:90","m":"marketing-numerique","ch":"Glossaire","l":"l8","type":"carte","q":"Storytelling","d":"Mise en récit","ex":"Protagoniste, musique de début, intrigue, adversité, personnages secondaires, chute, musique de fin — et beaucoup d'émotion et de non verbal."},{"id":"glo:91","m":"marketing-numerique","ch":"Glossaire","l":"l3","type":"carte","q":"Marché générique","d":"Le besoin sous-jacent","ex":"Répond à « quel besoin ? ». Le principal répond à « quel produit ? », le substitut à « qu'est-ce qui peut le remplacer ? », le complémentaire à « qu'est-ce qui accompagne ? », le support à « qu'est-ce qui facilite ? »."},{"id":"glo:92","m":"marketing-numerique","ch":"Glossaire","l":"l3","type":"carte","q":"NCR","d":"Non-consommateur relatif","ex":"Pourrait consommer si un frein était levé : c'est la réserve de croissance."},{"id":"glo:93","m":"fiscalite-particulier","ch":"Glossaire","l":"l1","type":"carte","q":"IR","d":"Impôt sur le revenu","ex":"Impôt d'État, annuel, direct, déclaratif, personnel, global et progressif. Il frappe le revenu net global du foyer fiscal (CGI, art. 1 A)."},{"id":"glo:94","m":"fiscalite-particulier","ch":"Glossaire","l":"l11","type":"carte","q":"RNGI","d":"Revenu Net Global Imposable","ex":"La base d'imposition. Quatrième et dernière étape : revenu net global moins les abattements spéciaux."},{"id":"glo:95","m":"fiscalite-particulier","ch":"Glossaire","l":"l11","type":"carte","q":"RBG","d":"Revenu Brut Global","ex":"Deuxième étape : revenu global moins les déficits globaux des six années antérieures, imputés du plus ancien au plus récent."},{"id":"glo:96","m":"fiscalite-particulier","ch":"Glossaire","l":"l11","type":"carte","q":"RNG","d":"Revenu Net Global","ex":"Troisième étape : revenu brut global moins les charges déductibles. Ces charges ne peuvent ni créer ni augmenter un déficit global."},{"id":"glo:97","m":"fiscalite-particulier","ch":"Glossaire","l":"l11","type":"carte","q":"RG","d":"Revenu Global","ex":"Première étape : somme algébrique des revenus et déficits nets catégoriels. S'il est négatif, un déficit global est constaté, reportable six ans."},{"id":"glo:98","m":"fiscalite-particulier","ch":"Glossaire","l":"l6","type":"carte","q":"PAC","d":"Personne À Charge","ex":"De droit (enfant mineur, enfant infirme à tout âge, mineur recueilli, personne invalide sous le toit) ou par rattachement sur demande."},{"id":"glo:99","m":"fiscalite-particulier","ch":"Glossaire","l":"l9","type":"carte","q":"Case T","d":"Parent isolé","ex":"Demi-part supplémentaire pour le célibataire, divorcé ou séparé qui vit seul ET assume seul la charge effective de la première personne à charge."},{"id":"glo:100","m":"fiscalite-particulier","ch":"Glossaire","l":"l2","type":"carte","q":"PAS","d":"Prélèvement À la Source","ex":"En vigueur depuis le 1er janvier 2019. Il change le moment du paiement, pas le caractère déclaratif de l'impôt."},{"id":"glo:101","m":"fiscalite-particulier","ch":"Glossaire","l":"l3","type":"carte","q":"SIPNR","d":"Service des Impôts des Particuliers des Non Résidents","ex":"Gère les dossiers des personnes domiciliées à l'étranger percevant des revenus de source française, quelle que soit leur nationalité."},{"id":"glo:102","m":"fiscalite-particulier","ch":"Glossaire","l":"l2","type":"carte","q":"2042","d":"Déclaration d'ensemble des revenus","ex":"Quatre pages : état civil, situation familiale et personnes à charge, revenus, puis charges et crédits d'impôt."},{"id":"glo:103","m":"fiscalite-particulier","ch":"Glossaire","l":"l3","type":"carte","q":"2047","d":"Déclaration des revenus encaissés à l'étranger","ex":"Annexée à la 2042 par les contribuables domiciliés en France qui perçoivent des revenus de source étrangère."},{"id":"glo:104","m":"fiscalite-particulier","ch":"Glossaire","l":"l1","type":"carte","q":"CGI","d":"Code Général des Impôts","ex":"Art. 1 A : définition de l'IR. Art. 4 A et 4 B : territorialité et domicile fiscal. Art. 13 et 156 : base d'imposition."},{"id":"glo:105","m":"fiscalite-particulier","ch":"Glossaire","l":"l1","type":"carte","q":"BIC","d":"Bénéfices Industriels et Commerciaux","ex":"Une des huit catégories de revenus. La location meublée en relève, à la différence de la location nue."},{"id":"glo:106","m":"fiscalite-particulier","ch":"Glossaire","l":"l1","type":"carte","q":"BNC","d":"Bénéfices Non Commerciaux","ex":"Revenus des professions libérales et revenus assimilés. Une des huit catégories de l'article 1 A."},{"id":"glo:107","m":"fiscalite-particulier","ch":"Glossaire","l":"l1","type":"carte","q":"RCM","d":"Revenus de Capitaux Mobiliers","ex":"Dividendes, intérêts et produits de placement. Une des huit catégories de l'article 1 A."},{"id":"glo:108","m":"fiscalite-particulier","ch":"Glossaire","l":"l11","type":"carte","q":"Micro-foncier","d":"Régime simplifié des revenus fonciers","ex":"Applicable jusqu'à 15 000 € de recettes : abattement forfaitaire de 30 %, soit recettes × 0,70. Au-delà, régime réel obligatoire."},{"id":"glo:109","m":"fiscalite-particulier","ch":"Glossaire","l":"l6","type":"carte","q":"CMI","d":"Carte Mobilité Inclusion","ex":"Mention « invalidité » : elle rend à charge une personne vivant sous le toit, et ouvre une demi-part supplémentaire."},{"id":"glo:110","m":"fiscalite-particulier","ch":"Glossaire","l":"l7","type":"carte","q":"Rattachement","d":"Option des enfants majeurs","ex":"Demande annuelle et en principe irrévocable. Moins de 21 ans, ou moins de 25 ans si études, apprécié au 1er janvier."},{"id":"glo:111","m":"droits-particuliers","ch":"Glossaire","l":"l3","type":"carte","q":"Infans conceptus","d":"L'enfant conçu est tenu pour né","ex":"L'enfant simplement conçu est réputé né chaque fois qu'il y va de son intérêt, s'il naît vivant et viable. Conception présumée du 300e au 180e jour avant la naissance (art. 311 C. civ.)."},{"id":"glo:112","m":"droits-particuliers","ch":"Glossaire","l":"l1","type":"carte","q":"Personnalité juridique","d":"Aptitude à avoir des droits et des obligations","ex":"Reconnue à tout être humain né vivant et viable ; elle prend fin au décès."},{"id":"glo:113","m":"droits-particuliers","ch":"Glossaire","l":"l2","type":"carte","q":"Enfant sans vie","d":"Mort-né ou né non viable","ex":"Acte d'enfant sans vie : prénoms et, depuis 2021, nom de famille possibles, mais aucun effet juridique."},{"id":"glo:114","m":"droits-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"RC","d":"Répertoire civil","ex":"Registre tenu par le tribunal où est inscrite la présomption d'absence ; la mention « RC » figure en marge de l'acte de naissance."},{"id":"glo:115","m":"droits-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"Présomption d'absence","d":"Première étape de l'absence","ex":"Constatée par le juge des contentieux de la protection. L'absent est présumé vivant : mariage maintenu, un représentant gère ses biens."},{"id":"glo:116","m":"droits-particuliers","ch":"Glossaire","l":"l6","type":"carte","q":"Jugement déclaratif d'absence","d":"Seconde étape de l'absence","ex":"10 ans après la présomption, ou 20 ans sans nouvelles ; au moins 1 an après publication. Produit les effets d'un décès. Si l'absent revient, son mariage reste dissous."},{"id":"glo:117","m":"droits-particuliers","ch":"Glossaire","l":"l7","type":"carte","q":"Jugement déclaratif de décès","d":"Issue de la disparition","ex":"Corps non retrouvé, mort quasi certaine (naufrage, crash, catastrophe) : le tribunal judiciaire peut être saisi immédiatement."},{"id":"glo:118","m":"droits-particuliers","ch":"Glossaire","l":"l5","type":"carte","q":"Droit moral","d":"Volet perpétuel du droit d'auteur","ex":"Paternité et respect de l'œuvre, perpétuel et transmis aux héritiers."},{"id":"glo:119","m":"etudes-marche","ch":"Glossaire","l":"l8","type":"carte","q":"Population mère","d":"Qui interroger","ex":"« L'ensemble des personnes possédant les informations désirées pour répondre aux objectifs d'une étude ». On en tire un échantillon dont on généralise les résultats."},{"id":"glo:120","m":"etudes-marche","ch":"Glossaire","l":"l2","type":"carte","q":"Données secondaires","d":"Données qui existent déjà","ex":"Non produites pour l'étude : internes ou externes (dont les panels). Exploitées par l'étude documentaire."},{"id":"glo:121","m":"etudes-marche","ch":"Glossaire","l":"l3","type":"carte","q":"Insight","d":"Découverte marketing","ex":"Réalité pertinente, concrète et jusque-là inexploitée sur une cible, obtenue par une analyse subjective et approfondie des données."},{"id":"glo:122","m":"etudes-marche","ch":"Glossaire","l":"l4","type":"carte","q":"Entretien semi-directif","d":"L'entretien le plus utilisé","ex":"Guide souple : l'interviewé développe ses idées dans l'ordre qu'il veut, l'enquêteur relance et recentre. Allie cadre et spontanéité."},{"id":"glo:123","m":"etudes-marche","ch":"Glossaire","l":"l4","type":"carte","q":"Saturation","d":"Quand arrêter les entretiens","ex":"On s'arrête quand un nouvel entretien n'apporte plus d'information nouvelle (en pratique 10 à 20 personnes, 15 à 30 selon une diapositive)."},{"id":"glo:124","m":"etudes-marche","ch":"Glossaire","l":"l5","type":"carte","q":"Phase de purge","d":"Mise en confiance","ex":"Début d'entretien où l'on lève les craintes du répondant pour le mettre en confiance, avant d'aborder les thèmes."},{"id":"glo:125","m":"etudes-marche","ch":"Glossaire","l":"l6","type":"carte","q":"Focus group","d":"Réunion de groupe","ex":"6 à 10 personnes et un animateur. Deux groupes ≈ 30 entretiens individuels. Biais : prise de parole dominante, influence mutuelle."},{"id":"glo:126","m":"etudes-marche","ch":"Glossaire","l":"l7","type":"carte","q":"Verbatim","d":"Citation du répondant","ex":"Phrase spontanée, citée mot pour mot, qui résume une opinion ou une perception fréquente."},{"id":"glo:127","m":"etudes-marche","ch":"Glossaire","l":"l8","type":"carte","q":"Quotas","d":"Méthode d'échantillonnage empirique","ex":"Groupes fixés a priori selon des caractéristiques connues de la population (48 % d'hommes → 480 sur 1 000). Contrôle précis, mais biais de sélection."},{"id":"glo:128","m":"etudes-marche","ch":"Glossaire","l":"l9","type":"carte","q":"Marge d'erreur","d":"Précision d'un sondage","ex":"e = t × √(p × q ÷ n), avec t = 1,96 à 95 %. Pour 1 000 personnes et p = 50 % : ± 3,1 points. Diviser e par 2 exige 4 fois plus de répondants."},{"id":"glo:129","m":"etudes-marche","ch":"Glossaire","l":"l10","type":"carte","q":"Biais de cadrage","d":"La formulation change la réponse","ex":"Tversky et Kahneman : le même programme est choisi par 72 % en cadre positif (« 200 sauvées ») et 22 % en cadre négatif (« 400 mourront »)."},{"id":"glo:130","m":"etudes-marche","ch":"Glossaire","l":"l10","type":"carte","q":"Échelle de Likert","d":"Degré d'accord","ex":"De « pas du tout d'accord » à « tout à fait d'accord ». Éviter un « sans opinion » au milieu : il rompt l'échelle."},{"id":"glo:131","m":"etudes-marche","ch":"Glossaire","l":"l12","type":"carte","q":"Prétest","d":"Étape 3 de l'enquête","ex":"Questionnaire soumis en face à face à une dizaine de personnes de la population mère, qui commentent leurs choix à voix haute."}];
